/* 自动生成，请勿手工修改。来源：DSH math/math-stats；重新生成：node scripts/build-learn-content.mjs */
module.exports = [{"id":"m-sta-shuju-shouji","title":"数据的收集、整理与描述","subtitle":"人教版七下 · 第12章 数据的收集、整理与描述","grade":"7b","tags":["统计与概率","数据的收集、整理与描述"],"blocks":[{"type":"note","title":"教材章节","text":"人教版七下 · 第12章 数据的收集、整理与描述"},{"type":"note","title":"一句话概述","text":"认识全面调查与抽样调查，掌握总体、个体、样本与频数、频率，会读三种统计图。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"想知道全班同学最喜欢哪种水果，一个一个问就是全面调查；想知道全市中学生的睡眠时间，不可能人人问，就只能抽样。统计的第一步，是决定「问谁」。","walk":["全面调查要考察全体对象，结果准确但费时费力；抽样调查只考察一部分，省时省力但要注意样本的代表性。","总体是所要考察的全体对象，样本是从中抽取的一部分，样本容量是样本中个体的数目。","整理数据常用频数分布表和频数分布直方图，组距和组数要合适，才能看出数据的分布规律。"],"try":"统计家里一周每天扔掉的垃圾袋数量，做成表格，再画一张简单的条形图，看看哪天最多。","use":["抽样调查题先判断「样本是否有代表性」，再判断「样本容量是否足够」。","频数分布直方图的纵轴是频数除以组距，别直接把频数当高度。"]},{"type":"h","text":"先看情境：要统计什么，数据从哪来"},{"type":"p","text":"统计的第一步是说清考察对象。要考察的全体对象叫做总体，组成总体的每一个考察对象叫做个体；只抽取一部分个体进行调查时，这些个体组成一个样本，样本中个体的数目叫做样本容量。例如要了解某校七年级 800 名学生的视力情况，考察的对象是「视力情况」这一数据，总体就是这 800 名学生的视力情况，样本容量 n=50，只是一个数、不带单位。"},{"type":"figure","figure":{"id":"fig-sta-shouji-s1","title":"总体、样本与个体的关系","caption":"总体是 800 名学生的视力情况，样本是随机抽取的 50 名学生","view":"wide","alt":"总体与样本示意图：左边方框内写总体是 800 名学生的视力情况，箭头向右指向小方框，小方框内写样本是抽取的 50 名学生，下方注明个体是每一名学生的视力情况、样本容量是 50","prims":[{"t":"rect","x":6,"y":14,"w":38,"h":26,"tone":"main"},{"t":"text","x":25,"y":23,"text":"总体","size":3.6,"anchor":"middle"},{"t":"text","x":25,"y":31,"text":"800 名学生的视力情况","size":2.8,"anchor":"middle"},{"t":"arrow","x1":45,"y1":27,"x2":55,"y2":27,"label":"抽取"},{"t":"rect","x":57,"y":19,"w":24,"h":16,"tone":"accent","fill":true},{"t":"text","x":69,"y":24,"text":"样本","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":69,"y":31,"text":"50 名学生","size":2.8,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":48,"text":"个体：组成总体的每一个考察对象，即每一名学生的视力情况","size":2.8,"anchor":"middle"},{"t":"text","x":50,"y":56,"text":"样本容量 = 50，只是一个数，不能带单位","size":2.8,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"考察的对象是「数据」而不是「人」本身，所以总体要写成「800 名学生的视力情况」，不能写成「800 名学生」。"},{"type":"h","text":"抓住哪个量：频数与频率"},{"type":"p","text":"数据整理分组后，落在某一组的数据个数叫做这一组的频数 m，频数与数据总数的比叫做这一组的频率，即 f=(m)/(n)。频率是一个比值，没有单位，通常写成小数或百分数。各组频率之和恒等于 1，可以用它检验整理是否出错。"},{"type":"figure","figure":{"id":"fig-sta-shouji-s2","title":"喜爱各类球类运动的频数条形图","caption":"频数是各组的人数，频率是频数与总数 50 的比","view":"square","alt":"条形统计图：横轴是篮球、足球、乒乓球、羽毛球四个类别，纵轴是人数，四类人数依次为 15、12、18、5，其中乒乓球 18 人最高，四类频率依次为 0.30、0.24、0.36、0.10","prims":[{"t":"axis","x":16,"y":82,"w":68,"h":60,"xLabel":"项目","yLabel":"人数","origin":true,"xTicks":[{"at":0.13,"label":"篮球"},{"at":0.38,"label":"足球"},{"at":0.63,"label":"乒乓球"},{"at":0.88,"label":"羽毛球"}],"yTicks":[{"at":0.25,"label":"5"},{"at":0.5,"label":"10"},{"at":0.75,"label":"15"},{"at":1,"label":"20"}]},{"t":"rect","x":18.5,"y":37,"w":12,"h":45},{"t":"rect","x":35.5,"y":46,"w":12,"h":36},{"t":"rect","x":52.5,"y":28,"w":12,"h":54,"tone":"accent","fill":true},{"t":"rect","x":69.5,"y":67,"w":12,"h":15},{"t":"text","x":24.5,"y":34,"text":"15","size":3.2,"anchor":"middle"},{"t":"text","x":41.5,"y":43,"text":"12","size":3.2,"anchor":"middle"},{"t":"text","x":58.5,"y":25,"text":"18","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":75.5,"y":64,"text":"5","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":94,"text":"频率 = 频数 ÷ 总数 50：0.30、0.24、0.36、0.10，和为 1","size":2.8,"anchor":"middle"}]}},{"type":"note","title":"","text":"频率与频数的关系是「知二求一」：频率 = 频数 ÷ 总数，频数 = 总数 × 频率，总数 = 频数 ÷ 频率。"},{"type":"h","text":"建立关系：百分比与扇形圆心角"},{"type":"p","text":"同一个调查结果还可以画成扇形统计图。某一部分所对的圆心角等于 360° 乘该部分所占的百分比，即圆心角 =360°×(m)/(n)。各部分圆心角之和为 360°，百分比之和为 100%，这两个和都可以用来检验计算。"},{"type":"figure","figure":{"id":"fig-sta-shouji-s3","title":"喜爱各类球类运动的扇形统计图","caption":"圆心角 = 百分比 × 360°，四个扇形的圆心角之和为 360°","view":"square","alt":"扇形统计图：乒乓球占 36% 对应圆心角 129.6 度，篮球占 30% 对应 108 度，足球占 24% 对应 86.4 度，羽毛球占 10% 对应 36 度，四部分圆心角之和为 360 度","prims":[{"t":"sector","cx":50,"cy":44,"r":27,"from":0,"to":108,"tone":"main","label":"篮球 30%"},{"t":"sector","cx":50,"cy":44,"r":27,"from":108,"to":194.4,"tone":"ok","label":"足球 24%"},{"t":"sector","cx":50,"cy":44,"r":27,"from":194.4,"to":324,"tone":"accent","fill":true,"label":"乒乓球 36%"},{"t":"sector","cx":50,"cy":44,"r":27,"from":324,"to":360,"tone":"muted","label":"羽毛球 10%"},{"t":"text","x":50,"y":88,"text":"108° + 86.4° + 129.6° + 36° = 360°","size":3,"anchor":"middle"},{"t":"text","x":50,"y":95,"text":"百分比之和 30% + 24% + 36% + 10% = 100%","size":3,"anchor":"middle"}]}},{"type":"note","title":"","text":"圆心角只能用 360° 乘百分比，不能把百分比直接当成角度，例如 30% 对应的是 108°，不是 30°。"},{"type":"h","text":"换个情境再想一遍：样本变了，结论怎么变"},{"type":"p","text":"用样本估计总体时，结论的可靠程度取决于样本是否随机、容量是否足够。把样本容量由 20 增大到 320，并在各班随机抽取，抽样得到的频率会越来越稳定地接近总体真实比例 0.30。若只调查一个班，样本容量太小又缺乏代表性，用它去乘总体数量得到的估计值会明显偏离真实情况。"},{"type":"figure","figure":{"id":"fig-sta-shouji-s4","title":"抽样频率随样本容量增大趋于稳定","caption":"样本容量越大，抽样得到的频率越接近总体的真实比例","view":"square","alt":"折线统计图：横轴是样本容量 20、40、80、160、320，纵轴是频率，折线依次经过 0.45、0.33、0.30、0.31、0.30，随着样本容量增大逐渐靠近 0.30 的参考线","prims":[{"t":"axis","x":16,"y":82,"w":68,"h":56,"xLabel":"样本容量（名）","yLabel":"频率","origin":true,"xTicks":[{"at":0.1,"label":"20"},{"at":0.3,"label":"40"},{"at":0.5,"label":"80"},{"at":0.7,"label":"160"},{"at":0.9,"label":"320"}],"yTicks":[{"at":0.2,"label":"0.1"},{"at":0.4,"label":"0.2"},{"at":0.6,"label":"0.3"},{"at":0.8,"label":"0.4"},{"at":1,"label":"0.5"}]},{"t":"line","x1":16,"y1":48.4,"x2":84,"y2":48.4,"dashed":true,"tone":"muted"},{"t":"text","x":87,"y":44,"text":"0.30","size":3,"anchor":"middle","tone":"muted"},{"t":"curve","points":[[22.8,31.6],[36.4,45],[50,48.4],[63.6,47.3],[77.2,48.4]],"tone":"accent"},{"t":"dot","x":22.8,"y":31.6,"tone":"accent"},{"t":"dot","x":36.4,"y":45,"tone":"accent"},{"t":"dot","x":50,"y":48.4,"tone":"accent"},{"t":"dot","x":63.6,"y":47.3,"tone":"accent"},{"t":"dot","x":77.2,"y":48.4,"tone":"accent"},{"t":"text","x":50,"y":94,"text":"样本容量从 20 增到 320，频率由 0.45 稳定到 0.30 附近","size":2.8,"anchor":"middle"}]}},{"type":"note","title":"","text":"抽样调查的三条要求：随机抽取、样本有代表性、样本容量适当，缺一条都会让估计失真。"},{"type":"h","text":"核心概念"},{"type":"p","text":"全面调查（普查）：考察全体对象的调查叫做全面调查。当调查范围较小、不具有破坏性、需要得到准确结果时采用，如全国人口普查、全班同学的身高测量。"},{"type":"p","text":"抽样调查：只抽取一部分对象进行调查，然后根据调查数据推断全体对象的情况，这样的调查叫做抽样调查。当总体数量很大、或调查具有破坏性时采用。"},{"type":"p","text":"总体、个体、样本、样本容量：要考察的全体对象叫做总体；组成总体的每一个考察对象叫做个体；被抽取的那些个体组成一个样本；样本中个体的数目叫做样本容量。注意考察的是「数据」而不是人本身，例如总体是 800 名学生的视力情况。"},{"type":"p","text":"频数与频率：落在各组中的数据个数叫做该组的频数；频数与数据总数的比叫做该组的频率，即频率 =(频数)/(数据总数)。所有各组的频率之和等于 1。"},{"type":"p","text":"抽样调查的合理性：抽取样本时必须随机、具有代表性，样本容量要适当。只调查男生、只调查成绩好的同学或只调查一个班，都会使样本失去代表性，用这样的样本估计总体会产生较大偏差。"},{"type":"p","text":"三种统计图的作用：条形统计图便于看出各类别的频数多少；扇形统计图便于看出各部分占总体的百分比；折线统计图便于看出数据的变化趋势。三种图各有用途，不能互相替代。"},{"type":"p","text":"频数分布直方图：把数据按组距分成若干组，用等宽的矩形表示各组的频数，矩形的高表示频数，各矩形之间紧密相连、没有空隙，数据总数等于各组频数之和。"},{"type":"note","title":"中考考法","text":"调查方式与样本概念辨析\n选择题常考全面调查与抽样调查的选择、总体个体样本与样本容量的判断，破坏性调查只能抽样、样本容量不带单位是必查点。"},{"type":"note","title":"中考考法","text":"频数、频率与扇形圆心角互求\n常在解答题中结合频数分布表出现，由总数、频数、频率知二求一，再画扇形图，可用各组频率之和为 1 自检。"},{"type":"note","title":"中考考法","text":"用样本估计总体\n以抽样调查为背景，用样本的频率乘总体数量估计总体中的个数，答题要写明「估计」并保留乘总数的过程。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["频率公式","频率等于该组的频数 m 与数据总数 n 的比。","各组的频率之和等于 1；频率是一个比值，没有单位，通常写成小数或百分数。"],["百分比公式","某一组所占的百分比等于该组频数除以数据总数再乘 100%。","百分比的分子分母是同类数量，结果不带单位。"],["扇形统计图的圆心角","扇形统计图中每一部分所对圆心角的度数，等于 360° 乘该部分所占的百分比。","各部分圆心角之和等于 360°，各扇形面积之和是整个圆。"]]},{"type":"note","title":"例题","text":"某校七年级共有 800 名学生，为了解他们的视力情况，从中随机抽取 50 名学生进行视力检测。请指出这次调查中的总体、个体、样本与样本容量。"},{"type":"figure","figure":{"id":"fig-sta-shouji-e1","title":"视力调查中的总体、个体、样本与样本容量","caption":"考察的对象是「视力情况」这一数据，不是学生本身","view":"wide","alt":"对照示意图：左上方框写「总体：800 名学生」并注明不规范，右上方框写「总体：800 名学生的视力情况」并注明规范，下方左框写样本是抽取的 50 名学生的视力情况，下方右框写样本容量是 50、不带单位","prims":[{"t":"rect","x":4,"y":12,"w":40,"h":20,"dashed":true,"tone":"danger"},{"t":"text","x":24,"y":19,"text":"总体：800 名学生","size":3,"anchor":"middle","tone":"danger"},{"t":"text","x":24,"y":27,"text":"不规范","size":2.6,"anchor":"middle","tone":"danger"},{"t":"rect","x":52,"y":12,"w":44,"h":20,"tone":"main"},{"t":"text","x":74,"y":19,"text":"总体：800 名学生的视力情况","size":2.8,"anchor":"middle"},{"t":"text","x":74,"y":27,"text":"规范","size":2.6,"anchor":"middle","tone":"ok"},{"t":"rect","x":4,"y":38,"w":44,"h":16,"tone":"accent","fill":true},{"t":"text","x":26,"y":46,"text":"样本：抽取的 50 名学生的视力情况","size":2.6,"anchor":"middle","tone":"accent"},{"t":"rect","x":52,"y":38,"w":44,"h":16,"tone":"accent","fill":true},{"t":"text","x":74,"y":46,"text":"样本容量：50（不带单位）","size":2.8,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["判断考察的对象：调查目的是了解学生的视力情况，所以考察的是「视力情况」这一数据，而不是学生本人。","总体：该校七年级 800 名学生的视力情况。","个体：该校七年级每一名学生的视力情况。","样本：被抽取的 50 名学生的视力情况。","样本容量：被抽取的个体数目，即 50。"]},{"type":"p","text":"答案：总体是该校七年级 800 名学生的视力情况；个体是该校七年级每一名学生的视力情况；样本是被抽取的 50 名学生的视力情况；样本容量是 50。"},{"type":"note","title":"方法小结","text":"样本容量只是一个数目，不能带单位，写成「50 名」是错误的。"},{"type":"note","title":"例题","text":"某班 40 名学生一分钟跳绳的次数中，落在 100 次到 120 次这一组的有 12 人。求这一组的频率，以及该组在扇形统计图中所对圆心角的度数。"},{"type":"figure","figure":{"id":"fig-m-sta-shouji-1","title":"跳绳次数扇形统计图","caption":"40 人中该组有 12 人，占 30%，所对圆心角为 108°","view":"square","alt":"扇形统计图：从圆心向右和向左上引两条半径，夹角为 108 度的扇形占整个圆的 30%，其余部分占 70%","prims":[{"t":"circle","cx":50,"cy":42,"r":20},{"t":"line","x1":50,"y1":42,"x2":70,"y2":42,"tone":"accent"},{"t":"line","x1":50,"y1":42,"x2":43.8,"y2":23,"tone":"accent"},{"t":"arc","cx":50,"cy":42,"r":24,"from":0,"to":108,"tone":"accent"},{"t":"text","x":58,"y":31,"text":"30%","size":3.6,"anchor":"middle","tone":"accent"},{"t":"text","x":43,"y":52,"text":"70%","size":3.6,"anchor":"middle"},{"t":"text","x":67,"y":21,"text":"108°","size":3.4,"tone":"accent"},{"t":"text","x":50,"y":74,"text":"40 人中该组 12 人，占 30%，圆心角 360°×30% = 108°","size":3.2,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["找出数据总数与频数：数据总数 n=40，该组的频数 m=12。","求频率：f=(m)/(n)=(12)/(40)=0.3。","把频率化为百分比：0.3=30%。","求圆心角：360°× 30%=108°。"]},{"type":"p","text":"答案：这一组的频率是 0.3（即 30%），在扇形统计图中所对的圆心角是 108°。"},{"type":"note","title":"方法小结","text":"频率乘 360° 得到圆心角；检验时可把所有组的圆心角相加，结果应为 360°。"},{"type":"note","title":"例题","text":"要了解一批灯泡的平均使用寿命，应该采用全面调查还是抽样调查？请说明理由。"},{"type":"figure","figure":{"id":"fig-sta-shouji-e3","title":"破坏性调查只能抽样","caption":"全面调查会把所有灯泡都损坏，抽样调查只损坏被抽到的那几只","view":"wide","alt":"对比示意图：左边方框内六只灯泡全部被点亮损坏，标注全面调查不可行；右边方框内六只灯泡中只有两只被抽到测试，其余完好，标注抽样调查可行","prims":[{"t":"rect","x":4,"y":16,"w":40,"h":30,"dashed":true,"tone":"danger"},{"t":"circle","cx":12,"cy":26,"r":3.4,"tone":"danger"},{"t":"circle","cx":24,"cy":26,"r":3.4,"tone":"danger"},{"t":"circle","cx":36,"cy":26,"r":3.4,"tone":"danger"},{"t":"circle","cx":12,"cy":38,"r":3.4,"tone":"danger"},{"t":"circle","cx":24,"cy":38,"r":3.4,"tone":"danger"},{"t":"circle","cx":36,"cy":38,"r":3.4,"tone":"danger"},{"t":"text","x":24,"y":10,"text":"全面调查：全部损坏，不可行","size":3,"anchor":"middle","tone":"danger"},{"t":"rect","x":56,"y":16,"w":40,"h":30,"dashed":true,"tone":"main"},{"t":"circle","cx":64,"cy":26,"r":3.4,"tone":"accent"},{"t":"circle","cx":76,"cy":26,"r":3.4},{"t":"circle","cx":88,"cy":26,"r":3.4},{"t":"circle","cx":64,"cy":38,"r":3.4},{"t":"circle","cx":76,"cy":38,"r":3.4,"tone":"accent"},{"t":"circle","cx":88,"cy":38,"r":3.4},{"t":"text","x":76,"y":10,"text":"抽样调查：只损坏抽到的，可行","size":3,"anchor":"middle"},{"t":"text","x":50,"y":56,"text":"抽到的 2 只做寿命试验，用样本的平均寿命估计这批灯泡","size":2.8,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["判断调查的性质：检测灯泡的使用寿命必须把灯泡点亮直到损坏，这种调查具有破坏性。","如果采用全面调查，所有灯泡都会被损坏，调查结束后这批灯泡就失去使用价值。","因此只能抽取一部分灯泡进行试验，用样本的平均寿命去估计这批灯泡的平均使用寿命。"]},{"type":"p","text":"答案：应该采用抽样调查。因为检测灯泡寿命具有破坏性，全面调查会使全部灯泡损坏。"},{"type":"note","title":"方法小结","text":"凡是具有破坏性的调查，或总体数量过大的调查，一般都采用抽样调查。"},{"type":"note","title":"例题","text":"某校为了解七年级 200 名学生一分钟跳绳的成绩情况，随机抽取了 40 名学生进行测试，把成绩分成五组，整理得到不完整的频数分布表：90≤ x<110 的频数为 6，110≤ x<130 的频数为 a，130≤ x<150 的频数为 16，150≤ x<170 的频数为 10，170≤ x<190 的频数为 4。求 a 的值、130≤ x<150 这一组的频率，并估计全校成绩在该组的学生人数。"},{"type":"figure","figure":{"id":"fig-m-sta-shouji-2","title":"40 名学生跳绳成绩频数分布直方图","caption":"各组频数依次为 6、4、16、10、4，130≤x<150 一组频率为 0.4","view":"wide","alt":"频数分布直方图：横轴是成绩分组，从 90 到 190 每 20 次一组，纵轴是频数，五组频数依次为 6、4、16、10、4，其中第三组频数 16 最高","prims":[{"t":"axis","x":12,"y":70,"w":76,"h":50,"xLabel":"成绩（次）","yLabel":"频数","origin":true,"xTicks":[{"at":0,"label":"90"},{"at":0.2,"label":"110"},{"at":0.4,"label":"130"},{"at":0.6,"label":"150"},{"at":0.8,"label":"170"},{"at":1,"label":"190"}],"yTicks":[{"at":0,"label":"0"},{"at":0.22,"label":"4"},{"at":0.44,"label":"8"},{"at":0.67,"label":"12"},{"at":0.89,"label":"16"}]},{"t":"rect","x":12,"y":53.3,"w":15.2,"h":16.7},{"t":"rect","x":27.2,"y":58.9,"w":15.2,"h":11.1},{"t":"rect","x":42.4,"y":25.6,"w":15.2,"h":44.4,"tone":"accent","fill":true},{"t":"rect","x":57.6,"y":42.2,"w":15.2,"h":27.8},{"t":"rect","x":72.8,"y":58.9,"w":15.2,"h":11.1},{"t":"text","x":19.6,"y":50.8,"text":"6","size":3.2,"anchor":"middle"},{"t":"text","x":34.8,"y":56.4,"text":"4","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":23.1,"text":"16","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":65.2,"y":39.7,"text":"10","size":3.2,"anchor":"middle"},{"t":"text","x":80.4,"y":56.4,"text":"4","size":3.2,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["由各组频数之和等于数据总数，得 6+a+16+10+4=40，解得 a=4。","求 130≤ x<150 这一组的频率：该组频数为 16，频率 =(16)/(40)=0.4。","检验：各组频率依次为 0.15,0.1,0.4,0.25,0.1，和为 0.15+0.1+0.4+0.25+0.1=1，计算无误。","用样本估计总体：200× 0.4=80（人）。"]},{"type":"p","text":"答案：a=4；130≤ x<150 这一组的频率为 0.4；估计全校成绩在该组的学生约有 80 人。"},{"type":"note","title":"方法小结","text":"频数分布表的核心关系是「各组频数之和等于数据总数」，先用它求未知频数，再求频率，最后用样本频率估计总体数量。"},{"type":"note","title":"例题","text":"某班有 20 名学生参加数学竞赛，成绩（单位：分）如下：12, 15, 18, 20, 22, 23, 25, 25, 26, 28, 30, 31, 33, 34, 35, 36, 38, 40, 42, 45。若组距取 7，请确定组数并完成频数分组。"},{"type":"figure","figure":{"id":"fig-sta-shouji-e5","title":"20 名学生竞赛成绩的频数分布直方图","caption":"极差 33、组距 7，分为 5 组，各组频数之和为 20","view":"square","alt":"频数分布直方图：横轴是成绩分组 12、19、26、33、40、47，纵轴是频数，五组频数依次为 3、5、4、5、3，频数之和为 20","prims":[{"t":"axis","x":16,"y":80,"w":70,"h":58,"xLabel":"成绩（分）","yLabel":"频数","origin":true,"xTicks":[{"at":0,"label":"12"},{"at":0.2,"label":"19"},{"at":0.4,"label":"26"},{"at":0.6,"label":"33"},{"at":0.8,"label":"40"},{"at":1,"label":"47"}],"yTicks":[{"at":0.33,"label":"2"},{"at":0.67,"label":"4"},{"at":1,"label":"6"}]},{"t":"rect","x":16,"y":51,"w":14,"h":29},{"t":"rect","x":30,"y":31.7,"w":14,"h":48.3,"tone":"accent","fill":true},{"t":"rect","x":44,"y":41.3,"w":14,"h":38.7},{"t":"rect","x":58,"y":31.7,"w":14,"h":48.3,"tone":"accent","fill":true},{"t":"rect","x":72,"y":51,"w":14,"h":29},{"t":"text","x":23,"y":48,"text":"3","size":3.2,"anchor":"middle"},{"t":"text","x":37,"y":28.7,"text":"5","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":51,"y":38.3,"text":"4","size":3.2,"anchor":"middle"},{"t":"text","x":65,"y":28.7,"text":"5","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":79,"y":48,"text":"3","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":93,"text":"12≤x<19 到 40≤x<47 共 5 组，各矩形等宽且没有空隙","size":2.8,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["找出最大值与最小值：最大值为 45，最小值为 12，极差为 45-12=33。","确定组数：(33)/(7)≈ 4.7，组数取不小于它的最小整数，所以分为 5 组。","依次划定组界并数出前两组频数：12≤ x<19 有 12, 15, 18，频数为 3；19≤ x<26 有 20, 22, 23, 25, 25，频数为 5。","继续数出其余各组：26≤ x<33 有 26, 28, 30, 31，频数为 4；33≤ x<40 有 33, 34, 35, 36, 38，频数为 5；40≤ x<47 有 40, 42, 45，频数为 3。检验：3+5+4+5+3=20。"]},{"type":"p","text":"答案：极差为 33，组数为 5；各组频数依次为 3, 5, 4, 5, 3，频数之和为 20，与数据总数一致。"},{"type":"note","title":"方法小结","text":"列频数分布表四步：求极差、定组数与组距、划定组界、数频数。组界要前后衔接且不重不漏，最后用频数之和检验。"},{"type":"list","title":"易错点","items":["总体、个体、样本都是指被考察的「数据」，不是「人」或「物体」本身，例如总体应说成「800 名学生的视力情况」。","样本容量只是一个数目，不带单位，写成「50 名」或「50 人」都是错的。","抽样必须随机抽取、样本要有代表性；只抽男生、只抽一个班或只抽成绩好的同学都会产生偏差。","具有破坏性的调查（如检测灯泡寿命、炮弹杀伤半径）不能用全面调查。","扇形统计图只反映各部分所占的百分比，不能直接读出具体数量，求具体数量要乘总数。","频数分布直方图的各矩形是连续、等宽的，与条形统计图中条形之间有间隔不同。"]},{"type":"list","title":"解题方法","items":["判断调查方式：先看调查是否具有破坏性、总体容量是否很大、是否需要精确结果，再决定用全面调查还是抽样调查。","求频数、频率与总数：频率 = 频数 ÷ 总数，频数 = 总数 × 频率，总数 = 频数 ÷ 频率，三者知二求一。","从统计图读数：条形图读频数，扇形图读百分比（求数量再乘总数），折线图读数据的变化趋势。","用样本估计总体：先由样本求出频率或百分比，再乘总体的数量，得到对总体情况的估计。","检验结果：各组频率之和应为 1，各百分比之和应为 100%，各扇形圆心角之和应为 360°。"]}],"questions":[{"id":"q-sta-shouji-1","type":"choice","stem":"下列调查中，适合采用全面调查（普查）的是（ ）","answer":"C","explain":"A、B、D 的调查对象数量很大或者调查具有破坏性，适合抽样调查；C 的调查范围小、需要准确结果，且不具有破坏性，适合全面调查。","options":["了解某市中学生每天的平均睡眠时间","检测一批炮弹的杀伤半径","了解某校七年级（1）班全体学生的身高情况","了解全国网民对某项政策的看法"],"difficulty":1,"tags":["全面调查","抽样调查"]},{"id":"q-sta-shouji-2","type":"fill","stem":"某校为了了解七年级 600 名学生的体重情况，从中随机抽取了 60 名学生进行测量，这个问题的样本容量是＿＿。","answer":"60","explain":"样本容量是样本中个体的数目，本题抽取了 60 名学生，所以样本容量是 60。它是一个数，不能带单位，写成「60 名」是不规范的。","difficulty":1,"tags":["样本容量"]},{"id":"q-sta-shouji-3","type":"choice","stem":"某班 50 名学生中，喜欢篮球的有 15 人，则喜欢篮球这一组的频率是（ ）","answer":"B","explain":"频率等于频数除以数据总数，即 f=(15)/(50)=0.3。0.15 是把人数与人数相除时算错，3 是把比值算反了。","options":["0.15","0.3","3","15"],"difficulty":1,"tags":["频数与频率"]},{"id":"q-sta-shouji-4","type":"choice","stem":"在扇形统计图中，某部分所对的圆心角是 72°，则该部分占总体的百分比是（ ）","answer":"C","explain":"该部分所占的百分比等于它的圆心角除以 360°，即 (72)/(360)=0.2=20%。注意不能用 72° 直接当作百分比。","options":["72%","36%","20%","18%"],"difficulty":2,"tags":["扇形统计图","圆心角"]},{"id":"q-sta-shouji-5","type":"short","stem":"为了解全校 1500 名学生的课外阅读时间，小明只调查了自己所在班级的 45 名同学，就把调查结果作为全校学生的情况。请指出他的做法存在的问题，并说明改进的办法。","answer":"存在的问题：样本容量偏小，而且同一个班级的同学学习环境相近、阅读情况相似，样本不具有代表性，用这样的样本推断全校学生的课外阅读时间会产生较大偏差。改进办法：在全校各年级、各班中随机抽取一定数量的学生，使样本容量适当、抽取过程具有随机性，并且覆盖不同的年级和班级，再根据样本数据估计全校的情况。","explain":"抽样调查的关键是样本要随机、有代表性、容量适当。只取一个班属于「方便样本」，既不能反映全校不同年级的差异，也容易受该班特殊情况的影响。","difficulty":2,"tags":["抽样调查","样本代表性"],"rubric":["指出样本不具有代表性（或样本容量偏小）","说明同一班级同学情况相近，不能代表全校水平","提出随机抽取、样本容量适当、覆盖各年级各班等改进办法"]},{"id":"q-sta-shouji-z1","type":"choice","stem":"某社区共有 2000 户家庭，为了解家庭汽车拥有情况，随机调查了 200 户，其中拥有汽车的有 80 户。下列说法正确的是（ ）","answer":"D","explain":"样本是被抽取的 200 户家庭的汽车拥有情况，不是 2000 户家庭，A 错；个体是每一户家庭的汽车拥有情况，考察的是数据而不是家庭本身，B 错；样本容量是 200，只是一个数目，不能带单位，C 错；样本中拥有汽车的频率为 (80)/(200)=0.4，估计总体为 2000× 0.4=800（户），D 正确。","options":["这次调查的样本是 2000 户家庭","这次调查的个体是每一户家庭","这次调查的样本容量是 200 户","估计该社区拥有汽车的家庭约有 800 户"],"difficulty":2,"tags":["抽样调查","用样本估计总体"]},{"id":"q-sta-shouji-z2","type":"fill","stem":"一个容量为 60 的样本中，某一组数据的频率为 0.35，则这一组数据的频数是＿＿。","answer":"21","explain":"由「频数 = 数据总数 × 频率」得频数 =60× 0.35=21。也可由频率定义 (m)/(60)=0.35 解得 m=21。","difficulty":2,"tags":["频数与频率"]}]},{"id":"m-sta-shuju-fenxi","title":"数据的分析：平均数、中位数、众数","subtitle":"人教版八下 · 第24章 数据的分析","grade":"8b","tags":["统计与概率","数据的分析"],"blocks":[{"type":"note","title":"教材章节","text":"人教版八下 · 第24章 数据的分析"},{"type":"note","title":"一句话概述","text":"掌握平均数、加权平均数、中位数与众数的求法，理解其统计意义并能选择合适的统计量。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"两个班平均分都是 80 分，但一个班人人 80，另一个班一半 100 一半 60。只看平均分会漏掉信息，所以还需要中位数和众数，从不同角度看「一般水平」。","walk":["平均数反映整体水平，但容易受极端值影响；中位数是把数据排序后中间的那个数，抗极端值；众数是出现次数最多的数。","奇数个数据，中位数是最中间那个；偶数个数据，中位数是中间两个数的平均数。","加权平均数按各数据的「权重」计算，权重可以是人数、次数、比例。"],"try":"取 5 个数：60、70、80、90、100，算一算平均数、中位数、众数，体会三者的区别。","use":["数据中有特别大或特别小的值时，优先看中位数，别只看平均数。","求加权平均数，先确认权重是什么，再乘再除。"]},{"type":"h","text":"先看整体：平均数落在哪里"},{"type":"p","text":"一组数据最常问的是「整体水平大约是多少」。把 7, 8, 9, 9, 10 画成条形图，条形越高表示数值越大；把它们相加再除以个数，就得到平均数 x=(7+8+9+9+10)/(5)=8.6。平均数用到了每一个数据，可以看作这组数据的「重心」，它一定落在最小值和最大值之间，但不一定是其中某个原数据。"},{"type":"figure","figure":{"id":"fig-sta-fenxi-s1","title":"一组数据与它的平均数","caption":"虚线标出平均数 8.6，它落在最小数据 7 与最大数据 10 之间","view":"square","alt":"条形统计图：横轴是 5 个数据的序号，纵轴是数值，5 个条形依次为 7、8、9、9、10，一条水平虚线画在 8.6 处表示平均数，虚线穿过前两个条形的上方、后三个条形的中间","prims":[{"t":"axis","x":16,"y":80,"w":68,"h":56,"xLabel":"序号","yLabel":"数值","origin":true,"xTicks":[{"at":0.1,"label":"1"},{"at":0.3,"label":"2"},{"at":0.5,"label":"3"},{"at":0.7,"label":"4"},{"at":0.9,"label":"5"}],"yTicks":[{"at":0.25,"label":"3"},{"at":0.5,"label":"6"},{"at":0.75,"label":"9"},{"at":1,"label":"12"}]},{"t":"rect","x":17.8,"y":47.3,"w":10,"h":32.7},{"t":"rect","x":31.4,"y":42.7,"w":10,"h":37.3},{"t":"rect","x":45,"y":38,"w":10,"h":42},{"t":"rect","x":58.6,"y":38,"w":10,"h":42},{"t":"rect","x":71.6,"y":33.3,"w":10,"h":46.7},{"t":"text","x":22.8,"y":44.4,"text":"7","size":3.2,"anchor":"middle"},{"t":"text","x":36.4,"y":39.8,"text":"8","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":35.1,"text":"9","size":3.2,"anchor":"middle"},{"t":"text","x":63.6,"y":35.1,"text":"9","size":3.2,"anchor":"middle"},{"t":"text","x":77.2,"y":30.4,"text":"10","size":3.2,"anchor":"middle"},{"t":"line","x1":16,"y1":39.9,"x2":84,"y2":39.9,"dashed":true,"tone":"accent"},{"t":"text","x":85,"y":39.9,"text":"8.6","size":3,"anchor":"start","tone":"accent"},{"t":"text","x":50,"y":92,"text":"平均数 = (7+8+9+9+10) ÷ 5 = 8.6","size":3,"anchor":"middle"}]}},{"type":"note","title":"","text":"求和时不能漏数、不能数错数据个数；平均数是一个数值，要带单位。"},{"type":"h","text":"抓位置：排序后找中位数"},{"type":"p","text":"平均数会被个别数据牵着走，再换一角度看「正中间的那个数」。先把数据从小到大排成一排：7, 8, 9, 9, 10；数据个数 n=5 是奇数，正中间第 (n+1)/(2)=3 个数就是中位数，即 9。中位数把数据分成大小各占一半的两部分，它的位置只由排序决定，与数值本身的大小无关。"},{"type":"figure","figure":{"id":"fig-sta-fenxi-s2","title":"排序后取正中间的数","caption":"n = 5 为奇数，第 3 个数 9 就是中位数","view":"square","alt":"把 5 个数据从小到大排成一排，依次是 7、8、9、9、10，每个数据画成一个点，正中间第 3 个数据 9 用虚线圆圈圈出，标注为 n 为奇数时第 3 个数就是中位数","prims":[{"t":"text","x":50,"y":16,"text":"先从小到大排序","size":3.4,"anchor":"middle","tone":"muted"},{"t":"dot","x":24,"y":38,"r":2.4},{"t":"dot","x":37,"y":38,"r":2.4},{"t":"dot","x":50,"y":38,"r":2.4,"tone":"accent"},{"t":"dot","x":63,"y":38,"r":2.4},{"t":"dot","x":76,"y":38,"r":2.4},{"t":"text","x":24,"y":46,"text":"7","size":3.2,"anchor":"middle"},{"t":"text","x":37,"y":46,"text":"8","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":46,"text":"9","size":3.2,"anchor":"middle"},{"t":"text","x":63,"y":46,"text":"9","size":3.2,"anchor":"middle"},{"t":"text","x":76,"y":46,"text":"10","size":3.2,"anchor":"middle"},{"t":"circle","cx":50,"cy":38,"r":6.5,"dashed":true,"tone":"accent"},{"t":"text","x":50,"y":58,"text":"n = 5 为奇数，中位数是第 (5+1)/2 = 3 个数","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":67,"text":"第 3 个数是 9，所以中位数是 9","size":3.4,"anchor":"middle","tone":"accent"}]}},{"type":"note","title":"","text":"必须先把数据从小到大排序，再按位置取数，不能从原始顺序里随手挑中间那个。"},{"type":"h","text":"抓次数：出现最多的就是众数"},{"type":"p","text":"还有一个角度看「大多数数据挤在哪个值上」。数一数每个数据出现的次数：数据 5 出现 2 次，7 出现 1 次，而 6 出现了 3 次，出现次数最多的 6 就是这组数据的众数。众数只关心「谁出现得最多」，它一定是原数据中出现过的值，并且可以不止一个。"},{"type":"figure","figure":{"id":"fig-sta-fenxi-s3","title":"数出现次数找众数","caption":"数据 6 出现 3 次，次数最多，众数就是 6","view":"square","alt":"条形统计图：横轴是数据 5、6、7，纵轴是出现次数，三个条形高度依次为 2、3、1，其中数据 6 的条形最高（3 次）并用高亮标出，说明它是众数","prims":[{"t":"axis","x":20,"y":80,"w":60,"h":56,"xLabel":"数据","yLabel":"出现次数","origin":true,"xTicks":[{"at":0.17,"label":"5"},{"at":0.5,"label":"6"},{"at":0.83,"label":"7"}],"yTicks":[{"at":0.33,"label":"1"},{"at":0.67,"label":"2"},{"at":1,"label":"3"}]},{"t":"rect","x":23,"y":42.7,"w":14,"h":37.3},{"t":"rect","x":43,"y":24,"w":14,"h":56,"tone":"accent","fill":true},{"t":"rect","x":63,"y":61.3,"w":14,"h":18.7},{"t":"text","x":30,"y":39.6,"text":"2","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":20.9,"text":"3","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":70,"y":58.2,"text":"1","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":92,"text":"数据 5, 5, 6, 6, 6, 7：6 出现 3 次最多，众数是 6","size":3,"anchor":"middle"}]}},{"type":"note","title":"","text":"众数可以有不止一个；当各数据出现的次数都相同时，这组数据没有众数。"},{"type":"h","text":"换个情境：加一个极端值会怎样"},{"type":"p","text":"在 7, 8, 9, 9, 10 里再添一个 100，重新计算：平均数变成 x=(143)/(6)≈ 23.8，被这个极端值大幅拉高；而中位数变成第 3、4 个数据的平均数 9 与 9 的平均数，仍然是 9，几乎不动。这说明数据中存在个别相差很大的数值时，用中位数描述「一般水平」比用平均数更合适。"},{"type":"figure","figure":{"id":"fig-sta-fenxi-s4","title":"极端值对平均数与中位数的影响","caption":"加入 100 后平均数从 8.6 拉到 23.8，中位数仍停在 9","view":"square","alt":"左右两幅对比图：左图原数据 7、8、9、9、10 的条形高度均匀，平均数虚线在 8.6；右图再加一个 100，出现一根很高的条形，平均数虚线被抬到 23.8，中位数虚线仍停在 9 附近","prims":[{"t":"text","x":26,"y":14,"text":"原数据：7, 8, 9, 9, 10","size":3.2,"anchor":"middle"},{"t":"axis","x":8,"y":78,"w":36,"h":46,"xLabel":"","yLabel":"","origin":false,"yTicks":[{"at":0.5,"label":"6"},{"at":1,"label":"12"}]},{"t":"rect","x":8.6,"y":51.2,"w":6,"h":26.8},{"t":"rect","x":15.8,"y":47.3,"w":6,"h":30.7},{"t":"rect","x":23,"y":43.5,"w":6,"h":34.5},{"t":"rect","x":30.2,"y":43.5,"w":6,"h":34.5},{"t":"rect","x":37.4,"y":39.7,"w":6,"h":38.3},{"t":"line","x1":8,"y1":45,"x2":44,"y2":45,"dashed":true,"tone":"accent"},{"t":"text","x":9,"y":41.5,"text":"平均数 8.6","size":2.8,"anchor":"start","tone":"accent"},{"t":"text","x":74,"y":14,"text":"再加一个 100","size":3.2,"anchor":"middle"},{"t":"axis","x":56,"y":78,"w":36,"h":46,"xLabel":"","yLabel":"","origin":false,"yTicks":[{"at":0.25,"label":"25"},{"at":0.5,"label":"50"},{"at":0.75,"label":"75"},{"at":1,"label":"100"}]},{"t":"rect","x":56.5,"y":74.8,"w":5,"h":3.2,"tone":"muted"},{"t":"rect","x":62.5,"y":74.3,"w":5,"h":3.7,"tone":"muted"},{"t":"rect","x":68.5,"y":73.9,"w":5,"h":4.1,"tone":"muted"},{"t":"rect","x":74.5,"y":73.9,"w":5,"h":4.1,"tone":"muted"},{"t":"rect","x":80.5,"y":73.4,"w":5,"h":4.6,"tone":"muted"},{"t":"rect","x":86.5,"y":32,"w":5,"h":46},{"t":"text","x":89,"y":28.5,"text":"100","size":3,"anchor":"middle"},{"t":"line","x1":56,"y1":67,"x2":92,"y2":67,"dashed":true,"tone":"accent"},{"t":"text","x":57,"y":63,"text":"平均数升到 23.8","size":2.8,"anchor":"start","tone":"accent"},{"t":"line","x1":56,"y1":73.9,"x2":92,"y2":73.9,"dashed":true,"tone":"ok"},{"t":"text","x":57,"y":70,"text":"中位数还是 9","size":2.8,"anchor":"start","tone":"ok"},{"t":"text","x":50,"y":92,"text":"平均数被极端值拉走：8.6 → 23.8；中位数几乎不动：9 → 9","size":3,"anchor":"middle"}]}},{"type":"note","title":"","text":"先看数据里有没有极端值：有极端值偏向中位数，关心「出现最多」用众数，要用到全部数据信息才用平均数。"},{"type":"h","text":"核心概念"},{"type":"p","text":"平均数：一组数据的总和除以数据的个数，叫做这组数据的平均数，记作 x。平均数能利用全部数据的信息，反映数据的平均水平。"},{"type":"p","text":"加权平均数：当各个数据的重要程度不同时，按重要程度计算出的平均数叫做加权平均数，各项的重要程度叫做权。权越大，该项数据对平均数的影响越大。"},{"type":"p","text":"中位数：把一组数据按从小到大（或从大到小）的顺序排列后，处于中间位置的数叫做这组数据的中位数。中位数把数据分成大小各占一半的两部分，不受极端值的影响。"},{"type":"p","text":"中位数的求法要点：必须先排序再定位。数据个数 n 为奇数时，中位数是第 (n+1)/(2) 个数；n 为偶数时，中位数是第 (n)/(2) 个数与第 (n)/(2)+1 个数的平均数。"},{"type":"p","text":"众数：一组数据中出现次数最多的数据叫做这组数据的众数。众数可以有不止一个；当各个数据出现的次数都相同时，这组数据没有众数。"},{"type":"p","text":"三个统计量的比较：平均数能反映全部数据的信息，但容易受极端值影响；中位数不受极端值影响，适合数据中有个别相差很大的数值时使用；众数反映出现次数最多的数据，当某个数据反复出现时最能代表一般水平。"},{"type":"p","text":"用样本估计总体：当总体数量很大时，常用样本的平均数、中位数、众数去估计总体的相应统计量，进而由「总体数量 × 平均数」估计总量。"},{"type":"note","title":"中考考法","text":"平均数、中位数、众数的计算\n选择、填空均常考，给一组数据或频数表求三个统计量，求中位数必须先排序，偶数个数据取中间两个的平均数。"},{"type":"note","title":"中考考法","text":"加权平均数的实际应用\n以成绩评定、招聘打分、商品定价为情境，按权重比或百分比求综合成绩，分母是所有权之和而不是数据的种类数。"},{"type":"note","title":"中考考法","text":"根据数据特点选择统计量\n解答题常要求先算三量再说明哪个更具代表性，数据中有极端值偏向中位数、某数据反复出现偏向众数，结论要回扣情境。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["算术平均数","n 个数据 x₁,x₂,…,x_n 的平均数等于它们的和除以数据个数。","各数据的重要程度相同时使用；计算时不要漏掉数据、不要数错数据个数。"],["加权平均数","当数据 x₁,x₂,…,x_k 出现的次数分别为 f₁,f₂,…,f_k 时，加权平均数为分子除以权的和。","分子是各数据与对应权乘积的和，分母是所有权的和，不能只除以数据的种类数 k。"],["权为百分比时的加权平均数","当各项的权用百分比表示、且各项权之和为 1 时，把每个数据乘它所占的比例再相加。","w₁+w₂+…+w_k=1，若权之和不等于 1，需要先化成和为 1 的比例。"],["中位数的位置","把 n 个数据从小到大排列：n 为奇数时，中位数是第 (n+1)/(2) 个数；n 为偶数时，中位数是第 (n)/(2) 个与第 (n)/(2)+1 个数的平均数。","必须先把数据从小到大排序，再按位置找中位数。"],["平均数随数据变化","若一组数据的平均数为 x，把每个数据都加上 a，则新数据的平均数为 x+a。","把每个数据都乘 k 时，新数据的平均数是原来平均数的 k 倍。"]]},{"type":"note","title":"例题","text":"求数据 7, 9, 8, 9, 10 的平均数、中位数和众数。"},{"type":"figure","figure":{"id":"fig-sta-fenxi-e1","title":"三个统计量一起求","caption":"排序后取中间得中位数，数出现次数得众数，求和再平均得平均数","view":"square","alt":"示意图：把数据 7、8、9、9、10 排序后放进五个方框，中间第 3 个方框 9 用虚线圈出表示中位数；下方分别写出众数是 9（出现 2 次）与平均数 8.6","prims":[{"t":"text","x":50,"y":14,"text":"数据 7, 9, 8, 9, 10 的三个统计量","size":3.2,"anchor":"middle"},{"t":"rect","x":8,"y":22,"w":13,"h":13},{"t":"rect","x":24,"y":22,"w":13,"h":13},{"t":"rect","x":40,"y":22,"w":13,"h":13},{"t":"rect","x":56,"y":22,"w":13,"h":13},{"t":"rect","x":72,"y":22,"w":13,"h":13},{"t":"text","x":14.5,"y":28.5,"text":"7","size":3.4,"anchor":"middle"},{"t":"text","x":30.5,"y":28.5,"text":"8","size":3.4,"anchor":"middle"},{"t":"text","x":46.5,"y":28.5,"text":"9","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":62.5,"y":28.5,"text":"9","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":78.5,"y":28.5,"text":"10","size":3.4,"anchor":"middle"},{"t":"circle","cx":46.5,"cy":28.5,"r":10,"dashed":true,"tone":"accent"},{"t":"text","x":50,"y":48,"text":"排序后第 3 个是 9 → 中位数是 9","size":3,"anchor":"middle"},{"t":"text","x":50,"y":60,"text":"9 出现 2 次、其余各 1 次 → 众数是 9","size":3,"anchor":"middle"},{"t":"text","x":50,"y":72,"text":"平均数 = (7+8+9+9+10) ÷ 5 = 8.6","size":3.2,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["求平均数：x=(7+9+8+9+10)/(5)=(43)/(5)=8.6。","把数据从小到大排列：7, 8, 9, 9, 10，共 5 个数据，n=5 为奇数。","中位数是第 (5+1)/(2)=3 个数，即 9。","数各数据出现的次数：9 出现了 2 次，其他数据都只出现 1 次，出现次数最多，所以众数是 9。"]},{"type":"p","text":"答案：平均数是 8.6，中位数是 9，众数是 9。"},{"type":"note","title":"方法小结","text":"求中位数之前一定先排序，否则容易点错位置；出现次数相同的数据要一起作为众数。"},{"type":"note","title":"例题","text":"求数据 3, 5, 4, 7, 6, 9 的中位数。"},{"type":"figure","figure":{"id":"fig-sta-fenxi-e2","title":"先排序再取中间两个数","caption":"原始顺序不能直接取中间，排序后中间两数是 5 和 6，中位数 5.5","view":"square","alt":"上下两行对比：上一行按原始顺序排列 3、5、4、7、6、9；下一行从小到大排序为 3、4、5、6、7、9，中间第 3、4 个 5 和 6 用虚线圆圈圈出，中位数等于 5 加 6 再除以 2 得 5.5","prims":[{"t":"text","x":50,"y":12,"text":"原始顺序：3, 5, 4, 7, 6, 9（不能直接取中间）","size":3,"anchor":"middle","tone":"muted"},{"t":"rect","x":8,"y":18,"w":13,"h":12,"tone":"muted","dashed":true},{"t":"rect","x":23.4,"y":18,"w":13,"h":12,"tone":"muted","dashed":true},{"t":"rect","x":38.8,"y":18,"w":13,"h":12,"tone":"muted","dashed":true},{"t":"rect","x":54.2,"y":18,"w":13,"h":12,"tone":"muted","dashed":true},{"t":"rect","x":69.6,"y":18,"w":13,"h":12,"tone":"muted","dashed":true},{"t":"rect","x":85,"y":18,"w":13,"h":12,"tone":"muted","dashed":true},{"t":"text","x":14.5,"y":24,"text":"3","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":29.9,"y":24,"text":"5","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":45.3,"y":24,"text":"4","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":60.7,"y":24,"text":"7","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":76.1,"y":24,"text":"6","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":91.5,"y":24,"text":"9","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":44,"text":"排序后：3, 4, 5, 6, 7, 9","size":3.2,"anchor":"middle"},{"t":"rect","x":8,"y":52,"w":13,"h":13},{"t":"rect","x":23.4,"y":52,"w":13,"h":13},{"t":"rect","x":38.8,"y":52,"w":13,"h":13},{"t":"rect","x":54.2,"y":52,"w":13,"h":13},{"t":"rect","x":69.6,"y":52,"w":13,"h":13},{"t":"rect","x":85,"y":52,"w":13,"h":13},{"t":"text","x":14.5,"y":58.5,"text":"3","size":3.4,"anchor":"middle"},{"t":"text","x":29.9,"y":58.5,"text":"4","size":3.4,"anchor":"middle"},{"t":"text","x":45.3,"y":58.5,"text":"5","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":60.7,"y":58.5,"text":"6","size":3.4,"anchor":"middle","tone":"accent"},{"t":"text","x":76.1,"y":58.5,"text":"7","size":3.4,"anchor":"middle"},{"t":"text","x":91.5,"y":58.5,"text":"9","size":3.4,"anchor":"middle"},{"t":"circle","cx":45.3,"cy":58.5,"r":10,"dashed":true,"tone":"accent"},{"t":"circle","cx":60.7,"cy":58.5,"r":10,"dashed":true,"tone":"accent"},{"t":"text","x":50,"y":82,"text":"n = 6 为偶数，中位数 = (5 + 6) ÷ 2 = 5.5","size":3.2,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["把数据从小到大排列：3, 4, 5, 6, 7, 9。","数据个数 n=6，是偶数，中位数要取中间两个数的平均数。","中间两个数是第 3 个数与第 4 个数，即 5 和 6。","中位数 =(5+6)/(2)=5.5。"]},{"type":"p","text":"答案：这组数据的中位数是 5.5。"},{"type":"note","title":"方法小结","text":"偶数个数据的中位数是中间两数的平均数，它可以是原数据中没有出现过的数。"},{"type":"note","title":"例题","text":"某公司招聘职员，笔试成绩与面试成绩按 4 : 6 的比确定综合成绩。甲的笔试成绩是 90 分，面试成绩是 80 分，求甲的综合成绩。"},{"type":"figure","figure":{"id":"fig-sta-fenxi-e3","title":"条形的宽就是权的大小","caption":"笔试与面试的权之比是 4 : 6，条形宽度也按 4 : 6 画出","view":"square","alt":"加权平均数示意图：笔试条形宽 4 份、面试条形宽 6 份，宽度之比等于权之比 4 比 6，下方写出综合成绩等于 90 乘 4 加 80 乘 6 的和再除以 10，得 84 分","prims":[{"t":"text","x":50,"y":14,"text":"笔试与面试按 4 : 6 计权","size":3.2,"anchor":"middle"},{"t":"rect","x":10,"y":24,"w":24,"h":12,"fill":true},{"t":"rect","x":34,"y":24,"w":36,"h":12,"tone":"accent","fill":true},{"t":"text","x":22,"y":30,"text":"笔试 90","size":2.8,"anchor":"middle"},{"t":"text","x":52,"y":30,"text":"面试 80","size":2.8,"anchor":"middle","tone":"accent"},{"t":"text","x":22,"y":43,"text":"权 4","size":2.8,"anchor":"middle"},{"t":"text","x":52,"y":43,"text":"权 6","size":2.8,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":58,"text":"条形的宽之比 = 权之比 = 4 : 6","size":3,"anchor":"middle"},{"t":"text","x":50,"y":72,"text":"综合成绩 = (90×4 + 80×6) ÷ (4+6) = 840 ÷ 10 = 84 分","size":3.2,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["分清权：笔试的权为 4，面试的权为 6，权的和为 4+6=10。","求各数据与权的乘积之和：90× 4+80× 6=360+480=840。","求加权平均数：x=(840)/(4+6)=(840)/(10)=84（分）。"]},{"type":"p","text":"答案：甲的综合成绩是 84 分。"},{"type":"note","title":"方法小结","text":"权越大，该项成绩对综合成绩的影响越大。这里的面试权为 6，比笔试更重要，所以综合成绩 84 分低于两数的简单平均数 85 分。"},{"type":"note","title":"例题","text":"某商店 20 名营业员某月的销售额（单位：千元）与人数如下表：销售额 10 的有 4 人，15 的有 8 人，20 的有 6 人，25 的有 2 人。求这 20 人销售额的平均数、中位数和众数。"},{"type":"figure","figure":{"id":"fig-m-sta-fenxi-1","title":"20 名营业员月销售额条形统计图","caption":"销售额 15 千元一组人数最多（8 人），即众数 15 千元","view":"wide","alt":"条形统计图：横轴是销售额 10、15、20、25 千元，纵轴是人数，四组人数依次为 4、8、6、2，其中 15 千元一组 8 人最高","prims":[{"t":"axis","x":14,"y":68,"w":68,"h":46,"xLabel":"销售额（千元）","yLabel":"人数","origin":true,"xTicks":[{"at":0.13,"label":"10"},{"at":0.38,"label":"15"},{"at":0.63,"label":"20"},{"at":0.88,"label":"25"}],"yTicks":[{"at":0,"label":"0"},{"at":0.33,"label":"3"},{"at":0.67,"label":"6"},{"at":1,"label":"9"}]},{"t":"rect","x":17.5,"y":47.6,"w":10,"h":20.4},{"t":"rect","x":34.5,"y":27.1,"w":10,"h":40.9,"tone":"accent","fill":true},{"t":"rect","x":51.5,"y":37.3,"w":10,"h":30.7},{"t":"rect","x":68.5,"y":57.8,"w":10,"h":10.2},{"t":"text","x":22.5,"y":45.1,"text":"4","size":3.2,"anchor":"middle"},{"t":"text","x":39.5,"y":24.6,"text":"8","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":56.5,"y":34.8,"text":"6","size":3.2,"anchor":"middle"},{"t":"text","x":73.5,"y":55.3,"text":"2","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":82,"text":"平均数 16.5 千元 · 中位数 15 千元 · 众数 15 千元","size":3.2,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["求加权平均数：总人数为 4+8+6+2=20，销售总额为 10× 4+15× 8+20× 6+25× 2=40+120+120+50=330。","平均数 x=(330)/(20)=16.5（千元）。","求中位数：把 20 个数据按从小到大排列，n=20 为偶数，中位数是第 10、11 两个数据的平均数；前两组累计 4+8=12 人，第 10、11 个数据都是 15，所以中位数为 15 千元。","求众数：销售额为 15 千元的人数最多，有 8 人，所以众数是 15 千元。"]},{"type":"p","text":"答案：平均数为 16.5 千元，中位数为 15 千元，众数为 15 千元。"},{"type":"note","title":"方法小结","text":"频数表中求中位数要用「累计频数」定位中间位置落在第几组，不能直接拿销售额的中间值 17.5 当中位数。"},{"type":"note","title":"例题","text":"某歌手大奖赛中，7 位评委给一名选手的打分（单位：分）为 6.0, 7.5, 8.0, 8.5, 9.0, 9.0, 9.5。比赛规则规定：去掉一个最高分和一个最低分后，用余下分数的平均数作为选手的最后得分。求这名选手的最后得分，并说明这样规定的理由。"},{"type":"figure","figure":{"id":"fig-sta-fenxi-e5","title":"去掉最高分与最低分再平均","caption":"7 位评委的打分中去掉 6.0 和 9.5，余下 5 个分数的平均数是 8.4 分","view":"square","alt":"数轴示意图：数轴上依次标出 6.0、7.5、8.0、8.5、9.0、9.0、9.5 共七个分数点，最低的 6.0 与最高的 9.5 画成空心圈并标出「去掉」，中间五个分数用实心点表示，下方写出余下五个分数的平均数是 8.4 分","prims":[{"t":"line","x1":8,"y1":45,"x2":94,"y2":45},{"t":"line","x1":10,"y1":42,"x2":10,"y2":48},{"t":"line","x1":30.5,"y1":42,"x2":30.5,"y2":48},{"t":"line","x1":51,"y1":42,"x2":51,"y2":48},{"t":"line","x1":71.5,"y1":42,"x2":71.5,"y2":48},{"t":"line","x1":92,"y1":42,"x2":92,"y2":48},{"t":"text","x":10,"y":52.5,"text":"6.0","size":2.8,"anchor":"middle"},{"t":"text","x":30.5,"y":52.5,"text":"7","size":2.8,"anchor":"middle"},{"t":"text","x":51,"y":52.5,"text":"8","size":2.8,"anchor":"middle"},{"t":"text","x":71.5,"y":52.5,"text":"9","size":2.8,"anchor":"middle"},{"t":"text","x":92,"y":52.5,"text":"10","size":2.8,"anchor":"middle"},{"t":"dot","x":10,"y":45,"r":2.4,"hollow":true,"tone":"danger"},{"t":"dot","x":40.8,"y":45,"r":2.4,"tone":"accent"},{"t":"dot","x":51,"y":45,"r":2.4,"tone":"accent"},{"t":"dot","x":61.3,"y":45,"r":2.4,"tone":"accent"},{"t":"dot","x":71.5,"y":41,"r":2.4,"tone":"accent"},{"t":"dot","x":71.5,"y":49,"r":2.4,"tone":"accent"},{"t":"dot","x":81.8,"y":45,"r":2.4,"hollow":true,"tone":"danger"},{"t":"text","x":16,"y":32,"text":"去掉最低 6.0","size":2.8,"anchor":"start","tone":"danger"},{"t":"text","x":68,"y":32,"text":"去掉最高 9.5","size":2.8,"anchor":"start","tone":"danger"},{"t":"text","x":71.5,"y":28,"text":"9.0 有两个","size":2.6,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":66,"text":"余下 7.5, 8.0, 8.5, 9.0, 9.0 共 5 个分数","size":3,"anchor":"middle"},{"t":"text","x":50,"y":78,"text":"最后得分 = 42 ÷ 5 = 8.4 分","size":3.4,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["找出一个最高分和一个最低分：最高分是 9.5 分，最低分是 6.0 分。","去掉这两个分数，余下 5 个分数为 7.5, 8.0, 8.5, 9.0, 9.0。","求余下分数的平均数：(7.5+8.0+8.5+9.0+9.0)/(5)=(42)/(5)=8.4（分）。","说明理由：6.0 分是明显偏低的极端值，会拉低平均数，去掉最高分和最低分可以减弱极端值对平均分的影响，使成绩更能反映评委的整体评价。"]},{"type":"p","text":"答案：这名选手的最后得分是 8.4 分；去掉极端分数是为了避免个别评委的异常打分影响总成绩。"},{"type":"note","title":"方法小结","text":"平均数容易受极端值影响，「去掉一个最高分、一个最低分再平均」就是用评分规则降低极端值的影响，计算时注意参与平均的数据个数变成了 5 个。"},{"type":"list","title":"易错点","items":["求中位数必须先排序：数据 9, 3, 7, 5, 11 若不排序就取中间的 7 是巧合，换成 11, 3, 7, 5, 9 就会做错，正确做法是先排序为 3, 5, 7, 9, 11 再取中位数 7。","偶数个数据的中位数是中间两个数的平均数，不要随手取其中一个数。","一组数据的众数可以有不止一个，也可能没有；不能想当然地认为众数只有一个。","平均数容易受极端值影响：数据 1, 2, 3, 4, 100 的平均数是 22，并不能代表大多数数据的水平，这时用中位数 3 更合适。","加权平均数中「权」体现的是重要程度，不能把权当成数据个数而改变除数；权为百分比时，各项权之和应为 1。","计算平均数时不要漏掉数据或数错数据个数，得数要带单位。"]},{"type":"list","title":"解题方法","items":["求平均数：先求和，再除以数据个数；数据较多且集中在某个数附近时，可把每个数据减去这个基准数，求出新数据的平均数后再加上基准数。","求中位数：先排序 → 判断数据个数是奇数还是偶数 → 奇数取最中间的一个数，偶数取中间两个数的平均数。","求众数：逐一数出各数据出现的次数，出现次数最多的数据就是众数，出现次数相同的要全部写出。","选择统计量：数据中有极端值时用中位数，需要利用全部数据信息时用平均数，关心「出现最多」的情况时用众数。","用样本估计总体：先用样本的平均数估计总体的平均水平，再用「总体数量 × 平均数」估计总量。"]}],"questions":[{"id":"q-sta-fenxi-1","type":"choice","stem":"一组数据 5, 7, 7, 8, 10 的中位数是（ ）","answer":"A","explain":"数据已按从小到大排列，共 5 个，n=5 为奇数，中位数是第 (5+1)/(2)=3 个数，即 7。选 8 是错取了偏大的数，选 7.5 是误把偶数个数的求法用在了奇数个数据上。","options":["7","7.5","8","10"],"difficulty":1,"tags":["中位数"]},{"id":"q-sta-fenxi-2","type":"fill","stem":"数据 2, 3, 3, 4, 5, 5 的中位数是＿＿。","answer":"3.5","explain":"数据共 6 个，已按从小到大排列。n=6 为偶数，中位数是第 3 个数与第 4 个数的平均数，即 (3+4)/(2)=3.5。","difficulty":1,"tags":["中位数","偶数个数据"]},{"id":"q-sta-fenxi-3","type":"choice","stem":"数据 1, 2, 2, 3, 3, 4 的众数是（ ）","answer":"C","explain":"2 和 3 都出现了 2 次，出现次数最多且相同，所以这组数据的众数是 2 和 3。众数可以有多个，不能只取其中一个；1 和 4 都只出现 1 次，不是众数。","options":["2","3","2 和 3","没有众数"],"difficulty":2,"tags":["众数"]},{"id":"q-sta-fenxi-4","type":"choice","stem":"某同学的平时成绩是 80 分，期末成绩是 90 分，平时成绩与期末成绩按 3 : 7 计算学期总评，则他的学期总评是（ ）","answer":"B","explain":"按加权平均数计算：x=(80× 3+90× 7)/(3+7)=(240+630)/(10)=(870)/(10)=87（分）。选 85 分是把两项成绩直接求算术平均数，忽略了权。","options":["85 分","87 分","86 分","84 分"],"difficulty":2,"tags":["加权平均数"]},{"id":"q-sta-fenxi-5","type":"short","stem":"某小组 5 名同学的捐款数为 10, 10, 20, 20, 20（单位：元）。分别求这组数据的平均数、中位数和众数，并说明用哪个统计量表示这组同学的捐款水平更合适。","answer":"平均数 =(10+10+20+20+20)/(5)=(80)/(5)=16（元）；把数据从小到大排列为 10, 10, 20, 20, 20，共 5 个数据，中间第 3 个数是 20，所以中位数是 20 元；20 出现了 3 次，出现次数最多，所以众数是 20 元。这组数据中有 3 人捐了 20 元，用众数 20 元（或中位数 20 元）表示大多数同学的捐款水平更合适；平均数 16 元受两个较小的数据 10 元影响而偏低。","explain":"求中位数前要先排序并判断数据个数是奇数还是偶数；众数要数清出现次数。选择统计量时要看数据的特点：数据中重复出现某个值时应考虑众数，有极端值时应考虑中位数。","difficulty":2,"tags":["平均数","中位数","众数","统计量选择"],"rubric":["正确求出平均数为 16 元","先排序后求出中位数为 20 元","指出众数是 20 元并说明它出现了 3 次","说明众数（或中位数）更能代表大多数同学的捐款水平"]},{"id":"q-sta-fenxi-z1","type":"choice","stem":"一家鞋店在一周内销售了某种运动鞋若干双，老板决定下周进货时多进一些卖得最多的尺码，他最应关心这组销售数据的（ ）","answer":"A","explain":"老板关心的是哪个尺码的鞋卖出的双数最多，即出现次数最多的数据，这正是众数。平均数反映平均销售水平、中位数反映中间水平，都不能直接告诉他该多进哪个尺码。","options":["众数","中位数","平均数","最大值"],"difficulty":2,"tags":["众数","统计量选择"]},{"id":"q-sta-fenxi-z2","type":"short","stem":"某校规定学生的数学学期成绩由三部分组成：平时成绩占 20%，期中成绩占 30%，期末成绩占 50%。小红的三项成绩依次为 90 分、85 分、92 分，求她这学期的数学学期成绩。","answer":"三项成绩的权分别为 20%、30%、50%，学期成绩为加权平均数：90× 20%+85× 30%+92× 50%=18+25.5+46=89.5（分）。所以小红这学期的数学学期成绩是 89.5 分。","explain":"当权以百分比给出时，把每个成绩乘对应的百分比再相加即可，且各项权之和 20%+30%+50%=100%。本题中期末成绩的权最大，所以学期成绩 89.5 分比较接近期末的 92 分，而不是三项成绩的简单平均数 89 分。","difficulty":2,"tags":["加权平均数","实际情境"],"rubric":["写出加权平均数算式 90× 20%+85× 30%+92× 50%","正确算出三项乘积之和为 89.5 分","说明这是按权计算的加权平均数（或指期末权重最大）"]}]},{"id":"m-sta-fangcha","title":"方差与数据的波动","subtitle":"人教版八下 · 第24章 数据的分析","grade":"8b","tags":["统计与概率","数据的分析"],"blocks":[{"type":"note","title":"教材章节","text":"人教版八下 · 第24章 数据的分析"},{"type":"note","title":"一句话概述","text":"理解极差、方差与标准差，掌握方差的完整计算步骤，会根据方差比较数据的稳定性。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"两名射击运动员，平均环数都是 9 环，但一个枪枪 9 环，另一个一会儿 10 环一会儿 8 环。比赛要选谁？看「稳不稳」，就要看方差。","walk":["方差衡量数据偏离平均数的程度，方差越小，数据越稳定。计算步骤：求平均数、求各数据与平均数的差的平方、求这些平方的平均数。","标准差是方差的算术平方根，单位与原数据一致，更直观。","方差越大波动越大，方差越小越整齐。选拔、质检、评比常用方差比较稳定性。"],"try":"算两组数 8、9、10 和 5、9、13 的方差，你会发现平均数都是 9，但第二组明显更分散。","use":["比较稳定性先算平均数，再算方差，两者都写出来才完整。","方差计算别漏「平方」，也别把「差的平方和」直接当方差，还要除以数据个数。"]},{"type":"h","text":"先看波动：两组数据的离散程度"},{"type":"p","text":"甲、乙两名同学各射击 5 次，两人的平均成绩都是 8 环，可甲的成绩集中在 8 环附近，乙的成绩却在 6 环到 9 环之间来回跳。平均数只能说明「打得准不准」，说不清「稳不稳」；描述这种忽高忽低的程度要另找一把尺子，就是方差，它衡量的是数据偏离平均数的程度，方差越大，数据越分散、越不稳定。"},{"type":"figure","figure":{"id":"fig-sta-fangcha-s1","title":"平均数相同、波动不同","caption":"两组的平均数都是 8 环，但甲的数据挤在一起，乙的数据铺得更开","view":"square","alt":"两组数据对比图：上排甲的成绩 7、8、8、8、9 集中在 8 附近，线段短；下排乙的成绩 6、8、8、9、9 分布范围更大，线段更长，说明乙的波动更大","prims":[{"t":"line","x1":16,"y1":26,"x2":88,"y2":26},{"t":"line","x1":16,"y1":23,"x2":16,"y2":29},{"t":"line","x1":30.4,"y1":23,"x2":30.4,"y2":29},{"t":"line","x1":44.8,"y1":23,"x2":44.8,"y2":29},{"t":"line","x1":59.2,"y1":23,"x2":59.2,"y2":29},{"t":"line","x1":73.6,"y1":23,"x2":73.6,"y2":29},{"t":"line","x1":88,"y1":23,"x2":88,"y2":29},{"t":"text","x":16,"y":18,"text":"5","size":3,"anchor":"middle"},{"t":"text","x":30.4,"y":18,"text":"6","size":3,"anchor":"middle"},{"t":"text","x":44.8,"y":18,"text":"7","size":3,"anchor":"middle"},{"t":"text","x":59.2,"y":18,"text":"8","size":3,"anchor":"middle"},{"t":"text","x":73.6,"y":18,"text":"9","size":3,"anchor":"middle"},{"t":"text","x":88,"y":18,"text":"10","size":3,"anchor":"middle"},{"t":"line","x1":44.8,"y1":45,"x2":73.6,"y2":45,"tone":"ok","width":3},{"t":"dot","x":44.8,"y":45,"r":1.8,"tone":"ok"},{"t":"dot","x":59.2,"y":45,"r":1.8,"tone":"ok"},{"t":"dot","x":73.6,"y":45,"r":1.8,"tone":"ok"},{"t":"text","x":14,"y":45,"text":"甲","size":3.2,"anchor":"end","tone":"ok"},{"t":"line","x1":30.4,"y1":62,"x2":73.6,"y2":62,"tone":"accent","width":3},{"t":"dot","x":30.4,"y":62,"r":1.8,"tone":"accent"},{"t":"dot","x":59.2,"y":62,"r":1.8,"tone":"accent"},{"t":"dot","x":73.6,"y":62,"r":1.8,"tone":"accent"},{"t":"text","x":14,"y":62,"text":"乙","size":3.2,"anchor":"end","tone":"accent"},{"t":"text","x":50,"y":78,"text":"两组的平均数都是 8 环","size":3,"anchor":"middle"},{"t":"text","x":50,"y":88,"text":"甲集中在 8 附近（波动小），乙的范围更大（波动大）","size":3,"anchor":"middle"}]}},{"type":"note","title":"","text":"比较稳定性不是比谁的成绩高，而是比谁离平均数更近；平均数相差很大时不能只比波动。"},{"type":"h","text":"抓偏差：每个数与平均数差多少"},{"type":"p","text":"方差的出发点是先把「偏离」量出来。以平均数为基准，每个数据与它的差叫做偏差；甲组 7, 8, 8, 8, 9 的平均数是 8，偏差依次为 -1, 0, 0, 0, +1。偏差有正有负，直接相加会互相抵消（-1+0+0+0+1=0），所以不能求「平均偏差」，必须先把每个偏差平方。"},{"type":"figure","figure":{"id":"fig-sta-fangcha-s2","title":"每个数据与平均数的偏差","caption":"偏差有正有负，和为 0，所以要平方后再平均","view":"square","alt":"偏差示意图：中间一条虚线标出平均数 8，左边数据 7 到平均数的箭头标 −1，右边数据 9 到平均数的箭头标 +1，数据 8 的偏差为 0，说明偏差的和是 0","prims":[{"t":"text","x":50,"y":14,"text":"平均数 8 所在的位置","size":3.2,"anchor":"middle","tone":"muted"},{"t":"line","x1":50,"y1":18,"x2":50,"y2":76,"dashed":true,"tone":"muted"},{"t":"dot","x":22,"y":28,"r":2.4},{"t":"text","x":22,"y":22,"text":"数据 7","size":2.8,"anchor":"middle"},{"t":"arrow","x1":25,"y1":28,"x2":47,"y2":28,"tone":"danger","label":"−1"},{"t":"dot","x":78,"y":28,"r":2.4},{"t":"text","x":78,"y":22,"text":"数据 9","size":2.8,"anchor":"middle"},{"t":"arrow","x1":75,"y1":28,"x2":53,"y2":28,"tone":"accent","label":"+1"},{"t":"dot","x":50,"y":46,"r":2.4},{"t":"dot","x":50,"y":58,"r":2.4},{"t":"dot","x":50,"y":70,"r":2.4},{"t":"text","x":57,"y":58,"text":"数据 8：偏差 0","size":2.8,"anchor":"start","tone":"muted"},{"t":"text","x":50,"y":88,"text":"偏差之和 −1 + 0 + 0 + 0 + 1 = 0，先平方再求平均","size":3,"anchor":"middle"}]}},{"type":"note","title":"","text":"偏差之和恒等于 0，所以不能把偏差直接相加求平均；必须先平方，再求这些平方的平均数。"},{"type":"h","text":"建立关系：偏差平方的平均数就是方差"},{"type":"p","text":"把偏差平方后再求平均，就得到方差。甲组偏差的平方为 1,0,0,0,1，方差 s²_(甲)=(1+0+0+0+1)/(5)=0.4；乙组偏差里出现了 -2 和 +1，平方后为 4,0,1,0,1，方差 s²_(乙)=(4+0+1+0+1)/(5)=1.2。乙组的偏差平方和更大，说明它偏离平均数更远，波动更大。"},{"type":"figure","figure":{"id":"fig-sta-fangcha-s3","title":"偏差的平方与方差","caption":"乙组偏差里有个 −2，平方后变成 4，把方差抬了上去","view":"square","alt":"左右两幅条形图对比偏差的平方：甲组五个偏差的平方是 1、0、0、0、1，算得方差 0.4；乙组是 4、0、1、0、1，最高的一根柱是偏差 −2 的平方 4，算得方差 1.2","prims":[{"t":"text","x":27,"y":12,"text":"甲组偏差的平方","size":3,"anchor":"middle","tone":"ok"},{"t":"axis","x":6,"y":62,"w":42,"h":44,"xLabel":"","yLabel":"","origin":false,"yTicks":[{"at":0.5,"label":"2"},{"at":1,"label":"4"}]},{"t":"rect","x":7.2,"y":51,"w":6,"h":11,"tone":"ok","fill":true},{"t":"rect","x":40.8,"y":51,"w":6,"h":11,"tone":"ok","fill":true},{"t":"text","x":18.6,"y":59,"text":"0","size":2.6,"anchor":"middle","tone":"muted"},{"t":"text","x":27,"y":59,"text":"0","size":2.6,"anchor":"middle","tone":"muted"},{"t":"text","x":35.4,"y":59,"text":"0","size":2.6,"anchor":"middle","tone":"muted"},{"t":"text","x":10.2,"y":48.5,"text":"1","size":2.8,"anchor":"middle"},{"t":"text","x":43.8,"y":48.5,"text":"1","size":2.8,"anchor":"middle"},{"t":"text","x":27,"y":74,"text":"方差 = (1+0+0+0+1) ÷ 5 = 0.4","size":2.6,"anchor":"middle"},{"t":"text","x":75,"y":12,"text":"乙组偏差的平方","size":3,"anchor":"middle","tone":"accent"},{"t":"axis","x":54,"y":62,"w":42,"h":44,"xLabel":"","yLabel":"","origin":false,"yTicks":[{"at":0.5,"label":"2"},{"at":1,"label":"4"}]},{"t":"rect","x":55.2,"y":18,"w":6,"h":44,"tone":"accent","fill":true},{"t":"rect","x":72,"y":51,"w":6,"h":11},{"t":"rect","x":88.8,"y":51,"w":6,"h":11},{"t":"text","x":66.6,"y":59,"text":"0","size":2.6,"anchor":"middle","tone":"muted"},{"t":"text","x":83.4,"y":59,"text":"0","size":2.6,"anchor":"middle","tone":"muted"},{"t":"text","x":58.2,"y":15.5,"text":"4","size":2.8,"anchor":"middle","tone":"accent"},{"t":"text","x":75,"y":48.5,"text":"1","size":2.8,"anchor":"middle"},{"t":"text","x":91.8,"y":48.5,"text":"1","size":2.8,"anchor":"middle"},{"t":"text","x":75,"y":74,"text":"方差 = (4+0+1+0+1) ÷ 5 = 1.2","size":2.6,"anchor":"middle"},{"t":"text","x":50,"y":90,"text":"乙方差 1.2 大于甲方差 0.4，说明乙的波动更大","size":3,"anchor":"middle"}]}},{"type":"note","title":"","text":"方差的单位是原数据单位的平方，式子里的分母是数据个数 n，不是 n−1。"},{"type":"h","text":"换个情境：标准差让单位回到原来"},{"type":"p","text":"方差的单位是原数据单位的平方，例如成绩单位是「环」，方差单位就是「环²」，不好解释。把方差开算术平方根就得到标准差 s，它的单位与原数据相同：数据 3, 4, 5, 6, 7 的方差是 2，标准差 s=√(2)≈ 1.41，可以说这组数据平均偏离平均数约 1.41 个单位。"},{"type":"figure","figure":{"id":"fig-sta-fangcha-s4","title":"标准差与原数据同单位","caption":"方差 2 开方得标准差约 1.41，标准差的单位与数据一致","view":"square","alt":"数轴示意图：数轴上标出数据 3、4、5、6、7，中间虚线标出平均数 5，以平均数为中心画一条双向箭头表示一个标准差约 1.41 的范围，下方注明方差 2、标准差约 1.41","prims":[{"t":"text","x":50,"y":30,"text":"平均数 5","size":3,"anchor":"middle","tone":"muted"},{"t":"line","x1":50,"y1":34,"x2":50,"y2":70,"dashed":true,"tone":"muted"},{"t":"arrow","x1":24.6,"y1":42,"x2":75.4,"y2":42,"both":true,"tone":"accent","label":"s ≈ 1.41","labelDy":-3},{"t":"dot","x":14,"y":52,"r":2,"tone":"accent"},{"t":"dot","x":32,"y":52,"r":2},{"t":"dot","x":50,"y":52,"r":2},{"t":"dot","x":68,"y":52,"r":2},{"t":"dot","x":86,"y":52,"r":2},{"t":"line","x1":10,"y1":52,"x2":90,"y2":52},{"t":"line","x1":14,"y1":49,"x2":14,"y2":55},{"t":"line","x1":32,"y1":49,"x2":32,"y2":55},{"t":"line","x1":50,"y1":49,"x2":50,"y2":55},{"t":"line","x1":68,"y1":49,"x2":68,"y2":55},{"t":"line","x1":86,"y1":49,"x2":86,"y2":55},{"t":"text","x":14,"y":60,"text":"3","size":2.8,"anchor":"middle"},{"t":"text","x":32,"y":60,"text":"4","size":2.8,"anchor":"middle"},{"t":"text","x":50,"y":60,"text":"5","size":2.8,"anchor":"middle"},{"t":"text","x":68,"y":60,"text":"6","size":2.8,"anchor":"middle"},{"t":"text","x":86,"y":60,"text":"7","size":2.8,"anchor":"middle"},{"t":"text","x":50,"y":80,"text":"方差 s² = 2，标准差 s = √2 ≈ 1.41","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":90,"text":"标准差与原数据同单位，方差的单位是原单位的平方","size":3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"标准差是方差的算术平方根，取非负值；两者都描述波动，说话时注意单位不同。"},{"type":"h","text":"核心概念"},{"type":"p","text":"极差：一组数据中最大值与最小值的差叫做这组数据的极差，它反映数据的波动范围。极差只用到两个数据，不能反映中间数据的分布情况。"},{"type":"p","text":"方差：各数据与平均数的差的平方的平均数叫做这组数据的方差，记作 s²。方差是衡量一组数据波动大小的统计量，方差越大，数据的波动越大，越不稳定。"},{"type":"p","text":"方差的计算步骤：第一步求这组数据的平均数 x；第二步求每个数据与平均数的差（偏差）；第三步求各偏差的平方；第四步求这些平方的平均数，即得方差。"},{"type":"p","text":"标准差：方差的算术平方根叫做标准差，记作 s。标准差与原数据的单位相同，也用来衡量数据的波动大小，标准差越小数据越稳定。"},{"type":"p","text":"方差越小越稳定：在平均数相同或接近的情况下，方差越小说明数据越集中在平均数附近、波动越小、越稳定。比赛选手中「发挥稳定」就用方差小来说明。"},{"type":"p","text":"方差的性质：把一组数据中的每个数据都加上（或减去）同一个常数 a，平均数改变但方差不变；把每个数据都乘同一个常数 k，方差变为原来的 k² 倍。"},{"type":"p","text":"方差的单位：方差的单位是原数据单位的平方，例如数据单位是「环」，方差单位就是「环²」；标准差的单位才与原数据相同。"},{"type":"note","title":"中考考法","text":"方差的完整计算\n解答题常以射击、测试成绩为背景，要求写出求平均数、求偏差、平方、再平均四步，少写一步就按步扣分。"},{"type":"note","title":"中考考法","text":"用方差比较稳定性并决策\n平均数相同或接近时再比方差，方差小者更稳定，常要求据此选择参赛人选或推广品种，结论必须回扣题目的选择问题。"},{"type":"note","title":"中考考法","text":"方差性质与标准差\n选择填空常考整体加常数方差不变、整体乘常数方差乘其平方，标准差是方差的算术平方根，单位与原数据相同。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["极差","极差等于一组数据中的最大值减去最小值。","极差只反映波动范围，不能完整反映数据的波动大小。"],["方差","方差等于各数据与平均数的差的平方的平均数。","初中阶段分母是数据个数 n，不是 n-1；偏差有正有负，必须先平方再求平均。"],["标准差","标准差是方差的算术平方根，单位与原数据相同。","开方时取算术平方根（非负数）。"],["方差的化简公式","方差等于各数据平方的平均数减去平均数的平方。","用于减少逐项求偏差的运算量，但求平均数这一步不能省。"],["数据变换后的方差","每个数据都乘 k 时，方差变为原来的 k² 倍；每个数据都加上同一个常数时，方差不变。","这里的 k 是常数，不是数据个数，不要与分母中的 n 混淆。"]]},{"type":"note","title":"例题","text":"甲、乙两名同学各射击 5 次，成绩（单位：环）如下：甲 7, 8, 8, 8, 9；乙 6, 8, 9, 8, 9。分别求两人的平均成绩和方差，并判断谁的射击成绩更稳定。"},{"type":"figure","figure":{"id":"fig-m-sta-fangcha-1","title":"甲、乙射击成绩折线对比","caption":"平均数同为 8 环：甲的折线更贴近 8 环，波动小、方差 0.4；乙波动大、方差 1.2","view":"wide","alt":"折线统计图：纵轴 5 到 10 环，横轴第 1 到第 5 次射击。甲的成绩 7、8、8、8、9 贴近 8 环参考线，乙的成绩 6、8、9、8、9 波动更大","prims":[{"t":"axis","x":14,"y":66,"w":70,"h":44,"xLabel":"射击次序","yLabel":"成绩（环）","origin":true,"xTicks":[{"at":0.1,"label":"1"},{"at":0.3,"label":"2"},{"at":0.5,"label":"3"},{"at":0.7,"label":"4"},{"at":0.9,"label":"5"}],"yTicks":[{"at":0,"label":"5"},{"at":0.2,"label":"6"},{"at":0.4,"label":"7"},{"at":0.6,"label":"8"},{"at":0.8,"label":"9"},{"at":1,"label":"10"}]},{"t":"line","x1":14,"y1":39.6,"x2":84,"y2":39.6,"dashed":true,"tone":"muted"},{"t":"text","x":86,"y":39,"text":"8 环","size":3,"tone":"muted"},{"t":"curve","points":[[21,48.4],[35,39.6],[49,39.6],[63,39.6],[77,30.8]]},{"t":"curve","points":[[21,57.2],[35,39.6],[49,30.8],[63,39.6],[77,30.8]],"dashed":true,"tone":"accent"},{"t":"dot","x":21,"y":48.4},{"t":"dot","x":35,"y":39.6},{"t":"dot","x":49,"y":39.6},{"t":"dot","x":63,"y":39.6},{"t":"dot","x":77,"y":30.8},{"t":"dot","x":21,"y":57.2,"hollow":true,"tone":"accent"},{"t":"dot","x":35,"y":39.6,"hollow":true,"tone":"accent"},{"t":"dot","x":49,"y":30.8,"hollow":true,"tone":"accent"},{"t":"dot","x":63,"y":39.6,"hollow":true,"tone":"accent"},{"t":"dot","x":77,"y":30.8,"hollow":true,"tone":"accent"},{"t":"text","x":50,"y":78,"text":"实线甲：7, 8, 8, 8, 9（方差 0.4，更稳定）","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":84,"text":"虚线乙：6, 8, 9, 8, 9（方差 1.2）","size":3.2,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["求平均数：x_(甲)=(7+8+8+8+9)/(5)=(40)/(5)=8；x_(乙)=(6+8+9+8+9)/(5)=(40)/(5)=8。","求甲的偏差：7-8=-1，8-8=0，8-8=0，8-8=0，9-8=1。","求甲各偏差的平方：1,0,0,0,1，平方和为 1+0+0+0+1=2。","求甲的方差：s²_(甲)=(2)/(5)=0.4。","求乙的偏差：6-8=-2，8-8=0，9-8=1，8-8=0，9-8=1。","求乙各偏差的平方：4,0,1,0,1，平方和为 4+0+1+0+1=6，方差 s²_(乙)=(6)/(5)=1.2。","比较方差：s²_(甲)=0.4<s²_(乙)=1.2，甲的成绩波动较小，更稳定。"]},{"type":"p","text":"答案：两人的平均成绩都是 8 环；s²_(甲)=0.4，s²_(乙)=1.2，甲的射击成绩更稳定。"},{"type":"note","title":"方法小结","text":"比较稳定性必须先看平均数是否相同或接近；如果两人平均数相差很大，不能只比方差，还要说明平均水平的差异。"},{"type":"note","title":"例题","text":"求数据 3, 4, 5, 6, 7 的方差和标准差。"},{"type":"figure","figure":{"id":"fig-sta-fangcha-e2","title":"数据 3, 4, 5, 6, 7 与平均数 5","caption":"五根柱子表示五个数据，虚线是平均数 5，越高的柱子离平均线越远","view":"square","alt":"柱状图：纵轴 0 到 8，五根柱子分别表示数据 3、4、5、6、7，横贯图中间有一条虚线标出平均数 5，数据 3 和 4 在线的下方，数据 6 和 7 在线的上方","prims":[{"t":"axis","x":18,"y":82,"w":68,"h":56,"origin":true,"xLabel":"数据","yLabel":"数值","yTicks":[{"at":0,"label":"0"},{"at":0.5,"label":"4"},{"at":1,"label":"8"}]},{"t":"rect","x":20,"y":61,"w":10,"h":21,"tone":"main","fill":true},{"t":"rect","x":34,"y":54,"w":10,"h":28,"tone":"main","fill":true},{"t":"rect","x":48,"y":47,"w":10,"h":35,"tone":"main","fill":true},{"t":"rect","x":62,"y":40,"w":10,"h":42,"tone":"main","fill":true},{"t":"rect","x":76,"y":33,"w":10,"h":49,"tone":"main","fill":true},{"t":"line","x1":18,"y1":47,"x2":86,"y2":47,"dashed":true,"tone":"accent"},{"t":"text","x":18,"y":41,"text":"平均数 5","size":2.8,"anchor":"start","tone":"accent"},{"t":"text","x":25,"y":57,"text":"3","size":3,"anchor":"middle"},{"t":"text","x":39,"y":50,"text":"4","size":3,"anchor":"middle"},{"t":"text","x":53,"y":43,"text":"5","size":3,"anchor":"middle"},{"t":"text","x":67,"y":36,"text":"6","size":3,"anchor":"middle"},{"t":"text","x":81,"y":29,"text":"7","size":3,"anchor":"middle"},{"t":"text","x":50,"y":89,"text":"偏差 −2, −1, 0, 1, 2（加起来正好为 0）","size":3,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":96,"text":"方差 s² = 10 ÷ 5 = 2，标准差 s = √2 ≈ 1.41","size":3,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["求平均数：x=(3+4+5+6+7)/(5)=(25)/(5)=5。","求各数据与平均数的差：3-5=-2，4-5=-1，5-5=0，6-5=1，7-5=2。","求各偏差的平方：4,1,0,1,4，平方和为 4+1+0+1+4=10。","求方差：s²=(10)/(5)=2。","求标准差：s=√(2)≈ 1.41。"]},{"type":"p","text":"答案：这组数据的方差是 2，标准差约为 1.41。"},{"type":"note","title":"方法小结","text":"偏差之和恒为 0，所以不能把偏差直接相加求平均，必须先平方再求平均。"},{"type":"note","title":"例题","text":"已知一组数据 1, 2, 3, 4, 5 的方差是 2。把这组数据中的每个数都乘 3，得到新数据 3, 6, 9, 12, 15，求新数据的方差。"},{"type":"figure","figure":{"id":"fig-sta-fangcha-e3","title":"每个数据都乘 3，波动也放大 3 倍","caption":"原数据 1, 2, 3, 4, 5 的方差是 2，每个数乘 3 后方差变成 9 倍，即 18","view":"square","alt":"上下两条数轴：上排标出 1 到 5 五个数据点，注明方差为 2；中间一个向下的箭头标注每个数乘以 3；下排在同样位置标出 3、6、9、12、15，注明方差为 18","prims":[{"t":"text","x":50,"y":12,"text":"原数据 1, 2, 3, 4, 5（方差 2）","size":3,"anchor":"middle"},{"t":"line","x1":14,"y1":30,"x2":86,"y2":30,"tone":"muted"},{"t":"dot","x":14,"y":30},{"t":"dot","x":32,"y":30},{"t":"dot","x":50,"y":30},{"t":"dot","x":68,"y":30},{"t":"dot","x":86,"y":30},{"t":"text","x":14,"y":38,"text":"1","size":2.8,"anchor":"middle"},{"t":"text","x":32,"y":38,"text":"2","size":2.8,"anchor":"middle"},{"t":"text","x":50,"y":38,"text":"3","size":2.8,"anchor":"middle"},{"t":"text","x":68,"y":38,"text":"4","size":2.8,"anchor":"middle"},{"t":"text","x":86,"y":38,"text":"5","size":2.8,"anchor":"middle"},{"t":"arrow","x1":50,"y1":46,"x2":50,"y2":62,"tone":"accent","label":"每个数 ×3","labelDx":22},{"t":"line","x1":14,"y1":74,"x2":86,"y2":74,"tone":"muted"},{"t":"dot","x":14,"y":74,"tone":"accent"},{"t":"dot","x":32,"y":74,"tone":"accent"},{"t":"dot","x":50,"y":74,"tone":"accent"},{"t":"dot","x":68,"y":74,"tone":"accent"},{"t":"dot","x":86,"y":74,"tone":"accent"},{"t":"text","x":14,"y":82,"text":"3","size":2.8,"anchor":"middle","tone":"accent"},{"t":"text","x":32,"y":82,"text":"6","size":2.8,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":82,"text":"9","size":2.8,"anchor":"middle","tone":"accent"},{"t":"text","x":68,"y":82,"text":"12","size":2.8,"anchor":"middle","tone":"accent"},{"t":"text","x":86,"y":82,"text":"15","size":2.8,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":92,"text":"新数据方差 18 = 2 × 3²，是原来的 9 倍","size":3,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["方法一（用性质）：每个数据都乘 k=3，方差变为原来的 k²=9 倍，所以 s'²=9× 2=18。","方法二（直接计算）验证：新数据的平均数 =(3+6+9+12+15)/(5)=(45)/(5)=9。","求偏差平方：(3-9)²=36，(6-9)²=9，(9-9)²=0，(12-9)²=9，(15-9)²=36。","平方和为 36+9+0+9+36=90，方差 =(90)/(5)=18。"]},{"type":"p","text":"答案：新数据的方差是 18。"},{"type":"note","title":"方法小结","text":"每个数据都加同一个常数时方差不变，每个数据都乘同一个常数时方差乘该常数的平方。"},{"type":"note","title":"例题","text":"已知一组数据 x₁,x₂,…,x₅ 的平均数是 3，方差是 2。设新数据为 y_i=2x_i-1（i=1,2,…,5），求新数据的平均数和方差。"},{"type":"figure","figure":{"id":"fig-sta-fangcha-e4","title":"数据先乘 2 再减 1 时怎么变","caption":"平均数跟着一起乘、一起减；方差只跟「乘 2」有关，放大 2 的平方即 4 倍","view":"square","alt":"三个方框用箭头依次连起来：第一个框写原数据、平均数 3、方差 2；箭头标注乘以 2，第二个框平均数变成 6、方差变成 8；箭头标注再减 1，第三个框平均数变成 5、方差仍然是 8","prims":[{"t":"text","x":50,"y":14,"text":"新数据 y = 2x − 1 时，平均数与方差怎么变","size":3.2,"anchor":"middle"},{"t":"rect","x":8,"y":34,"w":22,"h":24,"tone":"main"},{"t":"rect","x":39,"y":34,"w":22,"h":24,"tone":"main"},{"t":"rect","x":70,"y":34,"w":22,"h":24,"tone":"main"},{"t":"text","x":19,"y":41,"text":"原数据","size":2.9,"anchor":"middle"},{"t":"text","x":19,"y":48,"text":"x̄ = 3","size":2.8,"anchor":"middle"},{"t":"text","x":19,"y":55,"text":"s² = 2","size":2.8,"anchor":"middle"},{"t":"text","x":50,"y":41,"text":"乘 2 后","size":2.9,"anchor":"middle"},{"t":"text","x":50,"y":48,"text":"x̄ = 6","size":2.8,"anchor":"middle"},{"t":"text","x":50,"y":55,"text":"s² = 8","size":2.8,"anchor":"middle"},{"t":"text","x":81,"y":41,"text":"再减 1","size":2.9,"anchor":"middle"},{"t":"text","x":81,"y":48,"text":"x̄ = 5","size":2.8,"anchor":"middle"},{"t":"text","x":81,"y":55,"text":"s² = 8","size":2.8,"anchor":"middle","tone":"accent"},{"t":"arrow","x1":30,"y1":46,"x2":39,"y2":46,"tone":"main","label":"×2","labelDy":8},{"t":"arrow","x1":61,"y1":46,"x2":70,"y2":46,"tone":"main","label":"−1","labelDy":8},{"t":"text","x":50,"y":72,"text":"平均数：3 → 乘 2 得 6 → 再减 1 得 5","size":3,"anchor":"middle"},{"t":"text","x":50,"y":81,"text":"方差：只乘 2² = 4 倍，2 → 8；减 1 不改变波动","size":3,"anchor":"middle"},{"t":"text","x":50,"y":91,"text":"规律：y = kx + a 时，y 的平均数 = k x̄ + a，方差只乘 k²","size":3,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["分析数据的变换：每个数据先乘 2，再减去 1。","求新数据的平均数：每个数据乘 2 时平均数也乘 2，再减 1 时平均数再减 1，所以 y=2x-1=2× 3-1=5。","求新数据的方差：每个数据减同一个常数不改变方差，每个数据乘 2 时方差乘 2²=4。","所以 s_y²=2²× 2=8。"]},{"type":"p","text":"答案：新数据的平均数是 5，方差是 8。"},{"type":"note","title":"方法小结","text":"数据做「先乘 k 再加 a」的线性变换时，平均数做同样的变换，但方差只乘 k²，与加上的常数无关。"},{"type":"note","title":"例题","text":"甲、乙两组各有 5 个数据：甲组为 4, 6, 8, 10, 12，乙组为 4, 7, 8, 9, 12。分别求两组数据的极差和方差，并说明能否只凭极差比较两组数据的波动大小。"},{"type":"figure","figure":{"id":"fig-sta-fangcha-e5","title":"极差相同，波动不一定相同","caption":"甲、乙两组最大值都是 12、最小值都是 4，极差都是 8，但甲组中间数据离平均数更远","view":"square","alt":"一条从 4 到 12 的数轴，虚竖线标出平均数 8；上方甲组的点落在 4、6、8、10、12，下方乙组的点落在 4、7、8、9、12；两组极差都是 8，但甲组的点更分散，方差更大","prims":[{"t":"text","x":50,"y":12,"text":"两组极差都是 8，谁波动大？","size":3.4,"anchor":"middle"},{"t":"text","x":8,"y":24,"text":"甲组 4, 6, 8, 10, 12","size":2.8,"anchor":"start"},{"t":"dot","x":14,"y":32},{"t":"dot","x":32,"y":32},{"t":"dot","x":50,"y":32},{"t":"dot","x":68,"y":32},{"t":"dot","x":86,"y":32},{"t":"line","x1":50,"y1":20,"x2":50,"y2":44,"dashed":true,"tone":"muted"},{"t":"line","x1":50,"y1":60,"x2":50,"y2":74,"dashed":true,"tone":"muted"},{"t":"line","x1":10,"y1":46,"x2":90,"y2":46,"tone":"muted"},{"t":"text","x":14,"y":54,"text":"4","size":2.8,"anchor":"middle"},{"t":"text","x":32,"y":54,"text":"6","size":2.8,"anchor":"middle"},{"t":"text","x":50,"y":54,"text":"8","size":2.8,"anchor":"middle"},{"t":"text","x":68,"y":54,"text":"10","size":2.8,"anchor":"middle"},{"t":"text","x":86,"y":54,"text":"12","size":2.8,"anchor":"middle"},{"t":"dot","x":14,"y":66,"tone":"accent"},{"t":"dot","x":41,"y":66,"tone":"accent"},{"t":"dot","x":50,"y":66,"tone":"accent"},{"t":"dot","x":59,"y":66,"tone":"accent"},{"t":"dot","x":86,"y":66,"tone":"accent"},{"t":"text","x":8,"y":78,"text":"乙组 4, 7, 8, 9, 12","size":2.8,"anchor":"start","tone":"accent"},{"t":"text","x":50,"y":88,"text":"极差只看头尾：两组都是 8","size":3,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":96,"text":"方差看全部：甲组 8 大于乙组 6.8","size":3,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["求极差：甲组最大值为 12、最小值为 4，极差为 12-4=8；乙组最大值为 12、最小值为 4，极差也是 8。","两组平均数相同：甲组 x_甲=(4+6+8+10+12)/(5)=8，乙组 x_乙=(4+7+8+9+12)/(5)=8。","求甲组方差：偏差为 -4,-2,0,2,4，平方和为 16+4+0+4+16=40，s²_甲=(40)/(5)=8。","求乙组方差：偏差为 -4,-1,0,1,4，平方和为 16+1+0+1+16=34，s²_乙=(34)/(5)=6.8。两组极差相同但方差不同，说明极差只反映波动范围，不能完整衡量波动大小。"]},{"type":"p","text":"答案：两组数据的极差都是 8；s²_甲=8，s²_乙=6.8；不能只凭极差比较波动大小。"},{"type":"note","title":"方法小结","text":"极差只由最大值和最小值两个数据决定；这两组数据极差相同，但甲组中间数据离平均数更远，方差更大，比较波动要以方差为准。"},{"type":"list","title":"易错点","items":["方差公式的分母是数据个数 n，初中阶段不涉及分母为 n-1 的样本方差。","方差越小数据越稳定，不是越大越好；判断稳定性时方差越小越好。","不能把各偏差直接相加求「平均偏差」，因为偏差之和恒等于 0，必须先平方再求平均。","方差大小只说明波动大小，不能说明平均水平的高低；比较稳定性要在平均数相同或接近的前提下进行。","方差的单位是原数据单位的平方，标准差才与原数据同单位，作答时不要写错。","极差只由最大值和最小值决定，极差相同或很小的两组数据，波动情况不一定相同，不能只用极差判断稳定性。"]},{"type":"list","title":"解题方法","items":["求方差四步法：先求平均数 x → 再求各数据与平均数的差 → 再求各偏差的平方 → 最后求这些平方的平均数。","比较两组数据稳定性：先比平均数，若平均数相同或接近，再比方差，方差小的一组更稳定。","用性质简化运算：数据都加同一个常数时方差不变，数据都乘 k 时方差变为 k² 倍。","用化简公式 s²=(1)/(n)(x₁²+x₂²+…+x_n²)-x² 计算，可减少逐项求偏差的运算量。","实际问题先判断比较的是「平均水平」还是「波动大小」：比平均成绩用平均数，比发挥是否稳定用方差。"]}],"questions":[{"id":"q-sta-fangcha-1","type":"choice","stem":"一组数据 2, 4, 6 的平均数是 4，则这组数据的方差是（ ）","answer":"B","explain":"先求各数据与平均数的差：2-4=-2，4-4=0，6-4=2；再求偏差的平方：4,0,4；平方和为 4+0+4=8；最后求平方的平均数，方差 s²=(8)/(3)。选 8 是求了平方和而忘记除以数据个数。","options":["(2)/(3)","(8)/(3)","4","8"],"difficulty":1,"tags":["方差计算"]},{"id":"q-sta-fangcha-2","type":"fill","stem":"数据 1, 2, 3, 4, 5 的方差是＿＿。","answer":"2","explain":"平均数 x=(1+2+3+4+5)/(5)=3；各偏差为 -2,-1,0,1,2，平方为 4,1,0,1,4，平方和为 10；方差 s²=(10)/(5)=2。","difficulty":1,"tags":["方差计算"]},{"id":"q-sta-fangcha-3","type":"choice","stem":"甲、乙两名同学各进行 5 次测试，平均成绩相同，且 s²_(甲)=0.4，s²_(乙)=1.2。下列说法正确的是（ ）","answer":"C","explain":"两人平均成绩相同，比较稳定性只需比较方差。s²_(甲)=0.4<s²_(乙)=1.2，说明甲的成绩波动较小、更稳定。方差越小越稳定，所以选 C。","options":["甲的平均成绩比乙高","乙的成绩比甲稳定","甲的成绩比乙稳定","平均数相同，无法比较稳定性"],"difficulty":2,"tags":["方差","稳定性"]},{"id":"q-sta-fangcha-4","type":"choice","stem":"把一组数据中的每个数据都加上 5，得到一组新数据，则（ ）","answer":"B","explain":"每个数据都加 5，平均数也加 5，即平均数改变；而各数据与平均数的差（偏差）都没有变化，所以方差不变。","options":["平均数不变，方差不变","平均数改变，方差不变","平均数不变，方差改变","平均数、方差都改变"],"difficulty":2,"tags":["方差性质"]},{"id":"q-sta-fangcha-5","type":"short","stem":"某班要从甲、乙两人中选一人参加投篮比赛，两人 5 次投篮命中的个数如下：甲 6, 8, 8, 9, 9；乙 7, 7, 8, 9, 9。分别求出两人的平均数和方差，并说明应该选谁参赛。","answer":"甲：平均数 =(6+8+8+9+9)/(5)=(40)/(5)=8；偏差为 -2,0,0,1,1，平方为 4,0,0,1,1，平方和为 6，方差 =(6)/(5)=1.2。乙：平均数 =(7+7+8+9+9)/(5)=(40)/(5)=8；偏差为 -1,-1,0,1,1，平方为 1,1,0,1,1，平方和为 4，方差 =(4)/(5)=0.8。两人平均数相同，都是 8 个，而 0.8<1.2，说明乙的方差较小、成绩更稳定，所以应选乙参赛。","explain":"平均数相同的情况下，方差越小说明数据的波动越小、发挥越稳定。求方差必须写出完整步骤：先求平均数，再求各偏差的平方，最后求这些平方的平均数。","difficulty":2,"tags":["方差计算","实际决策"],"rubric":["正确求出两人的平均数都是 8 个","写出偏差平方的过程并求出甲的方差 1.2","求出乙的方差 0.8","由方差较小判断乙更稳定，得出选乙参赛的结论"]},{"id":"q-sta-fangcha-z1","type":"choice","stem":"一组数据的方差为 4。把这组数据中的每个数都乘 2，再加上 3，得到一组新数据，则新数据的方差是（ ）","answer":"D","explain":"每个数据加上同一个常数 3 不改变各数据与平均数的差，方差不变；每个数据乘 2 时方差乘 2²=4，所以新方差为 4× 4=16。选 8 是误乘了 2 而不是 2 的平方，选 11 是把加数 3 也加进了方差。","options":["4","8","11","16"],"difficulty":2,"tags":["方差性质"]},{"id":"q-sta-fangcha-z2","type":"fill","stem":"某地某一周每天的最低气温（单位：℃）依次为 -2, 0, 3, 5, 6, 8, 4，则这组数据的极差是＿＿。","answer":"10|10℃","explain":"极差等于最大值减去最小值。这组数据中最大值为 8，最小值为 -2，极差为 8-(-2)=10。最小值是负数时，先变号再相加，不要误算成 8-2=6。","difficulty":2,"tags":["极差"]}]},{"id":"m-sta-gailv-chubu","title":"概率初步","subtitle":"人教版九下 · 第34章 随机事件的概率","grade":"9b","tags":["统计与概率","随机事件的概率"],"blocks":[{"type":"note","title":"教材章节","text":"人教版九下 · 第34章 随机事件的概率"},{"type":"note","title":"一句话概述","text":"认识必然事件、不可能事件与随机事件，理解概率的意义，会用简单公式求事件的概率。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"掷一枚硬币，可能正面也可能反面；明天可能下雨也可能不下。概率就是把「有多可能发生」变成一个 0 到 1 之间的数。","walk":["在一定条件下，可能发生也可能不发生的事件叫随机事件；一定发生的是必然事件，一定不发生的是不可能事件。","概率的取值范围是 0 到 1。必然事件概率为 1，不可能事件概率为 0，随机事件在 0 和 1 之间。","大量重复试验中，事件发生的频率会稳定在某个常数附近，这个常数就是概率。频率是试验结果，概率是理论值。"],"try":"掷一枚硬币 20 次，记录正面次数，算一算频率；再掷 100 次，看看频率是不是更接近 0.5。","use":["概率题先判断事件类型，再用公式或列举法求值。","「频率」和「概率」不要混：频率是算出来的，概率是理论上的。"]},{"type":"h","text":"先分清：三类事件落在概率尺的哪里"},{"type":"p","text":"研究随机现象的第一步是分清事件会不会发生：一定发生的是必然事件，一定不发生的是不可能事件，可能发生也可能不发生的是随机事件。用「发生可能性有多大」这把尺子（取值 0 到 1）去量，必然事件落在右端 1 处，不可能事件落在左端 0 处，随机事件夹在 0 与 1 之间，位置越靠右越容易发生。"},{"type":"figure","figure":{"id":"fig-sta-glcb-s1","title":"三类事件在概率尺上的位置","caption":"必然事件在最右端 1，不可能事件在最左端 0，随机事件夹在两者之间","view":"square","alt":"一条标出 0、0.5、1 的概率刻度线：左端 0 处标不可能事件，右端 1 处标必然事件，中间用双向箭头标出随机事件的概率介于 0 与 1 之间","prims":[{"t":"arrow","x1":12,"y1":50,"x2":90,"y2":50,"label":"P"},{"t":"line","x1":12,"y1":47,"x2":12,"y2":53},{"t":"line","x1":51,"y1":47,"x2":51,"y2":53},{"t":"line","x1":90,"y1":47,"x2":90,"y2":53},{"t":"text","x":12,"y":61,"text":"0","size":3.2,"anchor":"middle"},{"t":"text","x":51,"y":61,"text":"0.5","size":3.2,"anchor":"middle"},{"t":"text","x":90,"y":61,"text":"1","size":3.2,"anchor":"middle"},{"t":"dot","x":12,"y":50,"r":2,"tone":"danger"},{"t":"dot","x":51,"y":50,"r":2,"tone":"main"},{"t":"dot","x":90,"y":50,"r":2,"tone":"ok"},{"t":"text","x":12,"y":32,"text":"不可能事件","size":3,"anchor":"start","tone":"danger"},{"t":"text","x":51,"y":32,"text":"随机事件","size":3,"anchor":"middle","tone":"main"},{"t":"text","x":90,"y":32,"text":"必然事件","size":3,"anchor":"end","tone":"ok"},{"t":"arrow","x1":12,"y1":72,"x2":90,"y2":72,"both":true,"dashed":true,"tone":"muted","label":"随机事件：0<P<1","labelDy":6},{"t":"text","x":50,"y":90,"text":"必然事件 P=1，不可能事件 P=0","size":3.2,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"事件分类都离不开「在一定条件下」这个前提，条件变了，同一件事的类型也可能变。"},{"type":"h","text":"抓条件：等可能才能用结果数相比"},{"type":"p","text":"要算可能性究竟是几分之几，得先把一次试验的所有结果都列出来。掷一枚质地均匀的骰子，结果是 1 到 6 共六种，而且每种出现的可能性一样大，这就叫等可能。只有在等可能的前提下，才能数一数所求事件占了其中几种，用 P(A)=(m)/(n) 求概率：点数是偶数占了 2、4、6 三种结果，所以 P=(3)/(6)=(1)/(2)。"},{"type":"figure","figure":{"id":"fig-sta-glcb-s2","title":"把所有等可能结果一一列出","caption":"掷一枚骰子共 6 种等可能结果，点数是偶数的占 3 种","view":"square","alt":"六个并排的方框依次写着 1 到 6，表示掷骰子的六种等可能结果，其中 2、4、6 三个方框用高亮标出，下方注明共有 6 种结果、符合条件的有 3 种，概率为二分之一","prims":[{"t":"text","x":50,"y":20,"text":"掷一枚质地均匀的骰子","size":3.2,"anchor":"middle"},{"t":"rect","x":8,"y":32,"w":13,"h":14},{"t":"rect","x":23,"y":32,"w":13,"h":14,"tone":"accent","fill":true},{"t":"rect","x":38,"y":32,"w":13,"h":14},{"t":"rect","x":53,"y":32,"w":13,"h":14,"tone":"accent","fill":true},{"t":"rect","x":68,"y":32,"w":13,"h":14},{"t":"rect","x":83,"y":32,"w":13,"h":14,"tone":"accent","fill":true},{"t":"text","x":14.5,"y":39,"text":"1","size":3.4,"anchor":"middle"},{"t":"text","x":29.5,"y":39,"text":"2","size":3.4,"anchor":"middle"},{"t":"text","x":44.5,"y":39,"text":"3","size":3.4,"anchor":"middle"},{"t":"text","x":59.5,"y":39,"text":"4","size":3.4,"anchor":"middle"},{"t":"text","x":74.5,"y":39,"text":"5","size":3.4,"anchor":"middle"},{"t":"text","x":89.5,"y":39,"text":"6","size":3.4,"anchor":"middle"},{"t":"text","x":50,"y":58,"text":"6 种等可能结果，各结果机会相同","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":70,"text":"点数是偶数的有 2、4、6 共 3 种","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":82,"text":"P(点数是偶数) = 3 ÷ 6 = 1/2","size":3.4,"anchor":"middle","tone":"accent"}]}},{"type":"note","title":"","text":"各结果不等可能时（如有轻重的球、面积不相等的转盘），不能直接用结果数之比算概率。"},{"type":"h","text":"做试验：频率会稳定到概率附近"},{"type":"p","text":"概率是事件本身固有的理论值，试验中真正算出来的比值叫频率，两者不是一回事。抛一枚硬币，次数少的时候正面朝上的频率忽高忽低（10 次里出现 7 次正面也不奇怪），可次数一多，摆动的幅度越来越小，最后围绕 0.5 上下微微起伏。可见在大量重复试验中，频率会稳定在概率附近，这也正是「可以用频率估计概率」的依据。"},{"type":"figure","figure":{"id":"fig-sta-glcb-s3","title":"抛硬币的频率逐渐稳定在 0.5","caption":"试验次数越多，正面朝上的频率摆动越小，最后稳定在 0.5 附近","view":"square","alt":"折线图：纵轴是频率、横轴是试验次数，折线一开始上下大幅摆动，随着试验次数增加摆动越来越小，最后贴着 0.5 的水平虚线趋于稳定","prims":[{"t":"axis","x":16,"y":76,"w":68,"h":52,"xLabel":"试验次数","yLabel":"频率","origin":true,"yTicks":[{"at":0.5,"label":"0.5"},{"at":1,"label":"1"}]},{"t":"line","x1":16,"y1":50,"x2":84,"y2":50,"dashed":true,"tone":"muted"},{"t":"curve","points":[[20,40],[28,60],[36,44],[44,55],[52,47],[60,52],[68,49],[76,51],[84,50]],"tone":"accent"},{"t":"text","x":50,"y":90,"text":"次数越多，频率越稳定 → 用频率估计概率","size":3.2,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"只有「大量重复试验」时频率才稳定，几十次的频率波动很大，不能当作概率。"},{"type":"h","text":"换个情境：用频率估计概率再推算数量"},{"type":"p","text":"频率稳定下来能办两件事：估计概率，以及反过来推算数量。思路是「大量重复试验 → 频率稳定 → 用稳定值作为概率 → 总数乘概率得数量」。例如袋中红、白球共 20 个，反复有放回地摸球后摸到红球的频率稳定在 0.35 附近，就把 0.35 当作概率，于是红球约有 20× 0.35=7 个，白球约有 13 个。"},{"type":"figure","figure":{"id":"fig-sta-glcb-s4","title":"频率估计概率再推算数量的思路","caption":"频率稳定后当作概率，再乘总数得到某类个体的数量","view":"square","alt":"三个方框用箭头依次连起来：第一个框写大量重复试验、频率稳定在 0.35；第二个框写估计概率 P 约等于 0.35；第三个框写推算数量 20 乘 0.35 得 7","prims":[{"t":"text","x":50,"y":18,"text":"用频率估计概率，再推算数量","size":3.4,"anchor":"middle"},{"t":"rect","x":6,"y":32,"w":26,"h":20,"tone":"main"},{"t":"text","x":19,"y":39,"text":"大量重复试验","size":2.8,"anchor":"middle"},{"t":"text","x":19,"y":47,"text":"频率稳定 0.35","size":2.8,"anchor":"middle"},{"t":"rect","x":37,"y":32,"w":26,"h":20,"tone":"accent"},{"t":"text","x":50,"y":39,"text":"估计概率","size":2.8,"anchor":"middle"},{"t":"text","x":50,"y":47,"text":"P ≈ 0.35","size":2.8,"anchor":"middle","tone":"accent"},{"t":"rect","x":68,"y":32,"w":26,"h":20,"tone":"main"},{"t":"text","x":81,"y":39,"text":"推算数量","size":2.8,"anchor":"middle"},{"t":"text","x":81,"y":47,"text":"20×0.35=7","size":2.8,"anchor":"middle"},{"t":"arrow","x1":32,"y1":42,"x2":37,"y2":42,"tone":"muted"},{"t":"arrow","x1":63,"y1":42,"x2":68,"y2":42,"tone":"muted"},{"t":"text","x":50,"y":66,"text":"频率 → 概率 → 数量，三步一脉相承","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":78,"text":"前提是频率在大量重复试验后确实稳定下来了","size":3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"用频率估计出的个数是近似值，作答要写「估计」，不能写成确定的数。"},{"type":"h","text":"核心概念"},{"type":"p","text":"必然事件：在一定条件下必然会发生的事件叫做必然事件，例如「太阳从东方升起」「标准大气压下 100 ℃ 的水会沸腾」。必然事件的概率为 1。"},{"type":"p","text":"不可能事件：在一定条件下不可能发生的事件叫做不可能事件，例如「掷一枚骰子得到 7 点」「从装有红球的袋中摸出白球」。不可能事件的概率为 0。"},{"type":"p","text":"随机事件：在一定条件下可能发生也可能不发生的事件叫做随机事件，例如「掷一枚硬币正面朝上」「明天是晴天」。随机事件的概率在 0 与 1 之间。"},{"type":"p","text":"确定性事件：必然事件与不可能事件统称确定性事件，它们在一定条件下是否发生是确定的；随机事件则不确定。"},{"type":"p","text":"概率的意义：概率是刻画随机事件 A 发生可能性大小的数值，记作 P(A)。概率越大，事件发生的可能性越大；概率是事件本身固有的理论值，不随试验结果改变。"},{"type":"p","text":"等可能事件：在一次试验中，如果每个结果出现的可能性都相等，这些结果就叫做等可能结果。只有所有结果都是等可能的，才能用结果数之比计算概率。"},{"type":"p","text":"频率与概率的关系：频率是试验中算出的比值，会随试验次数变化；在大量重复试验中，事件发生的频率会逐渐稳定在某个常数附近，这个常数就是该事件概率的估计值，即可以用频率估计概率。"},{"type":"p","text":"概率的取值范围：任何事件 A 的概率都满足 0≤ P(A)≤ 1。其中必然事件的概率为 1，不可能事件的概率为 0，随机事件的概率严格介于 0 与 1 之间。"},{"type":"note","title":"中考考法","text":"事件分类与概率取值\n选择题考必然事件、不可能事件、随机事件的判断及概率 0 与 1 的归属，随机事件的概率严格介于 0 和 1 之间。"},{"type":"note","title":"中考考法","text":"等可能条件下的简单概率\n以摸球、掷骰、抽卡片为情境，用 P(A)=(m)/(n) 一步求概率，前提是结果等可能，总数 n 与符合结果数 m 要数准。"},{"type":"note","title":"中考考法","text":"用频率估计概率并推算数量\n给多批次试验数据算频率，由频率的稳定值估计概率，再乘总数估计某类个体的个数，答题要强调「大量重复试验」。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["简单随机事件的概率","在一次试验中，若共有 n 种等可能的结果，事件 A 包含其中的 m 种结果，则事件 A 发生的概率为 (m)/(n)。","前提是试验的所有结果都是等可能的；m 不大于 n，所以概率不超过 1。"],["概率的取值范围","任何事件的概率都不小于 0 且不大于 1。","必然事件的概率为 1，不可能事件的概率为 0。"],["必然事件与不可能事件的概率","必然事件的概率为 1；不可能事件的概率为 0。即 P(必然事件)=1，P(不可能事件)=0。","概率为 1 的事件一定发生，概率为 0 的事件一定不发生。"],["用频率估计概率","在相同条件下进行 n 次重复试验，事件 A 发生了 m 次，当 n 很大时，频率 (m)/(n) 可以作为事件 A 概率的估计值。","必须经过大量重复试验，试验次数太少时频率波动大、不可靠。"]]},{"type":"note","title":"例题","text":"掷一枚质地均匀的骰子，求下列事件的概率：（1）掷得的点数是 6；（2）掷得的点数大于 4；（3）掷得的点数是偶数。"},{"type":"figure","figure":{"id":"fig-m-sta-gailv-1","title":"概率的大小与事件类型","caption":"骰子各事件的概率都落在 0 与 1 之间：0 是不可能事件，1 是必然事件","view":"wide","alt":"概率数轴：从 0 到 1，标出掷骰子掷出 6 的概率六分之一、点数大于 4 的概率三分之一、点数是偶数的概率二分之一，三个概率都在 0 与 1 之间","prims":[{"t":"arrow","x1":10,"y1":50,"x2":92,"y2":50,"label":"P"},{"t":"line","x1":14,"y1":47.5,"x2":14,"y2":52.5},{"t":"line","x1":26,"y1":47.5,"x2":26,"y2":52.5},{"t":"line","x1":38,"y1":47.5,"x2":38,"y2":52.5},{"t":"line","x1":50,"y1":47.5,"x2":50,"y2":52.5},{"t":"line","x1":86,"y1":47.5,"x2":86,"y2":52.5},{"t":"text","x":14,"y":60,"text":"0","size":3.2,"anchor":"middle"},{"t":"text","x":86,"y":60,"text":"1","size":3.2,"anchor":"middle"},{"t":"dot","x":26,"y":50,"tone":"accent"},{"t":"dot","x":38,"y":50,"tone":"accent"},{"t":"dot","x":50,"y":50,"tone":"accent"},{"t":"line","x1":26,"y1":50,"x2":26,"y2":36,"dashed":true,"tone":"accent"},{"t":"text","x":26,"y":32,"text":"掷出 6：P=1/6","size":3.2,"anchor":"middle","tone":"accent"},{"t":"line","x1":38,"y1":50,"x2":38,"y2":64,"dashed":true,"tone":"accent"},{"t":"text","x":38,"y":68,"text":"大于 4：P=1/3","size":3.2,"anchor":"middle","tone":"accent"},{"t":"line","x1":50,"y1":50,"x2":50,"y2":36,"dashed":true,"tone":"accent"},{"t":"text","x":50,"y":32,"text":"偶数：P=1/2","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":84,"text":"不可能事件 P=0 · 必然事件 P=1 · 随机事件 0<P<1","size":3.2,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["列出所有等可能结果：1, 2, 3, 4, 5, 6，共 n=6 种，各结果出现的可能性相同。","（1）点数是 6 的结果只有 1 种，m=1，P=(1)/(6)。","（2）点数大于 4 的结果有 5, 6，共 2 种，m=2，P=(2)/(6)=(1)/(3)。","（3）点数是偶数的结果有 2, 4, 6，共 3 种，m=3，P=(3)/(6)=(1)/(2)。"]},{"type":"p","text":"答案：（1）(1)/(6)；（2）(1)/(3)；（3）(1)/(2)。"},{"type":"note","title":"方法小结","text":"先数清所有等可能结果的总数 n，再数清所求事件包含的结果数 m，最后代入 P(A)=(m)/(n)。"},{"type":"note","title":"例题","text":"一个不透明的袋子里装有 3 个红球和 2 个白球，这些球除颜色外都相同。从袋中任意摸出一个球，求摸出红球的概率。"},{"type":"figure","figure":{"id":"fig-sta-glcb-e2","title":"数出袋中的球再求概率","caption":"每个球被摸出的可能性相同，总结果数 5，红球占 3 种","view":"square","alt":"并排画着五个小球，前三个标红、后两个标白，上方注明袋中共 5 个球且除颜色外都相同，下方注明摸出红球的结果有 3 种、概率为五分之三","prims":[{"t":"text","x":50,"y":22,"text":"袋中 5 个球（3 红 2 白），除颜色外都相同","size":3,"anchor":"middle"},{"t":"circle","cx":18,"cy":44,"r":6,"tone":"danger","fill":true},{"t":"circle","cx":34,"cy":44,"r":6,"tone":"danger","fill":true},{"t":"circle","cx":50,"cy":44,"r":6,"tone":"danger","fill":true},{"t":"circle","cx":66,"cy":44,"r":6,"tone":"muted","fill":true},{"t":"circle","cx":82,"cy":44,"r":6,"tone":"muted","fill":true},{"t":"text","x":18,"y":45.4,"text":"红","size":3,"anchor":"middle"},{"t":"text","x":34,"y":45.4,"text":"红","size":3,"anchor":"middle"},{"t":"text","x":50,"y":45.4,"text":"红","size":3,"anchor":"middle"},{"t":"text","x":66,"y":45.4,"text":"白","size":3,"anchor":"middle"},{"t":"text","x":82,"y":45.4,"text":"白","size":3,"anchor":"middle"},{"t":"text","x":50,"y":62,"text":"等可能结果总数 n = 5","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":74,"text":"摸出红球的结果数 m = 3，P = 3/5","size":3.4,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["确定所有等可能结果：袋中共有 3+2=5 个球，每个球被摸出的可能性相同，所以 n=5。","确定事件包含的结果数：红球有 3 个，摸出红球的结果有 3 种，m=3。","代入公式：P(摸出红球)=(3)/(5)。"]},{"type":"p","text":"答案：摸出红球的概率是 (3)/(5)。"},{"type":"note","title":"方法小结","text":"「除颜色外都相同」和「任意摸出」是各结果等可能的前提，缺少这一条件就不能直接用公式。"},{"type":"note","title":"例题","text":"某农科所在相同条件下做玉米种子发芽试验：试验 1000 粒，发芽 950 粒；试验 2000 粒，发芽 1910 粒。请估计这种玉米种子发芽的概率。"},{"type":"figure","figure":{"id":"fig-sta-glcb-e3","title":"两次试验的发芽频率","caption":"两次发芽频率都接近 0.95，可用它估计发芽的概率","view":"square","alt":"一张两行三列的表格，列头依次是试验粒数、发芽粒数、频率；第一行 1000、950、0.95，第二行 2000、1910、0.955；下方注明两次频率都接近 0.95，估计发芽概率约为 0.95","prims":[{"t":"text","x":50,"y":16,"text":"玉米种子发芽试验","size":3.4,"anchor":"middle"},{"t":"line","x1":14,"y1":26,"x2":86,"y2":26},{"t":"line","x1":14,"y1":40,"x2":86,"y2":40},{"t":"line","x1":14,"y1":54,"x2":86,"y2":54},{"t":"line","x1":14,"y1":68,"x2":86,"y2":68},{"t":"line","x1":14,"y1":26,"x2":14,"y2":68},{"t":"line","x1":40,"y1":26,"x2":40,"y2":68},{"t":"line","x1":62,"y1":26,"x2":62,"y2":68},{"t":"line","x1":86,"y1":26,"x2":86,"y2":68},{"t":"text","x":27,"y":33.5,"text":"试验粒数","size":2.8,"anchor":"middle","tone":"muted"},{"t":"text","x":51,"y":33.5,"text":"发芽粒数","size":2.8,"anchor":"middle","tone":"muted"},{"t":"text","x":74,"y":33.5,"text":"频率","size":2.8,"anchor":"middle","tone":"muted"},{"t":"text","x":27,"y":47.5,"text":"1000","size":3,"anchor":"middle"},{"t":"text","x":51,"y":47.5,"text":"950","size":3,"anchor":"middle"},{"t":"text","x":74,"y":47.5,"text":"0.95","size":3,"anchor":"middle","tone":"accent"},{"t":"text","x":27,"y":61.5,"text":"2000","size":3,"anchor":"middle"},{"t":"text","x":51,"y":61.5,"text":"1910","size":3,"anchor":"middle"},{"t":"text","x":74,"y":61.5,"text":"0.955","size":3,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":80,"text":"两次频率都接近 0.95，估计发芽概率约为 0.95","size":3.2,"anchor":"middle","tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["求第一次试验的发芽频率：(950)/(1000)=0.95。","求第二次试验的发芽频率：(1910)/(2000)=0.955。","两次频率都接近 0.95，而且试验粒数较多时频率趋于稳定，可以用频率估计概率。"]},{"type":"p","text":"答案：这种玉米种子发芽的概率约为 0.95（即 95%）。"},{"type":"note","title":"方法小结","text":"用频率估计概率必须依据大量重复试验，试验次数太少时频率波动较大，不能作为可靠的估计。"},{"type":"note","title":"例题","text":"一个不透明的袋子里装有红球和白球共 20 个，这些球除颜色外都相同。每次搅匀后从中任意摸出一个球，记下颜色再放回，进行大量重复试验后，发现摸到红球的频率稳定在 0.35 附近。请估计袋中红球和白球各有多少个。"},{"type":"figure","figure":{"id":"fig-sta-glcb-e4","title":"用频率估计出的红球与白球个数","caption":"频率 0.35 当作概率，20 个球中红球约 7 个、白球约 13 个","view":"square","alt":"一条表示袋中 20 个球的长条，左端一小段高亮标红球，右端较长一段标白球；上方注明摸到红球的频率稳定在 0.35，下方注明红球约 20 乘 0.35 得 7 个、白球约 13 个","prims":[{"t":"text","x":50,"y":22,"text":"摸到红球的频率稳定在 0.35","size":3.2,"anchor":"middle"},{"t":"rect","x":12,"y":46,"w":76,"h":16,"tone":"muted","fill":true},{"t":"rect","x":12,"y":46,"w":26.6,"h":16,"tone":"danger","fill":true},{"t":"text","x":25,"y":42,"text":"红球","size":3.2,"anchor":"middle","tone":"danger"},{"t":"text","x":64,"y":42,"text":"白球","size":3.2,"anchor":"middle","tone":"muted"},{"t":"text","x":50,"y":76,"text":"红球个数 ≈ 20 × 0.35 = 7（个）","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":88,"text":"白球个数 = 20 − 7 = 13（个）","size":3.2,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["试验是有放回的大量重复摸球，摸到红球的频率稳定在 0.35 附近，因此估计摸到红球的概率为 0.35。","用概率估计袋中红球的个数：20× 0.35=7（个）。","袋中球的总数为 20 个，所以白球约有 20-7=13（个）。"]},{"type":"p","text":"答案：估计袋中红球约有 7 个，白球约有 13 个。"},{"type":"note","title":"方法小结","text":"由频率估计概率，再用「总数 × 概率」估计某类个体的数量，是频率估计概率的进一步应用，结果要写「估计」。"},{"type":"note","title":"例题","text":"把分别写有数字 1, 2, 3, …, 10 的 10 张卡片背面朝上洗匀，从中任意抽取一张。求下列事件的概率：（1）抽到的数是 3 的倍数；（2）抽到的数大于 6；（3）抽到的数既是偶数又是素数。"},{"type":"figure","figure":{"id":"fig-sta-glcb-e5","title":"从 1 到 10 中逐一数出符合条件的结果","caption":"总结果数都是 10，三个小问各自数出符合条件的结果数","view":"square","alt":"一张列有 1 到 10 的卡片横排；下面是一张表，列出三个小问符合条件的结果与概率：3 的倍数有 3、6、9，概率十分之三；大于 6 的有 7、8、9、10，概率五分之二；既是偶数又是素数只有 2，概率十分之一","prims":[{"t":"text","x":50,"y":8,"text":"10 张卡片分别写有 1～10","size":3,"anchor":"middle"},{"t":"rect","x":9,"y":13,"w":7.5,"h":9},{"t":"rect","x":17,"y":13,"w":7.5,"h":9},{"t":"rect","x":25,"y":13,"w":7.5,"h":9},{"t":"rect","x":33,"y":13,"w":7.5,"h":9},{"t":"rect","x":41,"y":13,"w":7.5,"h":9},{"t":"rect","x":49,"y":13,"w":7.5,"h":9},{"t":"rect","x":57,"y":13,"w":7.5,"h":9},{"t":"rect","x":65,"y":13,"w":7.5,"h":9},{"t":"rect","x":73,"y":13,"w":7.5,"h":9},{"t":"rect","x":81,"y":13,"w":7.5,"h":9},{"t":"text","x":12.75,"y":18.6,"text":"1","size":2.6,"anchor":"middle"},{"t":"text","x":20.75,"y":18.6,"text":"2","size":2.6,"anchor":"middle"},{"t":"text","x":28.75,"y":18.6,"text":"3","size":2.6,"anchor":"middle"},{"t":"text","x":36.75,"y":18.6,"text":"4","size":2.6,"anchor":"middle"},{"t":"text","x":44.75,"y":18.6,"text":"5","size":2.6,"anchor":"middle"},{"t":"text","x":52.75,"y":18.6,"text":"6","size":2.6,"anchor":"middle"},{"t":"text","x":60.75,"y":18.6,"text":"7","size":2.6,"anchor":"middle"},{"t":"text","x":68.75,"y":18.6,"text":"8","size":2.6,"anchor":"middle"},{"t":"text","x":76.75,"y":18.6,"text":"9","size":2.6,"anchor":"middle"},{"t":"text","x":84.75,"y":18.6,"text":"10","size":2.6,"anchor":"middle"},{"t":"line","x1":12,"y1":34,"x2":88,"y2":34},{"t":"line","x1":12,"y1":46,"x2":88,"y2":46},{"t":"line","x1":12,"y1":58,"x2":88,"y2":58},{"t":"line","x1":12,"y1":70,"x2":88,"y2":70},{"t":"line","x1":12,"y1":82,"x2":88,"y2":82},{"t":"line","x1":12,"y1":34,"x2":12,"y2":82},{"t":"line","x1":42,"y1":34,"x2":42,"y2":82},{"t":"line","x1":68,"y1":34,"x2":68,"y2":82},{"t":"line","x1":88,"y1":34,"x2":88,"y2":82},{"t":"text","x":27,"y":41,"text":"所求事件","size":2.8,"anchor":"middle","tone":"muted"},{"t":"text","x":55,"y":41,"text":"符合的结果","size":2.8,"anchor":"middle","tone":"muted"},{"t":"text","x":78,"y":41,"text":"概率","size":2.8,"anchor":"middle","tone":"muted"},{"t":"text","x":27,"y":53,"text":"3 的倍数","size":2.8,"anchor":"middle"},{"t":"text","x":55,"y":53,"text":"3, 6, 9","size":2.8,"anchor":"middle"},{"t":"text","x":78,"y":53,"text":"3/10","size":2.8,"anchor":"middle","tone":"accent"},{"t":"text","x":27,"y":65,"text":"大于 6","size":2.8,"anchor":"middle"},{"t":"text","x":55,"y":65,"text":"7, 8, 9, 10","size":2.8,"anchor":"middle"},{"t":"text","x":78,"y":65,"text":"2/5","size":2.8,"anchor":"middle","tone":"accent"},{"t":"text","x":27,"y":77,"text":"偶数又是素数","size":2.8,"anchor":"middle"},{"t":"text","x":55,"y":77,"text":"2","size":2.8,"anchor":"middle"},{"t":"text","x":78,"y":77,"text":"1/10","size":2.8,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":93,"text":"总数 n 都是 10，再逐一数清符合条件的结果数","size":3,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["所有等可能结果共有 10 种，即抽到数字 1 到 10，所以 n=10。","（1）3 的倍数有 3, 6, 9，共 3 种，P=(3)/(10)。","（2）大于 6 的数有 7, 8, 9, 10，共 4 种，P=(4)/(10)=(2)/(5)。","（3）10 以内的素数有 2, 3, 5, 7，其中只有 2 是偶数，符合条件的结果只有 1 种，P=(1)/(10)。"]},{"type":"p","text":"答案：（1）(3)/(10)；（2）(2)/(5)；（3）(1)/(10)。"},{"type":"note","title":"方法小结","text":"「既是偶数又是素数」要同时满足两个条件，10 以内只有数字 2 符合；逐一数清每个限定词包含的结果，是求概率的关键。"},{"type":"list","title":"易错点","items":["概率是理论上的确定值，频率是试验中算出的比值；频率会随试验次数变化，只有大量重复试验后频率才稳定在概率附近，不能说「一次试验的频率就是概率」。","概率大只表示发生的可能性大，不等于一定会发生；概率小也不等于一定不发生。","求概率前必须先判断各个结果是否等可能，结果不等可能时不能直接用 P(A)=(m)/(n)。","概率的取值范围是 0 到 1，不能大于 1，也不能为负数；写成分数或百分数时要注意其值不超过 1。","「至少」「恰好」「不超过」「大于」等词语决定了事件包含哪些结果，要按题意逐一数清，不能凭感觉。","把必然事件的概率当成「很大的数」、把随机事件的概率当成「不确定的数」都是概念错误：概率是刻画可能性大小的数值，必然事件为 1，不可能事件为 0。"]},{"type":"list","title":"解题方法","items":["判断事件类型：一定发生的是必然事件（概率为 1），一定不发生的是不可能事件（概率为 0），可能发生也可能不发生的是随机事件。","求简单事件概率三步：列出所有等可能结果并数出总数 n → 数出事件 A 包含的结果数 m → 代入 P(A)=(m)/(n)。","用频率估计概率：在相同条件下做足够多次重复试验，用事件发生的频率作为概率的估计值。","检验结果：算出的概率应在 0 与 1 之间；若把一次试验中所有可能事件的概率相加，结果应为 1。","把题目语言翻译成事件：如「摸出红球」「点数大于 4」「恰好两次命中」，先说清事件再数结果。"]}],"questions":[{"id":"q-sta-gailv-1","type":"choice","stem":"下列事件中，属于必然事件的是（ ）","answer":"C","explain":"「太阳从东方升起」在一定条件下必然发生，是必然事件。A、B 可能发生也可能不发生，是随机事件；D 一定不会发生，是不可能事件。","options":["明天是晴天","掷一枚质地均匀的硬币，正面朝上","太阳从东方升起","从装有红球的袋子中摸出一个白球"],"difficulty":1,"tags":["必然事件","随机事件"]},{"id":"q-sta-gailv-2","type":"fill","stem":"掷一枚质地均匀的骰子，掷得的点数是奇数的概率是＿＿。","answer":"1/2","explain":"所有等可能结果有 6 种：1, 2, 3, 4, 5, 6。点数是奇数的结果有 1, 3, 5，共 3 种，所以概率 =(3)/(6)=(1)/(2)。","difficulty":1,"tags":["简单事件概率"]},{"id":"q-sta-gailv-3","type":"choice","stem":"一个不透明的袋子中装有 3 个红球和 2 个白球，这些球除颜色外都相同，从中任意摸出一个球，摸出白球的概率是（ ）","answer":"B","explain":"袋中共有 5 个球，每个球被摸出的可能性相同，所以 n=5；白球有 2 个，m=2，故摸出白球的概率是 (2)/(5)。(3)/(5) 是摸出红球的概率。","options":["(1)/(5)","(2)/(5)","(3)/(5)","(2)/(3)"],"difficulty":1,"tags":["简单事件概率"]},{"id":"q-sta-gailv-4","type":"choice","stem":"下列说法正确的是（ ）","answer":"C","explain":"必然事件一定发生，其概率为 1，C 正确。概率小只说明发生的可能性小，不等于一定不发生，A 错；抛硬币正面向上的概率是 (1)/(2)，但 10 次试验中正面朝上的次数不一定恰好是 5 次，B 错；概率不能超过 1，D 错。","options":["概率为 0.01 的事件不可能发生","抛一枚硬币 10 次，一定有 5 次正面朝上","必然事件的概率是 1","随机事件的概率可以是 1.5"],"difficulty":2,"tags":["概率的意义","概念辨析"]},{"id":"q-sta-gailv-5","type":"short","stem":"某射手在同一条件下进行射击，结果如下：射击 500 次，命中 445 次；射击 1000 次，命中 892 次；射击 2000 次，命中 1780 次。请计算各次试验中命中的频率，并估计这名射手射击一次命中的概率。","answer":"三次试验的命中频率分别为：(445)/(500)=0.89；(892)/(1000)=0.892；(1780)/(2000)=0.89。三次频率都稳定在 0.89 附近，随着射击次数增加，频率趋于稳定，因此可以估计这名射手射击一次命中的概率约为 0.89（即 89%）。","explain":"用频率估计概率时，要看多次重复试验中频率是否稳定在某个常数附近；三次频率都接近 0.89，说明估计值较为可靠。若只做几十次试验，频率波动大，就不能据此估计概率。","difficulty":2,"tags":["频率估计概率","实际情境"],"rubric":["正确算出三次命中频率 0.89、0.892、0.89","指出频率稳定在 0.89 附近","估计概率约为 0.89（或 89%）","说明依据是大量重复试验中频率的稳定性"]},{"id":"q-sta-gailv-z1","type":"choice","stem":"下列关于频率与概率的说法，正确的是（ ）","answer":"B","explain":"频率是试验值，会随试验次数变化，概率是理论上的确定值，二者不能等同，A 错；大量重复试验时频率稳定在概率附近，B 正确；概率为 0.5 只说明发生与不发生的可能性相同，1000 次试验中发生的次数不一定恰好是 500，C 错；概率为 0 的事件是不可能事件，一定不会发生，D 错。","options":["某次试验中事件发生的频率就是这个事件的概率","大量重复试验中，事件发生的频率会逐渐稳定在它的概率附近","若某事件发生的概率为 0.5，则做 1000 次试验该事件一定发生 500 次","概率为 0 的事件在某次试验中仍有可能发生"],"difficulty":2,"tags":["频率估计概率","概率的意义"]},{"id":"q-sta-gailv-z2","type":"short","stem":"判断下列事件分别属于必然事件、不可能事件还是随机事件，并写出其中必然事件与不可能事件的概率：（1）在标准大气压下，把水加热到 100 ℃，水沸腾；（2）掷一枚质地均匀的骰子，掷得的点数是 0；（3）买一张体育彩票，中奖。","answer":"（1）在标准大气压下水加热到 100 ℃ 必然沸腾，是必然事件，其概率为 1；（2）骰子的点数只有 1 到 6，掷得点数 0 一定不会发生，是不可能事件，其概率为 0；（3）买一张彩票可能中奖也可能不中奖，是随机事件，其概率在 0 与 1 之间。","explain":"一定条件下必然发生的是必然事件，概率为 1；一定不发生的是不可能事件，概率为 0；可能发生也可能不发生的是随机事件，概率介于 0 和 1 之间。注意事件分类都离不开「在一定条件下」这个前提。","difficulty":2,"tags":["必然事件","不可能事件","随机事件"],"rubric":["正确判断三个事件的类型：必然、不可能、随机","写出必然事件的概率为 1、不可能事件的概率为 0","说明随机事件的概率在 0 与 1 之间，分类前提清楚"]}]},{"id":"m-sta-gailv-jisuan","title":"概率的计算：列举法与树状图","subtitle":"人教版九下 · 第34章 随机事件的概率","grade":"9b","tags":["统计与概率","随机事件的概率"],"blocks":[{"type":"note","title":"教材章节","text":"人教版九下 · 第34章 随机事件的概率"},{"type":"note","title":"一句话概述","text":"掌握直接列举、列表与树状图三种方法，能完整列出所有等可能结果并计算事件的概率。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"抽签时，先抽还是后抽，中奖机会一样吗？把签的所有可能结果列清楚，答案自然就出来了。概率计算的关键不是猜，而是「不重不漏地列」。","walk":["一步试验用列举法：把所有等可能的结果列出来，数出符合条件的结果数，概率 = 符合条件数 ÷ 总结果数。","两步试验用列表法或树状图：第一步的每种结果下面接第二步的所有结果，保证不重不漏。","判断游戏是否公平，就看双方获胜的概率是否相等。"],"try":"同时掷两枚硬币，用树状图列出所有结果：正正、正反、反正、反反，共 4 种，再算「一正一反」的概率。","use":["两步试验优先画树状图，列出全部结果后再数，别凭感觉写答案。","「至少有一个」常用「1 减去一个都没有的概率」，能省很多列举。"]},{"type":"h","text":"第一次碰上两步：画树状图分层展开"},{"type":"p","text":"一步试验直接数结果就行，两步试验（先做一次、再做一次）就得按步骤一层层展开。画树状图的方法是从「开始」出发，第一步有几种结果就分出几条枝，每条枝下面再按第二步的结果继续分，从根到叶的一条路径就是一次试验的一种结果。抛两枚硬币，每枚都有正、反两种，所以第二步再各分两支，一共 2× 2=4 种结果。"},{"type":"figure","figure":{"id":"fig-sta-gljs-s1","title":"两步试验的树状图","caption":"从开始分出正、反两支，每支再分出正、反，共 4 种等可能结果","view":"square","alt":"树状图：从「开始」分出正、反两条枝，每条枝下再各分出正、反两个结果，共四种等可能结果，其中（正，反）与（反，正）两条路径用高亮标出","prims":[{"t":"dot","x":14,"y":52},{"t":"text","x":14,"y":43,"text":"开始","size":3.2,"anchor":"middle"},{"t":"line","x1":14,"y1":52,"x2":33,"y2":32,"tone":"accent"},{"t":"line","x1":14,"y1":52,"x2":33,"y2":72,"tone":"accent"},{"t":"dot","x":34,"y":32,"tone":"accent"},{"t":"dot","x":34,"y":72,"tone":"accent"},{"t":"text","x":30,"y":33,"text":"正","size":3.2,"anchor":"end","tone":"accent"},{"t":"text","x":30,"y":73,"text":"反","size":3.2,"anchor":"end","tone":"accent"},{"t":"line","x1":35,"y1":32,"x2":61,"y2":20,"tone":"accent"},{"t":"line","x1":35,"y1":32,"x2":61,"y2":44},{"t":"line","x1":35,"y1":72,"x2":61,"y2":60,"tone":"accent"},{"t":"line","x1":35,"y1":72,"x2":61,"y2":84},{"t":"dot","x":62,"y":20,"tone":"accent"},{"t":"dot","x":62,"y":44,"tone":"accent"},{"t":"dot","x":62,"y":60,"tone":"accent"},{"t":"dot","x":62,"y":84},{"t":"text","x":66,"y":21,"text":"（正,正）","size":3,"tone":"accent"},{"t":"text","x":66,"y":45,"text":"（正,反）","size":3,"tone":"accent"},{"t":"text","x":66,"y":61,"text":"（反,正）","size":3,"tone":"accent"},{"t":"text","x":66,"y":85,"text":"（反,反）","size":3},{"t":"text","x":50,"y":95,"text":"4 种等可能结果，一正一反占（正,反）（反,正）2 种","size":3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"画树状图要按固定顺序分层展开，每一步都把该步的所有结果画全，才不会漏枝。"},{"type":"h","text":"换个工具：列表法把交叉结果排成方阵"},{"type":"p","text":"两步试验如果每步的结果不易分支，就把第一步的结果排成横行、第二步的结果排成竖列，交叉位置的格子填上这一步组合出的结果。掷两枚骰子时横行、竖列各有 1 到 6，表格正好填满 6× 6=36 个格子，每个格子就是一种等可能结果。这样一来，凡是满足条件的结果在表里一目了然：点数和为 7 的正好落在一条斜线上，共 6 格。"},{"type":"figure","figure":{"id":"fig-sta-gljs-s2","title":"列表法列出 36 种结果","caption":"两枚骰子排成 6×6 方阵，每格填点数和，和为 7 的 6 格落在一条斜线上","view":"square","alt":"一张 6 行 6 列的方格表，横行是第一枚骰子的点数、竖列是第二枚骰子的点数，每格填两枚骰子的点数和；对角方向上点数和为 7 的六个格子用高亮标出，下方注明共 36 种结果、和为 7 的有 6 种","prims":[{"t":"text","x":48,"y":13,"text":"横行第一枚、竖列第二枚，格内为点数和","size":3,"anchor":"middle"},{"t":"text","x":32,"y":20,"text":"1","size":3,"anchor":"middle"},{"t":"text","x":40,"y":20,"text":"2","size":3,"anchor":"middle"},{"t":"text","x":48,"y":20,"text":"3","size":3,"anchor":"middle"},{"t":"text","x":56,"y":20,"text":"4","size":3,"anchor":"middle"},{"t":"text","x":64,"y":20,"text":"5","size":3,"anchor":"middle"},{"t":"text","x":72,"y":20,"text":"6","size":3,"anchor":"middle"},{"t":"text","x":24,"y":28,"text":"1","size":3,"anchor":"end"},{"t":"text","x":24,"y":36,"text":"2","size":3,"anchor":"end"},{"t":"text","x":24,"y":44,"text":"3","size":3,"anchor":"end"},{"t":"text","x":24,"y":52,"text":"4","size":3,"anchor":"end"},{"t":"text","x":24,"y":60,"text":"5","size":3,"anchor":"end"},{"t":"text","x":24,"y":68,"text":"6","size":3,"anchor":"end"},{"t":"rect","x":28,"y":24,"w":8,"h":8},{"t":"rect","x":36,"y":24,"w":8,"h":8},{"t":"rect","x":44,"y":24,"w":8,"h":8},{"t":"rect","x":52,"y":24,"w":8,"h":8},{"t":"rect","x":60,"y":24,"w":8,"h":8},{"t":"rect","x":68,"y":24,"w":8,"h":8,"tone":"accent","fill":true},{"t":"rect","x":28,"y":32,"w":8,"h":8},{"t":"rect","x":36,"y":32,"w":8,"h":8},{"t":"rect","x":44,"y":32,"w":8,"h":8},{"t":"rect","x":52,"y":32,"w":8,"h":8},{"t":"rect","x":60,"y":32,"w":8,"h":8,"tone":"accent","fill":true},{"t":"rect","x":68,"y":32,"w":8,"h":8},{"t":"rect","x":28,"y":40,"w":8,"h":8},{"t":"rect","x":36,"y":40,"w":8,"h":8},{"t":"rect","x":44,"y":40,"w":8,"h":8},{"t":"rect","x":52,"y":40,"w":8,"h":8,"tone":"accent","fill":true},{"t":"rect","x":60,"y":40,"w":8,"h":8},{"t":"rect","x":68,"y":40,"w":8,"h":8},{"t":"rect","x":28,"y":48,"w":8,"h":8},{"t":"rect","x":36,"y":48,"w":8,"h":8},{"t":"rect","x":44,"y":48,"w":8,"h":8,"tone":"accent","fill":true},{"t":"rect","x":52,"y":48,"w":8,"h":8},{"t":"rect","x":60,"y":48,"w":8,"h":8},{"t":"rect","x":68,"y":48,"w":8,"h":8},{"t":"rect","x":28,"y":56,"w":8,"h":8},{"t":"rect","x":36,"y":56,"w":8,"h":8,"tone":"accent","fill":true},{"t":"rect","x":44,"y":56,"w":8,"h":8},{"t":"rect","x":52,"y":56,"w":8,"h":8},{"t":"rect","x":60,"y":56,"w":8,"h":8},{"t":"rect","x":68,"y":56,"w":8,"h":8},{"t":"rect","x":28,"y":64,"w":8,"h":8,"tone":"accent","fill":true},{"t":"rect","x":36,"y":64,"w":8,"h":8},{"t":"rect","x":44,"y":64,"w":8,"h":8},{"t":"rect","x":52,"y":64,"w":8,"h":8},{"t":"rect","x":60,"y":64,"w":8,"h":8},{"t":"rect","x":68,"y":64,"w":8,"h":8},{"t":"text","x":32,"y":28.9,"text":"2","size":2.4,"anchor":"middle"},{"t":"text","x":40,"y":28.9,"text":"3","size":2.4,"anchor":"middle"},{"t":"text","x":48,"y":28.9,"text":"4","size":2.4,"anchor":"middle"},{"t":"text","x":56,"y":28.9,"text":"5","size":2.4,"anchor":"middle"},{"t":"text","x":64,"y":28.9,"text":"6","size":2.4,"anchor":"middle"},{"t":"text","x":72,"y":28.9,"text":"7","size":2.4,"anchor":"middle","tone":"accent"},{"t":"text","x":32,"y":36.9,"text":"3","size":2.4,"anchor":"middle"},{"t":"text","x":40,"y":36.9,"text":"4","size":2.4,"anchor":"middle"},{"t":"text","x":48,"y":36.9,"text":"5","size":2.4,"anchor":"middle"},{"t":"text","x":56,"y":36.9,"text":"6","size":2.4,"anchor":"middle"},{"t":"text","x":64,"y":36.9,"text":"7","size":2.4,"anchor":"middle","tone":"accent"},{"t":"text","x":72,"y":36.9,"text":"8","size":2.4,"anchor":"middle"},{"t":"text","x":32,"y":44.9,"text":"4","size":2.4,"anchor":"middle"},{"t":"text","x":40,"y":44.9,"text":"5","size":2.4,"anchor":"middle"},{"t":"text","x":48,"y":44.9,"text":"6","size":2.4,"anchor":"middle"},{"t":"text","x":56,"y":44.9,"text":"7","size":2.4,"anchor":"middle","tone":"accent"},{"t":"text","x":64,"y":44.9,"text":"8","size":2.4,"anchor":"middle"},{"t":"text","x":72,"y":44.9,"text":"9","size":2.4,"anchor":"middle"},{"t":"text","x":32,"y":52.9,"text":"5","size":2.4,"anchor":"middle"},{"t":"text","x":40,"y":52.9,"text":"6","size":2.4,"anchor":"middle"},{"t":"text","x":48,"y":52.9,"text":"7","size":2.4,"anchor":"middle","tone":"accent"},{"t":"text","x":56,"y":52.9,"text":"8","size":2.4,"anchor":"middle"},{"t":"text","x":64,"y":52.9,"text":"9","size":2.4,"anchor":"middle"},{"t":"text","x":72,"y":52.9,"text":"10","size":2.4,"anchor":"middle"},{"t":"text","x":32,"y":60.9,"text":"6","size":2.4,"anchor":"middle"},{"t":"text","x":40,"y":60.9,"text":"7","size":2.4,"anchor":"middle","tone":"accent"},{"t":"text","x":48,"y":60.9,"text":"8","size":2.4,"anchor":"middle"},{"t":"text","x":56,"y":60.9,"text":"9","size":2.4,"anchor":"middle"},{"t":"text","x":64,"y":60.9,"text":"10","size":2.4,"anchor":"middle"},{"t":"text","x":72,"y":60.9,"text":"11","size":2.4,"anchor":"middle"},{"t":"text","x":32,"y":68.9,"text":"7","size":2.4,"anchor":"middle","tone":"accent"},{"t":"text","x":40,"y":68.9,"text":"8","size":2.4,"anchor":"middle"},{"t":"text","x":48,"y":68.9,"text":"9","size":2.4,"anchor":"middle"},{"t":"text","x":56,"y":68.9,"text":"10","size":2.4,"anchor":"middle"},{"t":"text","x":64,"y":68.9,"text":"11","size":2.4,"anchor":"middle"},{"t":"text","x":72,"y":68.9,"text":"12","size":2.4,"anchor":"middle"},{"t":"text","x":50,"y":82,"text":"共 36 种等可能结果，点数和为 7 的有 6 种","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":93,"text":"P(点数和为 7) = 6 ÷ 36 = 1/6","size":3.4,"anchor":"middle","tone":"accent"}]}},{"type":"note","title":"","text":"列表时横行、竖列要分别放两步的全部结果，格子数应为两步结果数之积。"},{"type":"h","text":"面积之比也是概率：转盘问题"},{"type":"p","text":"有些试验的结果不是「数出来」的，而是「占多大面积」的。指针在转盘上等可能地停在每一点，落在某块区域的概率就等于这块区域的面积占整个圆面积的比例；把圆按角度分成相等的几份，也就是按份数比概率。转盘被三等分，中奖区域恰好占 120°，是整圈的 (1)/(3)，所以 P(中奖)=(1)/(3)。"},{"type":"figure","figure":{"id":"fig-sta-gljs-s3","title":"转盘的面积比就是概率","caption":"转盘三等分，中奖扇形占圆心角 120°，面积为整体的三分之一","view":"square","alt":"一个被三等分的圆形转盘，三块扇形面积相同，其中一块高亮并标出中奖与三分之一，下方注明中奖区域的面积是整体的三分之一，所以中奖概率为三分之一","prims":[{"t":"sector","cx":50,"cy":50,"r":30,"from":0,"to":120,"tone":"accent","fill":true,"label":"中奖 1/3","labelR":0.68},{"t":"sector","cx":50,"cy":50,"r":30,"from":120,"to":240,"tone":"muted","label":"1/3","labelR":0.68},{"t":"sector","cx":50,"cy":50,"r":30,"from":240,"to":360,"tone":"muted","label":"1/3","labelR":0.68},{"t":"circle","cx":50,"cy":50,"r":30,"tone":"main"},{"t":"dot","x":50,"y":50,"r":1.5},{"t":"text","x":50,"y":12,"text":"转盘三等分，指针落在每份的可能性相同","size":3,"anchor":"middle"},{"t":"text","x":50,"y":92,"text":"中奖区域面积占 1/3，所以 P(中奖) = 1/3","size":3.2,"anchor":"middle","tone":"accent"}]}},{"type":"note","title":"","text":"只有各扇形面积相等时指针落在每份才是等可能的；面积不等就不能用份数比。"},{"type":"h","text":"换个问法：「至少一次」用对立事件算"},{"type":"p","text":"「至少有一个」这类事件往往包含很多种情况，正面数起来容易漏。这时改从反面看：把「至少一枚正面」与「三枚全反」配成一对，二者恰好把所有结果分完、且不会同时发生，这样的两个事件叫对立事件，概率之和为 1。三枚硬币全反只有 1 种结果，概率 (1)/(8)，于是所求概率就是 1-(1)/(8)=(7)/(8)。"},{"type":"figure","figure":{"id":"fig-sta-gljs-s4","title":"用对立事件求「至少一次」的概率","caption":"8 种结果中只有 1 种是三枚全反，其余 7 种都至少有一枚正面","view":"square","alt":"一个长方形表示三枚硬币的 8 种等可能结果，左端一小块高亮标出三枚全反，右端大块标明至少有一枚正面共 7 种；下方写出至少一枚正面的概率等于 1 减去八分之一得八分之七","prims":[{"t":"text","x":50,"y":26,"text":"三枚硬币共 8 种等可能结果","size":3.2,"anchor":"middle"},{"t":"rect","x":16,"y":34,"w":68,"h":32,"tone":"main"},{"t":"rect","x":16,"y":34,"w":8.5,"h":32,"tone":"danger","fill":true},{"t":"text","x":20.25,"y":51.5,"text":"全反","size":2.6,"anchor":"middle","tone":"danger"},{"t":"text","x":56,"y":51.5,"text":"至少有一枚正面（7 种）","size":3.2,"anchor":"middle"},{"t":"text","x":50,"y":78,"text":"P(至少一枚正面) = 1 − P(三枚全反) = 1 − 1/8 = 7/8","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":50,"y":90,"text":"先算对立事件的概率，再用 1 减去它","size":3,"anchor":"middle","tone":"muted"}]}},{"type":"note","title":"","text":"只有两个事件互相对立（必有一个发生、且不同时发生）时，才能用 1 减去其中一个的概率。"},{"type":"h","text":"核心概念"},{"type":"p","text":"直接列举法：当试验的结果较少时，把所有等可能结果按固定顺序一一列出，再数出所求事件包含的结果数，用结果数之比求概率。"},{"type":"p","text":"列表法：适用于两步试验。把第一步的所有结果排在横行，第二步的所有结果排在竖列，交叉位置填出对应的结果，表格中结果的总数就是所有等可能结果的总数。"},{"type":"p","text":"树状图法：用树状图按步骤逐层画出所有结果：第一层画出第一步的所有结果，第二层在每个结果下面画出第二步的所有结果，从根到叶的一条路径就是一种结果。"},{"type":"p","text":"两步试验的结果总数：若第一步有 n₁ 种等可能结果，第二步有 n₂ 种等可能结果，则共有 n₁× n₂ 种等可能结果。例如同时掷两枚骰子共有 6× 6=36 种结果。"},{"type":"p","text":"放回与不放回：摸球、抽卡片等问题中，若摸出后放回，各步的结果数不变；若不放回（或一次取出两个），后一步的结果数比前一步少 1，结果总数与所求概率都会不同。"},{"type":"p","text":"可区分原则：掷两枚骰子、摸两个球时，要把两枚骰子（两个球）看作可区分的并加以编号，否则会把（1，2）与（2，1）误并成一种结果，导致结果个数错误、各结果不再等可能。"},{"type":"p","text":"等可能的前提：列举出的所有结果必须是等可能的，才可以用 P(A)=(m)/(n)。若各部分面积不等的转盘、有轻重的球，各结果并不等可能，不能直接套用公式。"},{"type":"note","title":"中考考法","text":"两步试验的列表法与树状图\n中考解答题高频题位，摸球、抽卡、转盘情境下列表或画树状图，写出结果总数 n 与符合结果数 m 后求概率。"},{"type":"note","title":"中考考法","text":"放回与不放回辨析\n题目通过「放回」「不放回」「一次摸两个」改变结果总数，不放回时后一步少一种，判断错则 n、m 全错。"},{"type":"note","title":"中考考法","text":"「至少」类事件与三步试验\n三步试验直接画树状图；「至少有一个」的事件可用 1 减去对立事件的概率，列举时对事物编号，做到不重不漏。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["事件概率公式","n 是所有等可能结果的总数，m 是事件 A 包含的结果数。","列举时要做到不重不漏，m 一定不大于 n。"],["两步试验的结果总数","两步试验中，若第一步有 n₁ 种等可能结果，第二步有 n₂ 种等可能结果，则所有等可能结果共有 n₁× n₂ 种。","放回时 n₂=n₁，不放回时 n₂=n₁-1。"],["不放回抽取的结果总数","在不放回地依次抽取两次的试验中，若第一次有 n₁ 种等可能结果，第二次只有 n₁-1 种，故共有 n₁(n₁-1) 种结果。","例如袋中有 3 个球，不放回地依次摸两次，共有 3× 2=6 种结果。"],["所有可能结果的概率之和","在一次试验中，所有等可能结果的概率之和等于 1。因此可以先求出「反面情况」的概率，再用 1 减去它得到所求事件的概率。","常用于「至少有一个」这类事件的间接计算。"]]},{"type":"note","title":"例题","text":"同时抛掷两枚质地均匀的硬币，求下列事件的概率：（1）两枚都正面朝上；（2）一枚正面朝上、一枚反面朝上。"},{"type":"figure","figure":{"id":"fig-sta-gljs-e1","title":"抛两枚硬币的 4 种结果","caption":"把两枚硬币看作可区分，四种结果各占 1/4","view":"square","alt":"四个方框排成两行两列，分别写着（正，正）（反，正）（正，反）（反，反），表示抛两枚硬币的全部四种等可能结果；两枚都正面朝上的方框和两个一正一反的方框分别高亮，下方注明两枚都正面有一种、一正一反有两种及其概率","prims":[{"t":"text","x":50,"y":14,"text":"两枚硬币看作可区分，共 4 种等可能结果","size":3.2},{"t":"rect","x":14,"y":26,"w":32,"h":20,"tone":"ok","fill":true,"label":"（正，正）"},{"t":"rect","x":54,"y":26,"w":32,"h":20,"tone":"accent","fill":true,"label":"（反，正）"},{"t":"rect","x":14,"y":52,"w":32,"h":20,"tone":"accent","fill":true,"label":"（正，反）"},{"t":"rect","x":54,"y":52,"w":32,"h":20,"label":"（反，反）"},{"t":"text","x":50,"y":83,"text":"（1）两枚都正面：1 种，P = 1/4","size":3},{"t":"text","x":50,"y":94,"text":"（2）一正一反：2 种，P = 2/4 = 1/2","size":3.2,"tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["把两枚硬币看作可区分的，分别记为第一枚、第二枚，按固定顺序列出所有等可能结果：（正，正）（正，反）（反，正）（反，反），共 n=4 种。","（1）两枚都正面朝上的结果只有（正，正）1 种，m=1，P=(1)/(4)。","（2）一枚正面朝上、一枚反面朝上的结果有（正，反）（反，正）2 种，m=2，P=(2)/(4)=(1)/(2)。"]},{"type":"p","text":"答案：（1）(1)/(4)；（2）(1)/(2)。"},{"type":"note","title":"方法小结","text":"一定要把两枚硬币看作可区分的，否则会把（正，反）与（反，正）合并成一种，四结果变成三种，各结果就不再等可能了。"},{"type":"note","title":"例题","text":"同时掷两枚质地均匀的骰子，求两枚骰子点数之和为 5 的概率。"},{"type":"figure","figure":{"id":"fig-sta-gljs-e2","title":"两枚骰子点数和为 5 的 4 种结果","caption":"和为 5 的结果有 4 种，占 36 种等可能结果的 1/9","view":"square","alt":"一排四个方框，分别写着（1，4）（2，3）（3，2）（4，1），表示两枚骰子点数和为 5 的全部四种结果，即第一枚从 1 到 4、第二枚对应从 4 到 1，下方注明这四种都满足点数和为 5，概率是四除以三十六等于九分之一","prims":[{"t":"text","x":50,"y":20,"text":"和为 5：第一枚 1→4，第二枚 4→1","size":2.9},{"t":"rect","x":6,"y":36,"w":21,"h":22,"tone":"accent","fill":true,"label":"（1，4）"},{"t":"rect","x":29,"y":36,"w":21,"h":22,"tone":"accent","fill":true,"label":"（2，3）"},{"t":"rect","x":52,"y":36,"w":21,"h":22,"tone":"accent","fill":true,"label":"（3，2）"},{"t":"rect","x":75,"y":36,"w":21,"h":22,"tone":"accent","fill":true,"label":"（4，1）"},{"t":"text","x":50,"y":76,"text":"这 4 种结果都满足点数和为 5","size":3},{"t":"text","x":50,"y":90,"text":"P = 4 ÷ 36 = 1/9","size":3.4,"tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["把两枚骰子分别记为第一枚、第二枚，用列表法列出所有等可能结果，共有 6× 6=36 种。","按第一枚的点数从小到大，依次找出点数之和为 5 的结果：（1，4）（2，3）（3，2）（4，1），共 4 种，即 m=4。","代入公式：P=(4)/(36)=(1)/(9)。"]},{"type":"p","text":"答案：两枚骰子点数之和为 5 的概率是 (1)/(9)。"},{"type":"note","title":"方法小结","text":"两枚骰子要编号，（1，4）与（4，1）是两种不同的结果，不能合并；点数之和为 7 的结果有 6 种，对比可以检验列举是否完整。"},{"type":"note","title":"例题","text":"一个不透明的袋中装有 2 个红球（记为红 1、红 2）和 1 个白球，除颜色外都相同。第一次任意摸出一个球后不放回，第二次再摸出一个球，求两次都摸到红球的概率。"},{"type":"figure","figure":{"id":"fig-m-sta-jisuan-1","title":"不放回摸球树状图","caption":"两次都摸到红球的结果有 2 种，占 6 种等可能结果的 1/3","view":"wide","alt":"树状图：第一次摸出红 1、红 2、白三种，第二次各剩两种球，共六种结果，其中红 1 到红 2、红 2 到红 1 两条路径两次都摸到红球，用高亮标出","prims":[{"t":"dot","x":10,"y":44},{"t":"text","x":10,"y":37,"text":"开始","size":3.2,"anchor":"middle"},{"t":"line","x1":12,"y1":44,"x2":32,"y2":18,"tone":"accent"},{"t":"line","x1":12,"y1":44,"x2":32,"y2":44,"tone":"accent"},{"t":"line","x1":12,"y1":44,"x2":32,"y2":70},{"t":"dot","x":34,"y":18,"tone":"accent"},{"t":"dot","x":34,"y":44,"tone":"accent"},{"t":"dot","x":34,"y":70},{"t":"text","x":30,"y":19,"text":"红 1","size":3.2,"anchor":"end","tone":"accent"},{"t":"text","x":30,"y":45,"text":"红 2","size":3.2,"anchor":"end","tone":"accent"},{"t":"text","x":30,"y":71,"text":"白","size":3.2,"anchor":"end"},{"t":"line","x1":36,"y1":18,"x2":64,"y2":10,"tone":"accent"},{"t":"line","x1":36,"y1":18,"x2":64,"y2":26},{"t":"line","x1":36,"y1":44,"x2":64,"y2":36,"tone":"accent"},{"t":"line","x1":36,"y1":44,"x2":64,"y2":52},{"t":"line","x1":36,"y1":70,"x2":64,"y2":62},{"t":"line","x1":36,"y1":70,"x2":64,"y2":78},{"t":"dot","x":66,"y":10,"tone":"accent"},{"t":"dot","x":66,"y":26},{"t":"dot","x":66,"y":36,"tone":"accent"},{"t":"dot","x":66,"y":52},{"t":"dot","x":66,"y":62},{"t":"dot","x":66,"y":78},{"t":"text","x":69,"y":11,"text":"红 2","size":3,"tone":"accent"},{"t":"text","x":69,"y":27,"text":"白","size":3},{"t":"text","x":69,"y":37,"text":"红 1","size":3,"tone":"accent"},{"t":"text","x":69,"y":53,"text":"白","size":3},{"t":"text","x":69,"y":63,"text":"红 1","size":3},{"t":"text","x":69,"y":79,"text":"红 2","size":3},{"t":"text","x":78,"y":11,"text":"（红 1,红 2）两红","size":3,"tone":"accent"},{"t":"text","x":78,"y":27,"text":"（红 1,白）","size":3},{"t":"text","x":78,"y":37,"text":"（红 2,红 1）两红","size":3,"tone":"accent"},{"t":"text","x":78,"y":53,"text":"（红 2,白）","size":3},{"t":"text","x":78,"y":63,"text":"（白,红 1）","size":3},{"t":"text","x":78,"y":79,"text":"（白,红 2）","size":3},{"t":"text","x":50,"y":93,"text":"6 种等可能结果中两红占 2 种，P(两红) = 2/6 = 1/3","size":3.2,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["画树状图：第一次有 3 种等可能结果（红 1、红 2、白）；由于不放回，第二次剩下 2 个球，各有 2 种结果，所以共有 3× 2=6 种等可能结果。","把所有结果按顺序写出：（红 1，红 2）（红 1，白）（红 2，红 1）（红 2，白）（白，红 1）（白，红 2）。","两次都摸到红球的结果有（红 1，红 2）（红 2，红 1），共 2 种，即 m=2。","代入公式：P=(2)/(6)=(1)/(3)。"]},{"type":"p","text":"答案：两次都摸到红球的概率是 (1)/(3)。"},{"type":"note","title":"方法小结","text":"不放回时第二次的结果数比第一次少 1，结果总数是 6 而不是 9；若误按放回处理，概率会算成 (4)/(9)。"},{"type":"note","title":"例题","text":"一个不透明的袋中装有 2 个红球和 1 个白球，它们除颜色外都相同，分别记为红 1、红 2、白。从中任意摸出一个球，记下颜色后放回并搅匀，再摸出一个球。求两次摸出的球颜色相同的概率。"},{"type":"figure","figure":{"id":"fig-sta-gljs-e4","title":"有放回摸球 9 种结果的方格表","caption":"有放回时每步都有 3 种结果，共 9 种；颜色相同的有 5 种","view":"square","alt":"一张三行三列的方格表，横行是第一次摸出的红 1、红 2、白，竖列是第二次摸出的红 1、红 2、白，九个格子分别标出两次的结果；两次同色的五个格子高亮，即同为红的四格加上同为白的一格，下方注明颜色相同共五种、概率是五除以九","prims":[{"t":"text","x":50,"y":12,"text":"有放回摸两次，共 3 × 3 = 9 种结果","size":2.9},{"t":"text","x":42,"y":22,"text":"红 1","size":2.8},{"t":"text","x":58,"y":22,"text":"红 2","size":2.8},{"t":"text","x":74,"y":22,"text":"白","size":2.8},{"t":"text","x":30,"y":33.5,"text":"红 1","size":2.8,"anchor":"end"},{"t":"text","x":30,"y":48.5,"text":"红 2","size":2.8,"anchor":"end"},{"t":"text","x":30,"y":63.5,"text":"白","size":2.8,"anchor":"end"},{"t":"rect","x":34,"y":26,"w":16,"h":15,"tone":"accent","fill":true},{"t":"rect","x":50,"y":26,"w":16,"h":15,"tone":"accent","fill":true},{"t":"rect","x":66,"y":26,"w":16,"h":15},{"t":"rect","x":34,"y":41,"w":16,"h":15,"tone":"accent","fill":true},{"t":"rect","x":50,"y":41,"w":16,"h":15,"tone":"accent","fill":true},{"t":"rect","x":66,"y":41,"w":16,"h":15},{"t":"rect","x":34,"y":56,"w":16,"h":15},{"t":"rect","x":50,"y":56,"w":16,"h":15},{"t":"rect","x":66,"y":56,"w":16,"h":15,"tone":"accent","fill":true},{"t":"text","x":42,"y":33.5,"text":"红1红1","size":2.2,"tone":"accent"},{"t":"text","x":58,"y":33.5,"text":"红2红1","size":2.2,"tone":"accent"},{"t":"text","x":74,"y":33.5,"text":"白红1","size":2.2},{"t":"text","x":42,"y":48.5,"text":"红1红2","size":2.2,"tone":"accent"},{"t":"text","x":58,"y":48.5,"text":"红2红2","size":2.2,"tone":"accent"},{"t":"text","x":74,"y":48.5,"text":"白红2","size":2.2},{"t":"text","x":42,"y":63.5,"text":"红1白","size":2.2},{"t":"text","x":58,"y":63.5,"text":"红2白","size":2.2},{"t":"text","x":74,"y":63.5,"text":"白白","size":2.2,"tone":"accent"},{"t":"text","x":50,"y":82,"text":"颜色相同：同为红 4 种 + 同为白 1 种 = 5 种","size":2.9},{"t":"text","x":50,"y":93,"text":"P(颜色相同) = 5 ÷ 9 = 5/9","size":3.3,"tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["因为是有放回地摸两次，每一步都有 3 种等可能结果，用树状图或列表可得共有 3× 3=9 种等可能结果。","两次都是红球的结果有（红 1，红 1）（红 1，红 2）（红 2，红 1）（红 2，红 2），共 4 种。","两次都是白球的结果只有（白，白）1 种。","颜色相同的结果共有 4+1=5 种，所以 P=(5)/(9)。"]},{"type":"p","text":"答案：两次摸出的球颜色相同的概率是 (5)/(9)。"},{"type":"note","title":"方法小结","text":"有放回时两步的结果数相同，结果总数是 3× 3=9；「颜色相同」要把「同为红」和「同为白」两类结果都数上后相加。"},{"type":"note","title":"例题","text":"同时抛掷三枚质地均匀的硬币，求至少有一枚硬币正面朝上的概率。"},{"type":"figure","figure":{"id":"fig-sta-gljs-e5","title":"三枚硬币的 8 种结果","caption":"8 种结果里只有「反反反」不满足条件，其余 7 种都至少有一枚正面","view":"square","alt":"八个方框排成四列两行，依次写着正正正、正正反、正反正、正反反、反正正、反正反、反反正、反反反，表示抛三枚硬币的全部八种等可能结果；只有最后的反反反用醒目颜色标出，其余七种都至少有一枚正面，下方注明概率等于一减去八分之一得八分之七","prims":[{"t":"text","x":50,"y":12,"text":"三枚硬币共 8 种等可能结果","size":3},{"t":"rect","x":5,"y":24,"w":21,"h":18,"label":"正正正"},{"t":"rect","x":28,"y":24,"w":21,"h":18,"label":"正正反"},{"t":"rect","x":51,"y":24,"w":21,"h":18,"label":"正反正"},{"t":"rect","x":74,"y":24,"w":21,"h":18,"label":"正反反"},{"t":"rect","x":5,"y":48,"w":21,"h":18,"label":"反正正"},{"t":"rect","x":28,"y":48,"w":21,"h":18,"label":"反正反"},{"t":"rect","x":51,"y":48,"w":21,"h":18,"label":"反反正"},{"t":"rect","x":74,"y":48,"w":21,"h":18,"tone":"danger","fill":true,"label":"反反反"},{"t":"text","x":50,"y":78,"text":"「至少一枚正面」含除「反反反」外的 7 种","size":2.9},{"t":"text","x":50,"y":91,"text":"P = 1 − 1/8 = 7/8","size":3.4,"tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["画树状图列举所有结果：第一枚有正、反 2 种，第二枚、第三枚各有 2 种，共有 2× 2× 2=8 种等可能结果。","直接列举时「至少有一枚正面朝上」包含一枚、两枚、三枚正面朝上，情况较多；改为考虑它的对立事件「三枚全部反面朝上」。","三枚全部反面朝上的结果只有（反，反，反）1 种，其概率为 (1)/(8)。","所以至少有一枚正面朝上的概率为 1-(1)/(8)=(7)/(8)。"]},{"type":"p","text":"答案：至少有一枚硬币正面朝上的概率是 (7)/(8)。"},{"type":"note","title":"方法小结","text":"遇到「至少有一个」的事件，先算它的对立事件（一个都没有）的概率，再用 1 去减，比逐类列举更快、更不容易漏。"},{"type":"list","title":"易错点","items":["列举时既不能遗漏也不能重复，最好按固定顺序列举（先固定第一个数，再依次变化第二个数），列完后检查结果总数是否符合 n₁× n₂。","计算两枚骰子、两枚硬币、两个球的试验时，必须把它们看作可区分的，否则结果个数错误、各结果也不再等可能。","注意「放回」与「不放回」的区别：放回时各步结果数相同，不放回时后一步少 1 种，结果总数和所求概率都不同。","只有各个结果等可能时才能用 P(A)=(m)/(n)；把「和为 5」这样的结果按种类想当然地估计概率是错的。","结果数要数清：两枚骰子点数之和为 7 的结果有 6 种而不是 3 种，数错就会算出错误的概率。","转盘问题要先看各扇形面积是否相等，面积不相等时指针落在各部分不是等可能的；分步试验要看各步是否相互影响。"]},{"type":"list","title":"解题方法","items":["一步试验：用直接列举法列出所有等可能结果，数出 n 与 m 后代入公式。","两步试验：结果较少时用列表法，需要显示先后顺序或步骤较多时用树状图法。","列举技巧：给可区分的事物编号（红 1、红 2，第一枚、第二枚），按固定顺序写出所有结果，避免遗漏和重复。","判断是否放回：看题目中是否有「不放回」「同时取出」等字样，据此确定各步的结果数。","检验答案：所有等可能结果的概率之和应为 1，所求概率应在 0 与 1 之间，且分母应与结果总数相符。"]}],"questions":[{"id":"q-sta-jisuan-1","type":"choice","stem":"同时抛掷两枚质地均匀的硬币，出现一枚正面朝上、一枚反面朝上的概率是（ ）","answer":"C","explain":"把两枚硬币看作可区分，所有等可能结果为（正，正）（正，反）（反，正）（反，反），共 4 种；其中一正一反的有（正，反）（反，正）2 种，所以概率 =(2)/(4)=(1)/(2)。选 (1)/(3) 是没有把两枚硬币区分开、把结果当成 3 种造成的错误。","options":["(1)/(4)","(1)/(3)","(1)/(2)","(3)/(4)"],"difficulty":2,"tags":["列举法","两步试验"]},{"id":"q-sta-jisuan-2","type":"fill","stem":"同时掷两枚质地均匀的骰子，两枚骰子点数之和为 7 的概率是＿＿。","answer":"1/6","explain":"两枚骰子共有 6× 6=36 种等可能结果。点数之和为 7 的结果有（1，6）（2，5）（3，4）（4，3）（5，2）（6，1），共 6 种，所以概率 =(6)/(36)=(1)/(6)。","difficulty":2,"tags":["列表法","两步试验"]},{"id":"q-sta-jisuan-3","type":"choice","stem":"一个不透明的袋中装有 1 个红球和 2 个白球，除颜色外都相同。从中任意摸出一个球后不放回，再摸出一个球，则两次都摸到白球的概率是（ ）","answer":"A","explain":"把三个球记为红、白 1、白 2，不放回地依次摸两次，共有 3× 2=6 种等可能结果：（红，白 1）（红，白 2）（白 1，红）（白 1，白 2）（白 2，红）（白 2，白 1）。两次都摸到白球的有（白 1，白 2）（白 2，白 1）2 种，所以概率 =(2)/(6)=(1)/(3)。选 (2)/(9) 是把不放回误当成放回并与顺序混淆的错误结果。","options":["(1)/(3)","(1)/(2)","(2)/(9)","(1)/(6)"],"difficulty":2,"tags":["不放回","树状图"]},{"id":"q-sta-jisuan-4","type":"choice","stem":"从分别标有数字 1、2、3 的三张卡片中任意抽取两张（不放回），两张卡片上数字之和为偶数的概率是（ ）","answer":"A","explain":"不放回地抽取两张，若按顺序列举，共有 3× 2=6 种等可能结果，其中数字之和为偶数的有（1，3）（3，1）2 种，概率 =(2)/(6)=(1)/(3)。若不考虑顺序，三组卡片之和分别为 3、4、5，和为偶数的只有 1 组，同样得到 (1)/(3)。","options":["(1)/(3)","(1)/(2)","(2)/(3)","(1)/(6)"],"difficulty":3,"tags":["不放回","列举法"]},{"id":"q-sta-jisuan-5","type":"short","stem":"三张完全相同的卡片上分别写有数字 1、2、3，背面朝上放在桌面上。小明先抽出一张，记下数字后放回并洗匀，再抽出一张，求两次抽到的数字之和为 3 的概率。","answer":"因为有放回，第一次有 3 种等可能结果，第二次仍有 3 种，共有 3× 3=9 种等可能结果：（1，1）（1，2）（1，3）（2，1）（2，2）（2，3）（3，1）（3，2）（3，3）。其中数字之和为 3 的结果有（1，2）和（2，1），共 2 种。所以两次抽到的数字之和为 3 的概率是 (2)/(9)。","explain":"有放回时每步都有 3 种结果，结果总数为 9。列举时必须把两次抽取看作有先后顺序，（1，2）与（2，1）是两种不同的结果，遗漏其一就会算成 (1)/(9)。","difficulty":2,"tags":["有放回","列表法","实际情境"],"rubric":["说明有放回，每步都有 3 种结果","用列表或树状图列出全部 9 种等可能结果","指出数字之和为 3 的结果是（1，2）和（2，1）共 2 种","得出概率为 (2)/(9)"]},{"id":"q-sta-jisuan-z1","type":"choice","stem":"从分别写有数字 1, 2, 3, 4 的四张卡片中任意抽取一张，记下数字后放回洗匀，再抽取一张。两次抽得的数字之积为偶数的概率是（ ）","answer":"D","explain":"有放回地抽取两次，共有 4× 4=16 种等可能结果。只有两个数都是奇数时积才是奇数，两次都抽到 1 或 3 的结果有（1，1）（1，3）（3，1）（3，3）共 4 种，故积为奇数的概率为 (4)/(16)=(1)/(4)，积为偶数的概率为 1-(1)/(4)=(3)/(4)。","options":["(1)/(2)","(2)/(3)","(1)/(4)","(3)/(4)"],"difficulty":3,"tags":["有放回","列举法"]},{"id":"q-sta-jisuan-z2","type":"fill","stem":"一个不透明的袋中装有 3 个红球和 2 个白球，它们除颜色外都相同。从中依次不放回地摸出两个球，则摸出的两个球颜色不同的概率是＿＿。","answer":"3/5","explain":"不放回地依次摸两次，共有 5× 4=20 种等可能结果。两球颜色不同包括「先红后白」3× 2=6 种和「先白后红」2× 3=6 种，共 12 种，所以概率为 (12)/(20)=(3)/(5)。","difficulty":3,"tags":["不放回","树状图"]}]},{"id":"m-sta-tongji-tu","title":"统计图表的选择与误读","subtitle":"人教版初中 · 统计图","grade":"all","tags":["统计与概率","统计图"],"blocks":[{"type":"note","title":"教材章节","text":"人教版初中 · 统计图"},{"type":"note","title":"一句话概述","text":"会按分析目的选择条形图、折线图、扇形图与频数分布直方图，识别常见的统计图误读。"},{"type":"teach","title":"零基础也能看懂：这一节到底在说什么","hook":"新闻里一张「销量暴涨」的折线图，纵轴却从 990 开始，看起来涨得吓人，实际只涨了 1%。统计图会说谎，读图的人要学会看穿它。","walk":["条形图适合比较数量多少，折线图适合看变化趋势，扇形图适合看各部分占总体的百分比，直方图适合看数据分布。","常见误读：纵轴不从 0 开始、扇形图基数不同还硬比、把百分比当绝对数量、样本没有代表性。","读图先看三件事：标题、单位、总量。再看图例和刻度，最后才看结论。"],"try":"找一张新闻里的统计图，检查它的纵轴从哪里开始、总量是多少，看看标题结论有没有夸大。","use":["选择统计图先问「我想让人看到什么」：比较多少用条形，看趋势用折线，看占比用扇形。","评价统计图先看「数据来源、样本、刻度」，再谈结论是否可靠。"]},{"type":"h","text":"比多少：条形的高度就是数量"},{"type":"p","text":"要比较几个类别数量的多少，就把类别排在横轴上、把数量画成条形的高度，条形之间留出间隔，谁高谁低一眼可见。读图时要先看纵轴：纵轴必须从 0 开始，否则条形高度之比不再等于数量之比，差距会被夸大。"},{"type":"figure","figure":{"id":"fig-sta-tjt-s1","title":"条形统计图：比较各类别的数量","caption":"条形越高数量越多，条形之间留有间隔","view":"square","alt":"一个条形统计图，横轴是篮球、足球、乒乓球、其他四个类别，纵轴是从 0 到 20 的人数；四根条形高度分别是 20、10、16、4，条形之间留有空隙，最高的篮球条形用醒目颜色标出","prims":[{"t":"axis","x":14,"y":80,"w":76,"h":58,"xLabel":"项目","yLabel":"人数","origin":true,"xTicks":[{"at":0.13,"label":"篮球"},{"at":0.38,"label":"足球"},{"at":0.63,"label":"乒乓球"},{"at":0.88,"label":"其他"}],"yTicks":[{"at":0,"label":"0"},{"at":0.5,"label":"10"},{"at":1,"label":"20"}]},{"t":"rect","x":18.5,"y":22,"w":10,"h":58,"fill":true},{"t":"rect","x":37.5,"y":51,"w":10,"h":29},{"t":"rect","x":56.5,"y":33.6,"w":10,"h":46.4},{"t":"rect","x":75.5,"y":68.4,"w":10,"h":11.6},{"t":"text","x":23.5,"y":19.5,"text":"20","size":3},{"t":"text","x":42.5,"y":48.5,"text":"10","size":3},{"t":"text","x":61.5,"y":31.1,"text":"16","size":3},{"t":"text","x":80.5,"y":65.9,"text":"4","size":3}]}},{"type":"note","title":"","text":"条形之间留间隔，表示这些类别彼此独立、没有先后连续关系。"},{"type":"h","text":"看趋势：折线连出变化走向"},{"type":"p","text":"要反映数量随时间（或顺序）变化的趋势，就把各个数据点按先后顺序依次连成折线。折线整体向上说明在增长、向下说明在减少，线段的陡缓反映变化的快慢。看折线图同样要先看纵轴刻度，刻度不同会让同样的变化显得陡缓不同。"},{"type":"figure","figure":{"id":"fig-sta-tjt-s2","title":"折线统计图：反映变化趋势","caption":"按顺序把各点连成折线，整体呈上升趋势","view":"square","alt":"一个折线统计图，横轴是五次记录、纵轴是从 0 到 100 的成绩；五个数据点对应的数值依次是 40、55、50、70、85，用折线依次连接，折线整体呈上升趋势，每个数据点都用圆点标出","prims":[{"t":"text","x":50,"y":12,"text":"各点按顺序连线，看升降趋势","size":3.2},{"t":"axis","x":14,"y":80,"w":76,"h":58,"xLabel":"次序","yLabel":"成绩","origin":true,"xTicks":[{"at":0.1,"label":"一"},{"at":0.3,"label":"二"},{"at":0.5,"label":"三"},{"at":0.7,"label":"四"},{"at":0.9,"label":"五"}],"yTicks":[{"at":0,"label":"0"},{"at":0.5,"label":"50"},{"at":1,"label":"100"}]},{"t":"curve","points":[[21.6,56.8],[36.8,48.1],[52,51],[67.2,39.4],[82.4,30.7]],"tone":"accent"},{"t":"dot","x":21.6,"y":56.8,"tone":"accent"},{"t":"dot","x":36.8,"y":48.1,"tone":"accent"},{"t":"dot","x":52,"y":51,"tone":"accent"},{"t":"dot","x":67.2,"y":39.4,"tone":"accent"},{"t":"dot","x":82.4,"y":30.7,"tone":"accent"}]}},{"type":"note","title":"","text":"折线的陡缓受纵轴刻度影响，比较变化快慢时要先确认刻度是否一致。"},{"type":"h","text":"看占比：扇形面积就是百分比"},{"type":"p","text":"要反映各部分占整体的比例，就把圆分成若干扇形，每块的圆心角与该部分所占百分比成正比，全部圆心角之和是 360°、百分比之和是 100%。扇形只表示比例，不表示具体数量；想知道各部分实际有多少，还必须知道总数。"},{"type":"figure","figure":{"id":"fig-sta-tjt-s3","title":"扇形统计图：表示各部分占总体比例","caption":"每块扇形的大小对应它所占的百分比","view":"square","alt":"一个圆形被分成四块扇形，依次标着步行 30%、骑车 20%、乘车 40%、其他 10%，四块所占的圆心角分别是 108 度、72 度、144 度、36 度，下方注明各部分百分比之和为 100%、圆心角之和为 360 度","prims":[{"t":"text","x":50,"y":12,"text":"扇形大小表示各部分占整体的百分比","size":3},{"t":"sector","cx":50,"cy":46,"r":28,"from":0,"to":108,"tone":"accent","fill":true,"label":"30%"},{"t":"sector","cx":50,"cy":46,"r":28,"from":108,"to":180,"tone":"muted","label":"20%"},{"t":"sector","cx":50,"cy":46,"r":28,"from":180,"to":324,"tone":"muted","label":"40%"},{"t":"sector","cx":50,"cy":46,"r":28,"from":324,"to":360,"tone":"muted","label":"10%"},{"t":"circle","cx":50,"cy":46,"r":28,"tone":"main"},{"t":"dot","x":50,"y":46,"r":1.4},{"t":"text","x":50,"y":88,"text":"百分比之和 100%，圆心角之和 360°","size":3,"tone":"muted"}]}},{"type":"note","title":"","text":"扇形统计图不给具体数量；「总人数 × 百分比」才能算出某部分有多少人。"},{"type":"h","text":"看分布：直方图数出落在哪一组"},{"type":"p","text":"连续数据要先分组统计，把每一组的数据个数画成等宽、紧密相连的矩形，就得到频数分布直方图。矩形越高说明落在这一组的数据越多，各矩形之间没有空隙，这是它与条形统计图最明显的区别；各组频数相加就是数据总数。"},{"type":"figure","figure":{"id":"fig-sta-tjt-s4","title":"频数分布直方图：看连续数据的分布","caption":"各组矩形等宽且相连，矩形越高该组频数越大","view":"square","alt":"一个频数分布直方图，横轴是 50 到 100 的五组测试成绩区间，纵轴是从 0 到 15 的频数；五组频数依次是 5、10、15、8、2，矩形等宽且紧密相连没有空隙，其中频数最高的第三组用醒目颜色标出","prims":[{"t":"text","x":50,"y":12,"text":"等宽、紧密相连，矩形越高该组频数越大","size":2.9},{"t":"axis","x":18,"y":80,"w":70,"h":52,"xLabel":"成绩","yLabel":"频数","origin":true,"xTicks":[{"at":0,"label":"50"},{"at":0.2,"label":"60"},{"at":0.4,"label":"70"},{"at":0.6,"label":"80"},{"at":0.8,"label":"90"},{"at":1,"label":"100"}],"yTicks":[{"at":0,"label":"0"},{"at":0.33,"label":"5"},{"at":0.67,"label":"10"},{"at":1,"label":"15"}]},{"t":"rect","x":18,"y":62.7,"w":14,"h":17.3},{"t":"rect","x":32,"y":45.3,"w":14,"h":34.7},{"t":"rect","x":46,"y":28,"w":14,"h":52,"tone":"accent","fill":true},{"t":"rect","x":60,"y":52.3,"w":14,"h":27.7},{"t":"rect","x":74,"y":73.1,"w":14,"h":6.9},{"t":"text","x":25,"y":60.2,"text":"5","size":3},{"t":"text","x":39,"y":42.8,"text":"10","size":3},{"t":"text","x":53,"y":25.5,"text":"15","size":3,"tone":"accent"},{"t":"text","x":67,"y":49.8,"text":"8","size":3},{"t":"text","x":81,"y":70.6,"text":"2","size":3}]}},{"type":"note","title":"","text":"频数分布直方图各矩形等宽且相连，只适用于连续数据分组，不能画成有间隔的条形。"},{"type":"h","text":"核心概念"},{"type":"p","text":"条形统计图：用条形的高度（长度）表示各个类别的频数，条形之间有间隔，便于比较各类别数量的多少。"},{"type":"p","text":"折线统计图：用折线把各个数据点依次连接起来，便于反映数据随时间（或顺序）变化的趋势，如近几年人口数量的变化。"},{"type":"p","text":"扇形统计图：用扇形的大小表示各部分占总体的百分比，各部分扇形圆心角的度数之和为 360°，便于看出部分与总体的比例关系。"},{"type":"p","text":"频数分布直方图：把连续数据分成若干组后，用等宽的矩形表示各组的频数，矩形越高表示该组的频数越大；各矩形之间紧密相连、没有空隙，数据总数等于各组频数之和。"},{"type":"p","text":"条形统计图与直方图的区别：条形统计图表示各自独立的类别，条形之间有间隔；频数分布直方图表示连续数据分组后的频数，矩形之间没有间隔，且各组组距相等。"},{"type":"p","text":"统计图的选择：比较各类别数量的大小用条形统计图；看数据的变化趋势用折线统计图；看各部分占总体的比例用扇形统计图；看连续数据的分布情况用频数分布直方图。"},{"type":"p","text":"常见的统计图误读：纵轴不从 0 开始会夸大差异；用面积或立体效果画图也会造成视觉上的夸大；扇形统计图各部分百分比之和必须为 100%；用样本推断总体时要注意样本是否随机、容量是否足够。"},{"type":"p","text":"从统计图求具体数量：扇形统计图只给出百分比，必须知道总体数量才能求出具体数量，即「该部分的数量 = 总数 × 该部分所占百分比」。"},{"type":"note","title":"中考考法","text":"按分析目的选择统计图\n选择题考四种图的用途：比数量多少用条形图、看变化趋势用折线图、看部分占总体比例用扇形图、看连续数据分布用直方图。"},{"type":"note","title":"中考考法","text":"条形图与扇形图的补全计算\n解答题常给两幅不完整统计图，由部分数量与其百分比先求总数，再补全其余各组的数量和百分比，各组百分比之和应为 100%。"},{"type":"note","title":"中考考法","text":"统计图的规范绘制与误读识别\n考纵轴是否从 0 开始、直方图与条形图的区别、扇形图能否直接读数量，要求指出问题并改正，常以简答形式出现。"},{"type":"table","title":"公式与定理","head":["公式/定理","表述","注意"],"rows":[["百分比公式","某一部分所占的百分比等于该部分的频数除以数据总数再乘 100%。","各部分百分比之和必须为 100%。"],["扇形圆心角公式","扇形统计图中每部分所对圆心角的度数，等于 360° 乘该部分所占的百分比。","各部分圆心角之和必须为 360°。"],["由百分比求具体数量","已知总数和某部分所占的百分比，就能求出该部分的具体数量。","扇形统计图本身不能直接读出数量，必须已知总数。"],["组数的确定","用最大值与最小值的差除以组距，结果取不小于它的最小整数就是组数。","组数要取整数；各组频数之和等于数据总数。"]]},{"type":"note","title":"例题","text":"某校共有 1200 名学生，为了解学生的课外锻炼情况，随机调查了部分学生并把结果绘制成扇形统计图，其中「每天锻炼 1 小时以上」的学生占 25%。请估计全校有多少名学生每天锻炼 1 小时以上。"},{"type":"figure","figure":{"id":"fig-sta-tjt-e1","title":"由扇形图的百分比求人数","caption":"扇形图给出 25%，乘全校总人数 1200 就得到具体人数","view":"square","alt":"一个圆形统计图，其中「每天锻炼 1 小时以上」所占的扇形高亮并标着 25%，下方注明全校共有 1200 名学生，用它乘 25% 得 300 人","prims":[{"t":"text","x":50,"y":12,"text":"每天锻炼 1 小时以上占 25%","size":3},{"t":"sector","cx":50,"cy":46,"r":28,"from":0,"to":90,"tone":"accent","fill":true,"label":"25%"},{"t":"sector","cx":50,"cy":46,"r":28,"from":90,"to":360,"tone":"muted"},{"t":"circle","cx":50,"cy":46,"r":28,"tone":"main"},{"t":"dot","x":50,"y":46,"r":1.4},{"t":"text","x":50,"y":84,"text":"全校共 1200 名学生，求这一部分的人数","size":3},{"t":"text","x":50,"y":94,"text":"1200 × 25% = 300（人）","size":3.4,"tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["从扇形统计图读取该部分所占的百分比：25%。","确定总数：全校共有 1200 名学生。","求具体数量：1200× 25%=1200× 0.25=300（人）。"]},{"type":"p","text":"答案：估计全校约有 300 名学生每天锻炼 1 小时以上。"},{"type":"note","title":"方法小结","text":"扇形统计图给出的是百分比，不能直接读出人数，求具体数量必须乘总数。这里是用样本的百分比估计全校的情况。"},{"type":"note","title":"例题","text":"某班 40 名学生一分钟跳绳次数的频数分布直方图中，100≤ x<120 这一组的频数是 12。求这一组所占的百分比，以及该组在扇形统计图中所对圆心角的度数。"},{"type":"figure","figure":{"id":"fig-sta-tjt-e2","title":"由直方图读某一组的频数","caption":"从直方图读出 100≤x<120 这一组有 12 人，全班共 40 人","view":"square","alt":"一个频数分布直方图，横轴是 80 到 180 的五组跳绳次数区间，纵轴是频数；五组频数依次是 6、12、14、6、2，其中 100≤x<120 这一组用醒目颜色标出、频数为 12，下方注明该组占 12 除以 40 等于 30%、圆心角是 360 度乘 30% 等于 108 度","prims":[{"t":"text","x":50,"y":12,"text":"某班 40 名学生一分钟跳绳次数","size":3},{"t":"axis","x":18,"y":74,"w":70,"h":48,"xLabel":"次数","yLabel":"频数","origin":true,"xTicks":[{"at":0,"label":"80"},{"at":0.2,"label":"100"},{"at":0.4,"label":"120"},{"at":0.6,"label":"140"},{"at":0.8,"label":"160"},{"at":1,"label":"180"}],"yTicks":[{"at":0,"label":"0"},{"at":0.33,"label":"5"},{"at":0.67,"label":"10"},{"at":1,"label":"15"}]},{"t":"rect","x":18,"y":54.8,"w":14,"h":19.2},{"t":"rect","x":32,"y":35.6,"w":14,"h":38.4,"tone":"accent","fill":true},{"t":"rect","x":46,"y":29.2,"w":14,"h":44.8},{"t":"rect","x":60,"y":54.8,"w":14,"h":19.2},{"t":"rect","x":74,"y":67.6,"w":14,"h":6.4},{"t":"text","x":25,"y":52.2,"text":"6","size":3},{"t":"text","x":39,"y":33,"text":"12","size":3,"tone":"accent"},{"t":"text","x":53,"y":26.6,"text":"14","size":3},{"t":"text","x":67,"y":52.2,"text":"6","size":3},{"t":"text","x":81,"y":65,"text":"2","size":3},{"t":"text","x":50,"y":93,"text":"该组占 12 ÷ 40 = 30%，圆心角 = 360° × 30% = 108°","size":2.7,"tone":"accent"}]}},{"type":"list","title":"解题步骤","items":["确定数据总数与该组频数：总人数 n=40，该组频数 m=12。","求百分比：(12)/(40)× 100%=30%。","求圆心角：360°× 30%=108°。"]},{"type":"p","text":"答案：这一组占全班人数的 30%，在扇形统计图中所对的圆心角是 108°。"},{"type":"note","title":"方法小结","text":"检验时把各组百分比相加应为 100%，把各扇形圆心角相加应为 360°。"},{"type":"note","title":"例题","text":"某公司用条形统计图比较甲、乙两个部门某月的销售额，纵轴从 80 万元开始，甲部门 92 万元，乙部门 88 万元，图中甲部门条形的高度看起来约是乙部门的 1.5 倍。请说明这幅统计图存在的问题及正确画法。"},{"type":"figure","figure":{"id":"fig-m-sta-tu-1","title":"同一组数据的两种画法对比","caption":"左图纵轴从 80 万起，差距被夸大；右图纵轴从 0 起，高度才与销售额成正比","view":"wide","alt":"两幅条形统计图对比：左图纵轴从 80 万元开始，甲 92 万元与乙 88 万元的条形看起来相差很大；右图纵轴从 0 开始，两个条形高度接近","prims":[{"t":"text","x":25,"y":12,"text":"纵轴从 80 起：差距被夸大","size":3.2,"anchor":"middle","tone":"accent"},{"t":"axis","x":8,"y":62,"w":34,"h":40,"xLabel":"部门","yLabel":"销售额（万元）","origin":false,"xTicks":[{"at":0.29,"label":"甲"},{"at":0.71,"label":"乙"}],"yTicks":[{"at":0,"label":"80"},{"at":0.33,"label":"85"},{"at":0.67,"label":"90"},{"at":1,"label":"95"}]},{"t":"rect","x":13,"y":30,"w":10,"h":32,"fill":true},{"t":"rect","x":27,"y":40.7,"w":10,"h":21.3},{"t":"text","x":18,"y":27.5,"text":"92 万","size":3,"anchor":"middle"},{"t":"text","x":32,"y":38.2,"text":"88 万","size":3,"anchor":"middle"},{"t":"text","x":73,"y":12,"text":"纵轴从 0 起：高度成正比","size":3.2,"anchor":"middle"},{"t":"axis","x":56,"y":62,"w":34,"h":40,"xLabel":"部门","yLabel":"销售额（万元）","origin":true,"xTicks":[{"at":0.29,"label":"甲"},{"at":0.71,"label":"乙"}],"yTicks":[{"at":0,"label":"0"},{"at":0.25,"label":"25"},{"at":0.5,"label":"50"},{"at":0.75,"label":"75"},{"at":1,"label":"100"}]},{"t":"rect","x":61,"y":25.2,"w":10,"h":36.8,"fill":true},{"t":"rect","x":75,"y":26.8,"w":10,"h":35.2},{"t":"text","x":66,"y":22.7,"text":"92 万","size":3,"anchor":"middle"},{"t":"text","x":80,"y":24.3,"text":"88 万","size":3,"anchor":"middle"},{"t":"text","x":50,"y":80,"text":"实际相差 4 万元，约 4.5%，远没有左图看起来那么大","size":3.2,"anchor":"middle","tone":"muted"}]}},{"type":"list","title":"解题步骤","items":["读图上的高度：甲的高度是 92-80=12，乙的高度是 88-80=8，两者之比为 12:8=1.5:1，所以看起来甲比乙高出 50%。","看实际数据：92-88=4（万元），相对差只有 (4)/(88)≈ 4.5%。","判断问题：纵轴起点不是 0，使图上高度的差距被夸大，容易让读者误认为两部门销售额相差很大。","正确画法：把纵轴从 0 开始，刻度间隔保持均匀，这样条形的高度才与销售额成正比。"]},{"type":"p","text":"答案：这幅统计图的纵轴没有从 0 开始，夸大了甲、乙两部门销售额的差距，属于统计图误读。正确画法是把纵轴从 0 开始、刻度间隔均匀。"},{"type":"note","title":"方法小结","text":"读条形统计图时先看纵轴起点是否为 0，再比较条形高度；比较实际差距要用数据本身，而不是图上的「视觉差距」。"},{"type":"note","title":"例题","text":"某中学为了解学生最喜爱的球类运动，随机抽取部分学生进行问卷调查（每人只选一项），调查结果绘制成两幅尚不完整的统计图：条形图中最喜爱篮球的有 80 人，扇形图中篮球占 40%，足球占 25%，乒乓球有 60 人，其余选「其他」。求被调查的总人数、最喜爱足球和「其他」的人数，以及乒乓球和「其他」各占的百分比。"},{"type":"figure","figure":{"id":"fig-m-sta-tu-2","title":"球类喜爱情况条形图与扇形图","caption":"篮球 80 人且占 40% 可求出总数 200 人，足球 50 人占 25%，乒乓球 60 人占 30%，其他 10 人占 5%","view":"wide","alt":"左边条形图：篮球 80 人、足球 50 人、乒乓球 60 人、其他 10 人；右边扇形图：篮球 40%、足球 25%、乒乓球 30%、其他 5%，总数 200 人","prims":[{"t":"axis","x":8,"y":64,"w":40,"h":44,"xLabel":"球类","yLabel":"人数","origin":true,"xTicks":[{"at":0.13,"label":"篮球"},{"at":0.38,"label":"足球"},{"at":0.63,"label":"乒乓球"},{"at":0.88,"label":"其他"}],"yTicks":[{"at":0,"label":"0"},{"at":0.33,"label":"30"},{"at":0.67,"label":"60"},{"at":1,"label":"90"}]},{"t":"rect","x":10,"y":24.9,"w":6,"h":39.1,"fill":true},{"t":"rect","x":20,"y":39.6,"w":6,"h":24.4},{"t":"rect","x":30,"y":34.7,"w":6,"h":29.3},{"t":"rect","x":40,"y":59.1,"w":6,"h":4.9},{"t":"text","x":13,"y":22.4,"text":"80","size":3,"anchor":"middle"},{"t":"text","x":23,"y":37.1,"text":"50","size":3,"anchor":"middle"},{"t":"text","x":33,"y":32.2,"text":"60","size":3,"anchor":"middle"},{"t":"text","x":43,"y":56.6,"text":"10","size":3,"anchor":"middle"},{"t":"circle","cx":74,"cy":40,"r":20},{"t":"line","x1":74,"y1":40,"x2":94,"y2":40},{"t":"line","x1":74,"y1":40,"x2":57.8,"y2":28.2},{"t":"line","x1":74,"y1":40,"x2":62.2,"y2":56.2},{"t":"line","x1":74,"y1":40,"x2":93,"y2":46.2},{"t":"text","x":77.7,"y":28.6,"text":"40%","size":3.2,"anchor":"middle","tone":"accent"},{"t":"text","x":62.1,"y":41.9,"text":"25%","size":3.2,"anchor":"middle"},{"t":"text","x":77.7,"y":51.4,"text":"30%","size":3.2,"anchor":"middle"},{"t":"text","x":86.5,"y":36,"text":"5%","size":3.2,"anchor":"middle"},{"t":"text","x":74,"y":68,"text":"共 200 人","size":3.2,"anchor":"middle"}]}},{"type":"list","title":"解题步骤","items":["由篮球的人数与所占百分比求被调查的总人数：80÷ 40%=200（人）。","求最喜爱足球的人数：200× 25%=50（人）。","求「其他」的人数：200-80-50-60=10（人）。","求乒乓球与「其他」所占百分比：乒乓球 (60)/(200)× 100%=30%，「其他」(10)/(200)× 100%=5%。检验：40%+25%+30%+5%=100%。"]},{"type":"p","text":"答案：被调查的总人数为 200 人；最喜爱足球的有 50 人，「其他」有 10 人；乒乓球占 30%，「其他」占 5%。"},{"type":"note","title":"方法小结","text":"两幅不完整统计图互补的关键是先找到「既知数量又知百分比」的那一组求出总数，其余各组再围绕总数计算，最后用百分比之和为 100% 自检。"},{"type":"note","title":"例题","text":"某校抽取 40 名学生测试一分钟跳绳次数，把成绩分成五组绘制成频数分布直方图，各组频数依次为：50≤ x<60 有 4 人，60≤ x<70 有 8 人，70≤ x<80 有 14 人，80≤ x<90 有 10 人，90≤ x≤ 100 有 4 人。求这组数据的中位数落在哪一组，并估计成绩不低于 80 次的学生所占的百分比。"},{"type":"figure","figure":{"id":"fig-sta-tjt-e5","title":"跳绳成绩的频数分布直方图","caption":"五组频数依次为 4、8、14、10、4，中间位置落在 70≤x<80 这一组","view":"square","alt":"一个频数分布直方图，横轴是 50 到 100 的五组跳绳次数区间，纵轴是频数；五组频数依次为 4、8、14、10、4，共 40 人；70≤x<80 这一组用正确颜色标出表示中位数所在组，80≤x<90 与 90≤x≤100 这两组用醒目颜色标出表示不低于 80 次，下方注明中位数落在 70≤x<80，不低于 80 的占 35%","prims":[{"t":"text","x":50,"y":12,"text":"40 名学生一分钟跳绳次数分组情况","size":3},{"t":"axis","x":18,"y":74,"w":70,"h":48,"xLabel":"次数","yLabel":"频数","origin":true,"xTicks":[{"at":0,"label":"50"},{"at":0.2,"label":"60"},{"at":0.4,"label":"70"},{"at":0.6,"label":"80"},{"at":0.8,"label":"90"},{"at":1,"label":"100"}],"yTicks":[{"at":0,"label":"0"},{"at":0.33,"label":"5"},{"at":0.67,"label":"10"},{"at":1,"label":"15"}]},{"t":"rect","x":18,"y":61.2,"w":14,"h":12.8},{"t":"rect","x":32,"y":48.4,"w":14,"h":25.6},{"t":"rect","x":46,"y":29.2,"w":14,"h":44.8,"tone":"ok","fill":true},{"t":"rect","x":60,"y":42,"w":14,"h":32,"tone":"accent","fill":true},{"t":"rect","x":74,"y":61.2,"w":14,"h":12.8,"tone":"accent","fill":true},{"t":"text","x":25,"y":58.6,"text":"4","size":3},{"t":"text","x":39,"y":45.8,"text":"8","size":3},{"t":"text","x":53,"y":26.6,"text":"14","size":3,"tone":"ok"},{"t":"text","x":67,"y":39.4,"text":"10","size":3,"tone":"accent"},{"t":"text","x":81,"y":58.6,"text":"4","size":3,"tone":"accent"},{"t":"text","x":50,"y":93,"text":"中位数落在 70≤x<80；不低于 80 的占 (10+4)÷40 = 35%","size":2.6}]}},{"type":"list","title":"解题步骤","items":["检验频数之和：4+8+14+10+4=40，与被抽取的学生人数一致。","确定中位数的位置：40 个数据按从小到大排列，中位数是第 20、21 两个数据的平均数。","累计前两组频数为 4+8=12，累计前三组频数为 12+14=26，第 20、21 个数据都落在 70≤ x<80 这一组，所以中位数落在该组。","成绩不低于 80 次的有 10+4=14 人，所占百分比为 (14)/(40)× 100%=35%。"]},{"type":"p","text":"答案：中位数落在 70≤ x<80 这一组；估计成绩不低于 80 次的学生占 35%。"},{"type":"note","title":"方法小结","text":"用频数分布表确定中位数落在哪一组，要先算累计频数，看中间位置夹在哪两组的累计频数之间；估计百分比时注意「不低于 80」包含 80 这一组。"},{"type":"list","title":"易错点","items":["条形统计图的纵轴必须从 0 开始，否则会夸大各类别之间的差距，造成误读。","扇形统计图只反映各部分所占的百分比，不能直接读出具体数量；求数量必须用「总数 × 百分比」。","扇形统计图中各部分百分比之和必须是 100%，各扇形圆心角之和必须是 360°，否则数据本身有问题。","读折线统计图要结合横轴的含义和纵轴刻度：趋势看起来陡峭不代表数量变化大，纵轴刻度不同，陡峭程度会变化。","频数分布直方图用于表示连续数据，各矩形等宽且紧密相连；条形统计图的条形之间有间隔，两者不能混为一谈。","用样本数据推断总体时要注意样本是否随机抽取、容量是否足够，只调查一部分人却当作全体结论会失真。"]},{"type":"list","title":"解题方法","items":["按分析目的选图：比较各类别数量用条形统计图，看变化趋势用折线统计图，看部分与总体的比例用扇形统计图，看连续数据的分布用频数分布直方图。","扇形统计图三类计算：百分比 = 频数 ÷ 总数，圆心角 =360°× 百分比，具体数量 = 总数 × 百分比。","直方图读数：先看组距和组数，把各组频数相加得到数据总数，再由某组频数求出它的频率或百分比。","识别误读：先检查纵轴是否从 0 开始，再看是否用面积或立体效果夸大差异，最后检查百分比之和是否为 100%。","用样本估计总体：先确认样本随机且有代表性，再用样本的百分比或平均数乘总体数量作出估计。"]}],"questions":[{"id":"q-sta-tu-1","type":"choice","stem":"要反映某市近几年常住人口数量的变化趋势，最合适的统计图是（ ）","answer":"B","explain":"折线统计图用折线连接各数据点，最能反映数据随时间变化的趋势，所以选 B。条形统计图适合比较各类别的数量，扇形统计图适合看部分与总体的比例，频数分布直方图适合看连续数据的分布情况。","options":["条形统计图","折线统计图","扇形统计图","频数分布直方图"],"difficulty":1,"tags":["统计图选择","折线统计图"]},{"id":"q-sta-tu-2","type":"fill","stem":"在扇形统计图中，某部分所对的圆心角是 90°，则该部分占总体的百分比是＿＿。","answer":"25%","explain":"该部分所占的百分比为 90°360°=0.25=25%。也可以用圆心角公式 360°× 百分比 =90° 反推得到 25%。","difficulty":1,"tags":["扇形统计图","圆心角"]},{"id":"q-sta-tu-3","type":"choice","stem":"某校共有 800 名学生，扇形统计图中「步行上学」的学生占 35%，则步行上学的学生人数是（ ）","answer":"B","explain":"由「具体数量 = 总数 × 百分比」得 800× 35%=800× 0.35=280（人）。选 35 是把百分比直接当成了人数，扇形统计图不能直接读出具体数量。","options":["35","280","350","800"],"difficulty":1,"tags":["扇形统计图","求具体数量"]},{"id":"q-sta-tu-4","type":"choice","stem":"关于统计图的使用，下列说法正确的是（ ）","answer":"C","explain":"折线统计图用折线连接数据点，便于反映变化趋势，C 正确。扇形统计图只给出百分比，不能直接读出数量，A 错；条形统计图的纵轴不从 0 开始会夸大差异，属于误读，B 错；频数分布直方图用于连续数据，各矩形之间没有空隙，D 错。","options":["扇形统计图能直接看出各部分的具体数量","条形统计图的纵轴可以不从 0 开始，以便突出差异","折线统计图便于反映数据的变化趋势","频数分布直方图的各矩形之间应当留有空隙"],"difficulty":2,"tags":["统计图选择","统计图误读"]},{"id":"q-sta-tu-5","type":"short","stem":"某商场把 1 月份和 2 月份的销售额画成条形统计图，纵轴从 100 万元开始。1 月份销售额 110 万元，2 月份销售额 120 万元，图上 2 月份的条形高度看起来是 1 月份的 2 倍。请指出这幅统计图存在的问题，并说明正确的画法。","answer":"图上的条形高度是按纵轴刻度画的：1 月份的高度为 110-100=10，2 月份的高度为 120-100=20，所以看起来 2 月份是 1 月份的 2 倍。但实际销售额只相差 120-110=10（万元），相对差只有 (10)/(110)≈ 9%，差距很小。问题在于纵轴起点不是 0，把两个月的差距放大了，容易造成误读。正确画法是把纵轴从 0 开始，刻度间隔保持均匀，使条形的高度与实际销售额成正比。","explain":"条形统计图是用高度表示数量的，只有纵轴从 0 开始，高度之比才等于数量之比。纵轴起点不为 0 时，图上高度的比值会被放大，属于典型的统计图误读。","difficulty":2,"tags":["条形统计图","统计图误读","实际情境"],"rubric":["指出图上高度差距是由纵轴起点不是 0 造成的","算出实际相差约 9%，说明实际差距不大","说明正确画法是纵轴从 0 开始、刻度间隔均匀"]},{"id":"q-sta-tu-z1","type":"choice","stem":"下列关于频数分布直方图的说法，正确的是（ ）","answer":"A","explain":"频数分布直方图中各组组距相等，各小长方形等宽且紧密相连，没有空隙，A 正确、B 错；等组距时小长方形的高表示各组的频数，不是频率，C 错；各组频数之和等于数据总数，没有固定等于 100 的结论，D 错。","options":["各小长方形的宽度相等，都等于组距","各小长方形之间应当留有空隙","小长方形的高表示各组数据的频率","所有小长方形的面积之和等于 100"],"difficulty":2,"tags":["频数分布直方图"]},{"id":"q-sta-tu-z2","type":"short","stem":"下列三组数据分别适合用哪种统计图表示？请说明理由。（1）某地一天中不同时刻气温的记录，要反映气温随时间的变化；（2）图书馆上周各类图书借阅的数量，要比较多少；（3）小丽家某月各项生活支出占总支出的比例。","answer":"（1）选用折线统计图，因为折线统计图最能反映数据随时间变化的趋势；（2）选用条形统计图，因为条形的高度便于比较各类图书借阅数量的多少；（3）选用扇形统计图，因为扇形统计图能清楚地表示各项支出占总支出的百分比，即部分与总体的关系。","explain":"选择统计图的依据是分析目的：看变化趋势用折线图，比较各类别数量用条形图，看各部分占总体的比例用扇形图。只写出图名不说明理由会被扣掉理由分。","difficulty":2,"tags":["统计图选择"],"rubric":["气温随时间变化选折线统计图，并说明反映变化趋势","比较借阅数量多少选条形统计图，并说明便于比较数量","支出占比选扇形统计图，并说明反映部分与总体的关系"]}]}];
